def prove_sottocategorie():
    """L'albero DORMIENTE (ago 2026): definito nel catalogo, mostrato
    da nessuna parte. Le prove difendono il patto scritto sopra
    SOTTOCATEGORIE: id per sempre, unici in TUTTO l'albero (un domani
    un filtro senza categoria non dev'essere ambiguo), niente voci
    «Altro X», e un giudice che non lascia passare niente di storto."""
    print("\n[sottocategorie]")
    amb = {}
    i = _SORGENTE.index("CATEGORIE = (")
    exec(_SORGENTE[i:_SORGENTE.index(")", i) + 1], amb)
    i = _SORGENTE.index("SOTTOCATEGORIE = {")
    exec(_SORGENTE[i:_SORGENTE.index("\n}", i) + 2], amb)
    albero = amb["SOTTOCATEGORIE"]
    cat = list(amb["CATEGORIE"])

    prova("ogni chiave dell'albero e' una categoria vera", [],
          [c for c in albero if c not in cat])
    prova("«Altro» resta piatta per forza", False, "Altro" in albero)
    tutti = [sid for voci in albero.values() for sid, _ in voci]
    prova("id unici in TUTTO l'albero", len(tutti), len(set(tutti)))
    import re
    prova("id kebab-case, mai vuoti", [],
          [s for s in tutti if not re.fullmatch(r"[a-z0-9]+(-[a-z0-9]+)*", s)])
    prova("nessuna voce si chiama «altro»", [],
          [(sid, nome) for voci in albero.values() for sid, nome in voci
           if "altro" in sid or nome.strip().lower().startswith("altro")])
    prova("nessuna etichetta vuota o doppia nella stessa categoria", [],
          [c for c, voci in albero.items()
           if len({n for _, n in voci}) != len(voci)
           or any(not n.strip() for _, n in voci)])

    for f in ("sottocategoria_valida", "sottocategoria_tollerante"):
        exec(pezzo(f), amb)
    valida = amb["sottocategoria_valida"]
    prova("una voce valida passa", "mtb", valida("Biciclette", "mtb"))
    prova("una voce di un'ALTRA categoria non passa", "",
          valida("Biciclette", "gift-card"))
    prova("una voce inventata non passa", "", valida("Biciclette", "carbonio"))
    prova("il vuoto resta vuoto", "", valida("Biciclette", ""))
    prova("None non esplode", "", valida("Biciclette", None))
    prova("una categoria piatta non ha voci", "", valida("Altro", "mtb"))
    prova("una categoria inventata non ha voci", "",
          valida("Fantacategoria", "mtb"))

    tollera = amb["sottocategoria_tollerante"]
    prova("il CSV che dice l'id viene capito", "ebike",
          tollera("Biciclette", "ebike"))
    prova("il CSV che dice l'ETICHETTA viene capito", "ebike",
          tollera("Biciclette", "E-BIKE"))
    prova("l'etichetta con gli spazi viene capita", "olio-condimenti",
          tollera("Alimenti e bevande", "Olio e condimenti"))
    prova("una voce storta e' '' e mai uno scarto", "",
          tollera("Biciclette", "bici volante"))

    # --- il giudice SILENZIOSO (ago 2026): parole chiave dentro la
    # categoria gia' scelta. La proprieta' che le prove difendono e'
    # l'ASTENSIONE: sul dubbio risponde '', mai un'assegnazione tirata
    # a indovinare.
    amb["re"], amb["unicodedata"] = __import__("re"), \
        __import__("unicodedata")
    i = _SORGENTE.index("SINONIMI_SOTTOCATEGORIA = {")
    exec(_SORGENTE[i:_SORGENTE.index("\n}", i) + 2], amb)
    for f in ("normalizza", "_parola_sottocategoria",
              "sottocategoria_indovina"):
        exec(pezzo(f), amb)
    sin = amb["SINONIMI_SOTTOCATEGORIA"]
    prova("il dizionario parla solo di categorie vere", [],
          [c for c in sin if c not in albero])
    prova("ogni voce del dizionario esiste nell'albero", [],
          [(c, v) for c, voci in sin.items() for v in voci
           if v not in {sid for sid, _ in albero[c]}])
    prova("ogni voce dell'albero ha le sue parole", [],
          [(c, sid) for c, voci in albero.items() for sid, _ in voci
           if sid not in sin.get(c, {})])

    g = amb["sottocategoria_indovina"]
    prova("il poster si riconosce", "poster-stampe",
          g("Bitcoin", 'Poster A1 "White Paper"', ""))
    prova("il titolo pesa doppio (il Buono soggiorno)",
          "soggiorni-esperienze",
          g("Buoni ed esperienze", "Buono soggiorno due notti", ""))
    prova("il pareggio e' un dubbio e il dubbio resta ''", "",
          g("Bitcoin", "poster wallet", ""))
    prova("'auto' non prende 'autoradio'", "",
          g("Motori", "Autoradio Pioneer", ""))
    prova("il prefisso lungo invece lavora", "outdoor",
          g("Sport e hobby", "kit per escursioni", ""))
    prova("senza parole si astiene", "",
          g("Libri e media", "bitcoin standard", "nuovo"))
    prova("una categoria piatta non giudica", "",
          g("Altro", "Poster bellissimo", ""))
    prova("gli accenti non contano", "cucina-tavola",
          g("Casa e giardino", "Caffettièra anni 60", ""))
    # il caso vero che ha fatto nascere «Mare e piscina» (ago 2026):
    # un telo da MARE in una categoria giusta senza una voce che lo
    # accogliesse. Il titolo normalizzato da' il token «amare», non
    # «mare»: a prenderlo dev'essere «telo».
    prova("il Telo d'Amare trova la sua voce", "mare-piscina",
          g("Sport e hobby", "III° Telo d'Amare, del (primo) trittico "
                            "2026", "canapa antica sulla spoletta di "
                                    "tessitura"))
    prova("e «amare» da solo non accende «mare»", "",
          g("Sport e hobby", "Imparare ad amare", ""))


# ====================================================================
def prove_ricategorizza():
    """Lo script di ricategorizzazione legge il catalogo da server.py
    (fonte unica) e non si fida delle risposte dell'AI: un «NON SO» o
    una categoria inventata devono lasciare l'annuncio dov'e'."""
    print("\n[ricategorizzazione]")
    import ricategorizza as ric

    cat = ric.catalogo()
    j = _SORGENTE.index("CATEGORIE = (")
    amb = {}
    exec(_SORGENTE[j:_SORGENTE.index(")", j) + 1], amb)
    prova("lo script legge il catalogo vero", list(amb["CATEGORIE"]), cat)

    leggi = lambda riga: (ric.RIGA.match(riga).groups()
                          if ric.RIGA.match(riga) else None)
    prova("verdetto normale", ("3", "Informatica"), leggi("3: Informatica"))
    prova("verdetto con la parentesi", ("12", "Alimenti e bevande"),
          leggi(" 12) Alimenti e bevande "))
    prova("«NON SO» non e' una categoria del catalogo", False,
          leggi("7: NON SO")[1] in cat)
    prova("una categoria inventata non e' nel catalogo", False,
          leggi("7: Fantacategoria")[1] in cat)
    prova("una riga di chiacchiere non e' un verdetto", None,
          leggi("Ecco i risultati:"))

    # LA REGOLA «BITCOIN» E' TEMATICA (ago 2026): 19 proposte in
    # produzione, e UNDICI erano annunci da tirare fuori da «Bitcoin»
    # — sacche, poster cypherpunk, magliette. Non era il modello a
    # disobbedire: il prompt insegnava «hardware e nodi» con quattro
    # esempi tutti apparecchi, mentre l'albero delle sottocategorie ha
    # «merch» e «poster-stampe» sotto Bitcoin da quando e' stato
    # disegnato. Qui si e' corretta una premessa parziale, mai
    # inseguito il modello (la regola di casa).
    prova("la regola «Bitcoin» dice TEMATICO", True,
          "reparto TEMATICO" in ric.PROMPT)
    # La coppia delle due magliette e' la parte che insegna (la
    # lezione bici/cuffie: gli esempi insegnano il confine piu' della
    # regola astratta) — un riordino la toglierebbe per prima,
    # sembrando una ripetizione.
    prova("...e tiene la coppia delle due magliette", True,
          "una maglietta col logo bitcoin e' «Bitcoin»" in ric.PROMPT
          and "maglietta qualunque e' «Abbigliamento»" in ric.PROMPT)
    # L'unica clausola del testo vecchio che funzionava, e RESTA.
    prova("...e la clausola sull'elettronica resta", True,
          "elettronica generica" in ric.PROMPT)
    # IL PRIMO GIRO VERO DEL COLLAUDO (ago 2026): 13/14 due volte, a
    # cadere la SACCA «col logo Bitcoin» — il modello leggeva la
    # formula come proprieta' delle magliette, perche' viveva solo
    # nella coppia (il simbolo ₿ invece lo riconosceva). La cura e'
    # questa riga, mirata: la regola non si allarga.
    prova("...e la coppia vale per ogni oggetto (la sacca)", True,
          "La coppia vale per OGNI oggetto" in ric.PROMPT
          and "anche una sacca o una tazza col logo bitcoin sono "
              "«Bitcoin»" in ric.PROMPT
          and "sia come simbolo ₿ sia scritto a parole" in ric.PROMPT)
    # IL SECONDO GIRO (ago 2026, dal campo): la regola tematica
    # assorbiva troppo — tre «Sat's Oil» da Alimenti a Bitcoin per il
    # «Sat» nel nome, e il «Manifesto Hacker» spinto verso Arte. La
    # contro-regola e' quella gia' pagata dal prompt della
    # moderazione: una somiglianza di nome non e' mai un motivo.
    prova("...e il nome non e' il tema (il secondo giro)", True,
          "il tema dev'essere L'OGGETTO, non il nome del prodotto"
          in ric.PROMPT)
    prova("...e il poster a tema non migra verso Arte", True,
          "poster cypherpunk resta «Bitcoin»" in ric.PROMPT)
    # IL TERZO GIRO (ago 2026, dal campo): una consulenza sui wallet
    # restava in «Bitcoin» — lo stesso pendolo del Sat's Oil ma
    # sull'altro asse: il tema batteva l'OGGETTO quando l'oggetto e'
    # una prestazione. La regola sta in una voce SUA perche' vale per
    # ogni argomento, non solo per Bitcoin.
    prova("le prestazioni battono il tema (il terzo giro)", True,
          "Le PRESTAZIONI battono il tema" in ric.PROMPT)
    prova("...con la coppia consulenza/hardware wallet", True,
          "Una consulenza su bitcoin e' «Lezioni e corsi»" in ric.PROMPT
          and "un hardware wallet e' «Bitcoin»" in ric.PROMPT)
    # IL QUARTO GIRO (ago 2026, dal campo: un abbonamento Spotify in
    # «Informatica»). Il buco non era una regola sbagliata ma una
    # regola ASSENTE: «Buoni ed esperienze» era nell'elenco delle
    # categorie ammesse e nessuna riga ci portava. Questa prova e'
    # anche il censimento che lo impedisce di nuovo — se un domani
    # una categoria nuova restasse senza una riga sua, e' qui che si
    # viene a leggere perche'.
    prova("i crediti hanno la loro regola (il quarto giro)", True,
          "Un CREDITO da spendere presso un altro e' «Buoni ed "
          "esperienze»" in ric.PROMPT)
    # La coppia che insegna il confine, come le due magliette: un
    # riordino la toglierebbe per prima sembrando una ripetizione.
    prova("...con la coppia abbonamento/corso", True,
          "Un abbonamento Spotify di 3 mesi e' «Buoni ed esperienze»"
          in ric.PROMPT
          and "un corso di chitarra di 3 mesi e' «Lezioni e corsi»"
          in ric.PROMPT)
    # LA CONTRO-REGOLA E' LA META' CHE CONTA, ed e' la gemella di
    # quella di Bitcoin («MA il tema dev'essere L'OGGETTO»): senza,
    # «credito» assorbe tutto cio' che arriva come codice — licenze e
    # videogiochi compresi — e il reparto smette di dire qualcosa.
    # Le due punte si guardano separate: nominate insieme in un `and`
    # unico, la mutazione che ne toglie una sola resterebbe verde.
    prova("...e il credito dev'essere il PRODOTTO", True,
          "MA il credito dev'essere il PRODOTTO" in ric.PROMPT)
    prova("...con la punta della licenza", True,
          "una licenza Office e' «Informatica»" in ric.PROMPT)
    prova("...e quella del videogioco", True,
          "la chiave di UN videogioco e' «Console e videogiochi»"
          in ric.PROMPT)
    # IL PRIMO GIRO VERO (ago 2026): 18/19 due volte, a cadere sempre
    # e solo il Game Pass. La regola diceva «abbonamenti a
    # piattaforme» col solo esempio Spotify — musica — mentre la
    # contro-regola aveva un esempio esplicito di videogiochi: sul
    # terreno dei giochi l'unico appiglio diceva «Console e
    # videogiochi». E' la forma della SACCA, e la cura e' mirata
    # come quella: la regola vale su qualunque argomento, la
    # contro-regola stringe sul gioco SINGOLO.
    prova("gli abbonamenti valgono su ogni argomento (il quinto giro)",
          True, "QUALUNQUE sia l'argomento: musica, video, "
                "videogiochi, software" in ric.PROMPT)
    prova("...e la differenza e' fra la COSA e l'ACCESSO", True,
          "La differenza e' fra la COSA e l'ACCESSO" in ric.PROMPT
          and "un abbonamento che apre un CATALOGO resta un credito"
          in ric.PROMPT)
    # LA RIGA DA NON AMMORBIDIRE: nel prompt non entra nessun marchio
    # dei due casi di collaudo, o quei casi diventano tautologie —
    # il modello imparerebbe il nome invece della regola (la lezione
    # della birra, gia' pagata dal secondo giro).
    prova("il prompt non nomina i marchi dei casi (mai tautologie)",
          [], [m for m in ("Game Pass", "PlayStation", "PS Plus",
                           "Netflix", "Elden Ring", "Zalando", "Steam")
               if m in ric.PROMPT])


# ====================================================================
def prove_collaudo_ricategorizza():
    """IL COLLAUDO DEL PROMPT DI RICATEGORIZZA (ago 2026): il gemello
    di collaudo_impersonazione.py — e qui si fa meglio del fratello.
    Le sue sentinelle cercano l'atteso in una finestra di 400/500
    caratteri dopo il titolo, fragilita' che i documenti dichiarano: una
    descrizione piu' lunga spinge l'atteso fuori finestra e la prova
    diventa rossa per il motivo sbagliato. Questo collaudo si IMPORTA
    (il modello si chiama solo dentro main()), quindi la tabella si
    legge COME DATO. Nessuna finestra da tarare."""
    print("\n[il collaudo della ricategorizzazione]")
    import collaudo_ricategorizza as cr
    import ricategorizza as ric
    cat = ric.catalogo()

    prova("i venti casi ci sono (piano + dal secondo al quinto giro)",
          True, len(cr.CASI) >= 20)
    prova("ogni «ora sta in» e' una categoria vera del catalogo", [],
          [t for t, _, ora, _, _ in cr.CASI if ora not in cat])
    prova("ogni atteso e' una categoria vera del catalogo", [],
          [t for t, _, _, att, _ in cr.CASI if att not in cat])
    # Il caso AFFILATO: la maglietta qualunque sta in «Bitcoin» e deve
    # USCIRNE. Senza, «reparto tematico» diventerebbe «tutto quello
    # che qualcuno ci ha messo».
    prova("la maglietta qualunque esce da Bitcoin", True,
          any(ora == "Bitcoin" and att == "Abbigliamento"
              for _, _, ora, att, _ in cr.CASI))
    prova("...e il merch tematico ci RESTA", True,
          any(ora == "Bitcoin" and att == "Bitcoin"
              for _, _, ora, att, _ in cr.CASI))
    prova("...e l'elettronica generica esce (la clausola che resta)",
          True, any(ora == "Bitcoin" and att == "Elettronica"
                    for _, _, ora, att, _ in cr.CASI))
    prova("il NON SO ha il suo caso («Altro» che resta «Altro»)", True,
          any(ora == "Altro" and att == "Altro"
              for _, _, ora, att, _ in cr.CASI))
    # Il secondo giro: l'olio a tema resta olio — il nome non e' il
    # tema. Ancorata al caso di campo per NOME, non con un any()
    # generico: la birra gemella lo terrebbe verde anche se qualcuno
    # riscrivesse l'atteso del Sat's Oil su una categoria vera.
    prova("il Sat's Oil resta in Alimenti (il caso di campo)", True,
          any(t.startswith("Sat's Oil")
              and ora == "Alimenti e bevande"
              and att == "Alimenti e bevande"
              for t, _, ora, att, _ in cr.CASI))
    # Il terzo giro, ancorato al caso per NOME come il Sat's Oil: la
    # gemella del corso di cucina terrebbe verde un any() generico su
    # «Lezioni e corsi» anche con l'atteso della consulenza riscritto.
    prova("la consulenza sui wallet esce da Bitcoin (terzo giro)", True,
          any(t.startswith("Consulenza sui wallet")
              and ora == "Bitcoin" and att == "Lezioni e corsi"
              for t, _, ora, att, _ in cr.CASI))
    # Il quarto giro, ancorato al caso di campo per NOME come i due
    # sopra: la gemella del Game Pass terrebbe verde un any() generico
    # su «Buoni ed esperienze» anche con l'atteso dello Spotify
    # riscritto.
    prova("l'abbonamento Spotify esce da Informatica (quarto giro)",
          True, any(t.startswith("Abbonamento Spotify")
                    and ora == "Informatica"
                    and att == "Buoni ed esperienze"
                    for t, _, ora, att, _ in cr.CASI))
    # LE DUE PUNTE AFFILATE della contro-regola: stanno in «Buoni ed
    # esperienze» e devono USCIRNE, ognuna verso la sua categoria.
    # Senza, «credito» diventerebbe «tutto quello che arriva come
    # codice» — la stessa funzione che la maglietta qualunque ha per
    # il reparto tematico.
    prova("...e la licenza software ne esce verso Informatica", True,
          any(ora == "Buoni ed esperienze" and att == "Informatica"
              for _, _, ora, att, _ in cr.CASI))
    prova("...e la chiave del gioco verso Console e videogiochi", True,
          any(ora == "Buoni ed esperienze"
              and att == "Console e videogiochi"
              for _, _, ora, att, _ in cr.CASI))
    prova("...mentre il buono vero ci RESTA", True,
          any(ora == "Buoni ed esperienze"
              and att == "Buoni ed esperienze"
              for _, _, ora, att, _ in cr.CASI))
    # IL QUINTO GIRO: il Game Pass e' caduto due volte, quindi
    # diventa regressione permanente — e vuole la sua gemella,
    # perche' la cura ha dovuto toccare proprio il terreno dei
    # videogiochi. Ancorate per NOME come il Sat's Oil: con un any()
    # generico su «Buoni ed esperienze» una terrebbe verde l'altra.
    prova("il Game Pass esce da Console e videogiochi (quinto giro)",
          True, any(t.startswith("Game Pass")
                    and ora == "Console e videogiochi"
                    and att == "Buoni ed esperienze"
                    for t, _, ora, att, _ in cr.CASI))
    prova("...e la sua gemella che il prompt non nomina", True,
          any(t.startswith("PlayStation Plus")
              and ora == "Console e videogiochi"
              and att == "Buoni ed esperienze"
              for t, _, ora, att, _ in cr.CASI))
    # E la punta che NON si deve allargare: il gioco singolo resta
    # un prodotto. Se cadesse anche lei, la cura avrebbe fatto
    # collassare la contro-regola.
    prova("...mentre la chiave di UN gioco resta un prodotto", True,
          any(t.startswith("Elden Ring")
              and att == "Console e videogiochi"
              for t, _, _, att, _ in cr.CASI))
    # Il collaudo usa i pezzi VERI: un prompt in due copie e' un
    # prompt che diverge, e una copia di chiedi() pure.
    src = open("collaudo_ricategorizza.py", encoding="utf-8").read()
    prova("il collaudo importa chiedi() e catalogo() veri", True,
          "from ricategorizza import" in src)


