def prove_capitale_cassa():
    """IL CAPITALE NOSTRO SULLE DUE CASSEFORTI (set 2026): lo strumento
    che legge i due registri e il polso 23 del libro mastro, che da
    allora e' PER CASSAFORTE. Le sentinelle sulla forma — il database
    non si apre, la chiave che paga non si legge, il risolutore e' quello
    di orfani.py — il cuore su un registro di cartone, e il polso 23
    eseguito DAVVERO su un database gemello: una query sbagliata in un
    file .sql non fallisce, TACE."""
    print("\n[il capitale nostro, per cassaforte, e il polso 23]")
    import sqlite3 as sq
    import capitale_cassa as cc

    src = open("capitale_cassa.py", encoding="utf-8").read()
    # («import sqlite3» e non «sqlite3»: la parola sta anche nel comando
    # che lo script STAMPA per chi dichiara — vedi prove-che-rispondono)
    prova("capitale_cassa non apre il database", False,
          "import sqlite3" in src)
    prova("...e non legge mai la chiave che paga", False, "ADMIN_KEY" in src)
    prova("...e non paga: nessuna richiesta in uscita", False,
          '"out": True' in src)
    prova("le casseforti vengono da orfani.py, un posto solo", True,
          "from orfani import" in src and "def casseforti_leggibili" not in src)
    prova("una chiave di impostazioni per cassaforte",
          {"saas": "capitale_saas_sats", "nodo": "capitale_nodo_sats"},
          cc.CHIAVE)

    def mov(sats, memo, **stato):
        return {"amount": sats * 1000, "memo": memo, "time": 1700000000,
                **(stato or {"status": "success"})}
    c = cc.conta([mov(5000, "capitale di Andrea"),
                  mov(300, "Barattolo escrow #7: cosa"),
                  mov(900, "fattura mai pagata", status="pending"),
                  mov(-1200, "payout"),
                  mov(70, "")])
    prova("capitale = entrate riuscite senza memo nostro", [70, 5000],
          [s for _, s, _ in c["capitale"]])   # stessa ora: ordina per sats
    prova("...sommate", 5070, c["totale"])
    prova("il memo nostro e' mercatino, non capitale", 300, c["mercatino"])
    prova("la fattura mai pagata non conta", False,
          any(m == "fattura mai pagata" for _, _, m in c["capitale"]))
    prova("le uscite si elencano tutte", [-1200],
          [s for _, s, _ in c["uscite"]])

    # --- il polso 23, eseguito su un database gemello ----------------
    sql = open("query_libro_mastro.sql", encoding="utf-8").read()
    blocco = sql[sql.index("SELECT '23)"):sql.index("SELECT '23b)")]
    for vietato in ("INSERT INTO", "UPDATE ", "DELETE ", "DROP ", "CREATE "):
        prova(f"polso 23: nessun {vietato.strip()} fuori dai commenti", False,
              vietato in "\n".join(r for r in blocco.splitlines()
                                   if not r.lstrip().startswith("--")))
    q = blocco[blocco.index("WITH"):blocco.index("FROM conto;") + len("FROM conto;")]

    def gemello():
        con = sq.connect(":memory:")
        con.row_factory = sq.Row
        con.executescript("""
          CREATE TABLE ordini(id INTEGER PRIMARY KEY, annuncio_id INT,
            prezzo_sats INT, protezione_sats INT DEFAULT 0, stato TEXT,
            cassaforte TEXT DEFAULT 'saas');
          CREATE TABLE annunci(id INTEGER PRIMARY KEY,
            asta_base_sats INT DEFAULT 0);
          CREATE TABLE rilanci(id INTEGER PRIMARY KEY, puntata_id INT,
            delta_sats INT, stato TEXT, cassaforte TEXT DEFAULT 'saas');
          CREATE TABLE pagamenti(id INTEGER PRIMARY KEY, importo_sats INT,
            stato TEXT, cassaforte TEXT DEFAULT 'saas');
          CREATE TABLE rimborsi_asta(id INTEGER PRIMARY KEY, puntata_id INT,
            importo_sats INT, stato TEXT, cassaforte TEXT DEFAULT '');
          CREATE TABLE impostazioni(chiave TEXT PRIMARY KEY, valore TEXT);
          INSERT INTO annunci VALUES (1, 0), (2, 5000);
          -- saas: un released (1000, protezione 100), un rilancio saldato
          -- 200, un rimborso d'asta riscosso 50 con la colonna VUOTA che
          -- eredita dalla puntata; nodo: un locked 500, un banner 30
          INSERT INTO ordini VALUES (1, 1, 1000, 100, 'released', 'saas');
          INSERT INTO ordini VALUES (2, 1, 500, 0, 'locked', 'nodo');
          INSERT INTO ordini VALUES (3, 2, 9999, 0, 'locked', 'saas');
          INSERT INTO ordini VALUES (4, 1, 777, 0, 'creato', 'nodo');
          INSERT INTO rilanci VALUES (1, 11, 200, 'saldato', 'saas');
          INSERT INTO rimborsi_asta VALUES (1, 11, 50, 'riscosso', '');
          INSERT INTO pagamenti VALUES (1, 30, 'pagato', 'nodo');
        """)
        return con

    con = gemello()
    righe = [dict(r) for r in con.execute(q)]
    prova("una riga per cassaforte, saas prima", ["saas", "nodo"],
          [r["cassaforte"] for r in righe])
    s, n = righe
    prova("saas: l'ordine nato da un'asta non conta fra le entrate", 1000,
          s["in_escrow_ordini"])
    prova("saas: movimento = 1000 + 200 - 900 - 50", 250,
          s["movimento_mercatino"])
    prova("nodo: movimento = 500 + 30, il 'creato' fuori", 530,
          n["movimento_mercatino"])
    prova("senza capitale l'atteso e' VUOTO, non sbagliato", [None, None],
          [s["saldo_atteso_sats"], n["saldo_atteso_sats"]])
    prova("...e lo dice", True,
          s["capitale_dichiarato"].startswith("NO"))
    con.execute("INSERT INTO impostazioni VALUES ('capitale_nostro_sats', '100')")
    con.execute("INSERT INTO impostazioni VALUES ('capitale_nodo_sats', ' 7 ')")
    s, n = [dict(r) for r in con.execute(q)]
    prova("la chiave di ieri vale come ripiego del SaaS", 350,
          s["saldo_atteso_sats"])
    prova("il nodo legge la sua, ripulita dagli spazi", 537,
          n["saldo_atteso_sats"])
    con.execute("INSERT INTO impostazioni VALUES ('capitale_saas_sats', '150')")
    con.execute("UPDATE impostazioni SET valore='7 sats' "
                "WHERE chiave='capitale_nodo_sats'")
    s, n = [dict(r) for r in con.execute(q)]
    prova("la chiave nuova del SaaS vince sul ripiego", 400,
          s["saldo_atteso_sats"])
    prova("un valore sporco non fa zero: fa VUOTO", None,
          n["saldo_atteso_sats"])
    con.close()


def prove_doppio_wallet():
    """IL DOPPIO WALLET (set 2026): ogni riga di denaro porta la sua
    cassaforte, i tubi che leggono o pagano la pretendono, chi conia
    la scrive. Le sentinelle difendono la FORMA — un chiamante che
    dimentica la colonna interrogherebbe il wallet sbagliato, e gli
    scandagli annullerebbero un ordine pagato senza che nessuna prova
    funzionale lo veda."""
    print("\n[il doppio wallet: la cassaforte per riga]")
    src = _SORGENTE
    cod = codice(src)
    pv = pezzo("paga_venditore")

    # 1) i tubi che leggono o pagano pretendono la cassaforte SENZA
    #    default: chi la dimentica lo sente da Python, non dal SaaS
    prova("invoice_pagata pretende la cassaforte", True,
          "async def invoice_pagata(payment_hash: str, cassaforte: str)"
          in src)
    prova("_stato_pagamento pretende la cassaforte", True,
          "async def _stato_pagamento(payment_hash: str, cassaforte: str)"
          in src)
    prova("paga_venditore: cassaforte solo per nome e senza default", True,
          "*,\n                         cassaforte: str, riga: tuple = ()) "
          "-> str:" in pv)
    # ...e le sentinelle dell'ordine leggono ancora i nomi delle chiavi
    prova("le chiavi tengono i loro nomi dentro l'oggetto", True,
          "cf.LNBITS_ADMIN_KEY" in pv and "cf.LNBITS_INVOICE_KEY" in
          pezzo("invoice_pagata"))

    # 2) chi conia dice SEMPRE dove, e le strade sono cinque
    chiamate = [m.start() for m in re.finditer(
        r"await crea_invoice_escrow\(", cod)]
    prova("ogni crea_invoice_escrow passa cassaforte=", [],
          [cod[:i].count("\n") + 1 for i in chiamate
           if "cassaforte=" not in cod[i:i + 400]])
    prova("...e le strade che coniano sono cinque", 5, len(chiamate))

    # 3) chi legge passa la colonna della riga, mai un letterale
    prova("nessun invoice_pagata a un argomento solo", [],
          re.findall(r"await invoice_pagata\([^,()]*\)", cod))
    prova("nessuna cassaforte scritta a mano nei poll", [],
          re.findall(r"""invoice_pagata\([^)]*['"](?:saas|nodo)['"]\)""",
                     cod))
    prova("nessun paga_venditore senza cassaforte=", [],
          [m.group(0)[:50] for m in re.finditer(
              r"await paga_venditore\((?:[^()]|\([^()]*\))*\)", cod)
           if "cassaforte=" not in m.group(0)])
    prova("nessun _stato_pagamento a un argomento solo", [],
          re.findall(r"await _stato_pagamento\([^,()]*\)", cod))

    # 4) il risolutore: due nomi, la leva letta viva, il terzo alza
    amb = {"LNBITS_URL": "u1", "LNBITS_INVOICE_KEY": "i1",
           "LNBITS_ADMIN_KEY": "a1", "LNBITS_NODO_URL": "http://n",
           "LNBITS_NODO_INVOICE_KEY": "i2", "LNBITS_NODO_ADMIN_KEY": "a2",
           "CASSAFORTE_NUOVA": False, "CASSAFORTE_SAAS": "saas",
           "CASSAFORTE_NODO": "nodo", "CASSAFORTI": ("saas", "nodo"),
           "NamedTuple": __import__("typing").NamedTuple}
    i = src.index("class _Cassaforte(")
    exec(src[i:src.index("\n\n\n", i)], amb)
    for f in ("_nodo_configurato", "cassaforte_nuova", "_chiavi_cassaforte"):
        exec(pezzo(f), amb)
    prova("leva spenta: il nuovo nasce sul SaaS", "saas",
          amb["cassaforte_nuova"]())
    prova("'saas' -> le tre chiavi di ieri", ("u1", "i1", "a1"),
          tuple(amb["_chiavi_cassaforte"]("saas"))[1:])
    prova("'nodo' -> le tre chiavi del nodo", ("http://n", "i2", "a2"),
          tuple(amb["_chiavi_cassaforte"]("nodo"))[1:])
    prova("vuoto = quella del denaro nuovo", "saas",
          amb["_chiavi_cassaforte"]("").nome)
    amb["CASSAFORTE_NUOVA"] = True
    prova("leva accesa e nodo configurato: nodo", "nodo",
          amb["cassaforte_nuova"]())
    prova("...e il vuoto la segue", "nodo", amb["_chiavi_cassaforte"]("").nome)
    prova("...mentre 'saas' resta il SaaS anche a leva accesa", "u1",
          amb["_chiavi_cassaforte"]("saas").LNBITS_URL)
    amb["LNBITS_NODO_ADMIN_KEY"] = "INCOLLA_QUI_LA_ADMIN_KEY_DEL_NODO"
    prova("leva accesa col segnaposto: vale SPENTA", "saas",
          amb["cassaforte_nuova"]())
    amb["LNBITS_NODO_ADMIN_KEY"] = ""
    prova("leva accesa senza chiave: vale SPENTA", "saas",
          amb["cassaforte_nuova"]())
    try:
        amb["_chiavi_cassaforte"]("spark")
        esito = "ha risposto"
    except ValueError:
        esito = "alza"
    prova("un terzo nome ALZA, non ripiega", "alza", esito)

    # 5) la cassaforte della riga, su un database usa-e-getta
    import sqlite3
    con = sqlite3.connect(":memory:")
    con.row_factory = sqlite3.Row
    con.executescript("""
        CREATE TABLE rilanci(id INTEGER PRIMARY KEY, puntata_id INTEGER,
                             stato TEXT, cassaforte TEXT DEFAULT 'saas');
        CREATE TABLE rimborsi_asta(id INTEGER PRIMARY KEY, puntata_id INTEGER,
                                   cassaforte TEXT DEFAULT '');
        CREATE TABLE ordini(id INTEGER PRIMARY KEY, cassaforte TEXT DEFAULT 'saas');
        INSERT INTO rilanci(puntata_id, stato, cassaforte) VALUES
            (1, 'creato', 'saas'), (1, 'saldato', 'nodo'), (1, 'saldato', 'nodo'),
            (2, 'creato', 'nodo');
        INSERT INTO rimborsi_asta(puntata_id) VALUES (1), (2);
        INSERT INTO ordini(cassaforte) VALUES ('saas'), ('spark');
    """)
    for f in ("_cassaforte_puntata", "_cassaforte_riga"):
        exec(pezzo(f), amb)
    prova("puntata: conta il primo versamento SALDATO, non il primo nato",
          "nodo", amb["_cassaforte_puntata"](con, 1))
    prova("puntata senza versamenti: vuoto", "", amb["_cassaforte_puntata"](con, 2))
    prova("rimborso d'asta: si compila dalla puntata", "nodo",
          amb["_cassaforte_riga"](con, "rimborsi_asta", 1))
    prova("...e resta scritto", "nodo", con.execute(
        "SELECT cassaforte FROM rimborsi_asta WHERE id=1").fetchone()[0])
    prova("ordine: la colonna", "saas", amb["_cassaforte_riga"](con, "ordini", 1))
    for tab, rid, caso in (("ordini", 2, "una cassaforte sconosciuta"),
                           ("rimborsi_asta", 2, "una puntata senza versamenti"),
                           ("ordini", 99, "una riga inesistente")):
        try:
            amb["_cassaforte_riga"](con, tab, rid)
            esito = "ha risposto"
        except ValueError:
            esito = "alza"
        prova(f"{caso} ALZA", "alza", esito)
    con.close()

    # 6) la colonna, la leva, il pannello e il config
    prova("la colonna nasce 'saas' su ordini, rilanci e pagamenti", True,
          'for tabella in ("ordini", "rilanci", "pagamenti"):' in src
          and "cassaforte TEXT DEFAULT 'saas'" in src)
    prova("...e vuota sui rimborsi d'asta", True,
          "cassaforte TEXT DEFAULT ''" in src)
    cfg = open("config_esempio.py", encoding="utf-8").read()
    prova("leva: nasce False nel codice", True, "CASSAFORTE_NUOVA = False" in src)
    prova("leva: gemella in config_esempio", True, "CASSAFORTE_NUOVA = False" in cfg)
    prova("le tre righe del nodo stanno in config_esempio", True,
          all(k in cfg for k in ("LNBITS_NODO_URL", "LNBITS_NODO_INVOICE_KEY",
                                 "LNBITS_NODO_ADMIN_KEY")))
    prova("il pannello chiede alla leva VIVA", True,
          "cassaforte_nuova() == CASSAFORTE_NODO" in pezzo("_leve_stato"))
    prova("il pannello suona se la leva e' accesa senza chiavi", True,
          "allarme=bool(CASSAFORTE_NUOVA) and not _nodo_configurato()"
          in pezzo("_leve_stato"))
    prova("all'avvio si dice dove nasce il nuovo", True,
          "Cassaforte del denaro nuovo: {cassaforte_nuova()}" in src)
    # 7) il congelamento dice in quale LNbits cercare
    prova("il congelamento nomina la cassaforte", True,
          "su LNbits{dove}" in pezzo("_congela_pagamento"))
    prova("...e tutte e quattro le strade gliela passano", 4,
          len(re.findall(r"await _congela_pagamento\((?:[^()]|\([^()]*\))*"
                         r"cassaforte=", cod)))


def prove_saas_senza_doveri():
    """L'AVVISO DELLA FASE 5 (set 2026): suona una volta, alla discesa
    a zero dei doveri del SaaS, solo col denaro nuovo sul nodo, e nel
    dubbio non dichiara zero. Girato su un database usa-e-getta."""
    print("\n[il SaaS non ha piu' doveri: l'avviso della fase 5]")
    import sqlite3

    class _Aperta:
        # la funzione chiude la connessione che riceve: qui no
        def __init__(self, con):
            self._c = con

        def execute(self, *a):
            return self._c.execute(*a)

        def commit(self):
            self._c.commit()

        def close(self):
            pass

    con = sqlite3.connect(":memory:")
    con.row_factory = sqlite3.Row
    con.executescript("""
        CREATE TABLE ordini(id INTEGER PRIMARY KEY, stato TEXT,
            cassaforte TEXT DEFAULT 'saas', payout_stato TEXT DEFAULT '');
        CREATE TABLE puntate(id INTEGER PRIMARY KEY, stato TEXT);
        CREATE TABLE rilanci(id INTEGER PRIMARY KEY, puntata_id INT,
            stato TEXT, cassaforte TEXT DEFAULT 'saas');
        CREATE TABLE rimborsi_asta(id INTEGER PRIMARY KEY, puntata_id INT,
            stato TEXT, cassaforte TEXT DEFAULT '', payout_stato TEXT DEFAULT '');
        CREATE TABLE pagamenti(id INTEGER PRIMARY KEY, stato TEXT,
            cassaforte TEXT DEFAULT 'saas', payout_stato TEXT DEFAULT '');
        CREATE TABLE crediti_cassaforte(id INTEGER PRIMARY KEY,
            cassaforte TEXT, stato TEXT DEFAULT 'aperto');
    """)
    timbri, avvisi, nuova = {}, [], ["nodo"]

    async def _avvisa(t):
        avvisi.append(t)

    amb = {"db": lambda: _Aperta(con), "time": __import__("time"),
           "cassaforte_nuova": lambda: nuova[0], "CASSAFORTE_NODO": "nodo",
           "timbro_letto": lambda n: timbri.get(n, ""),
           "timbro_scrivi": lambda n, v: timbri.__setitem__(n, v),
           "notifica_admin": _avvisa, "print": lambda *a, **k: None}
    i = _SORGENTE.index("DOVERI_SAAS = (")
    exec(_SORGENTE[i:_SORGENTE.index("\n\n\n", i)], amb)
    amb["TIMBRO_SAAS_SENZA_DOVERI"] = "saas_senza_doveri"
    exec("async " + pezzo("avvisa_saas_senza_doveri"), amb)
    import asyncio as _as

    def giro():
        _as.run(amb["avvisa_saas_senza_doveri"]())

    # 1) la leva spenta: il SaaS e' la cassaforte viva, zero non e' una notizia
    nuova[0] = "saas"
    giro()
    prova("leva spenta: a zero doveri non parla", (0, {}), (len(avvisi), timbri))
    nuova[0] = "nodo"
    # 2) un dovere aperto sul SaaS: silenzio
    con.execute("INSERT INTO ordini(stato) VALUES('locked')")
    giro()
    prova("un ordine aperto sul SaaS: silenzio", 0, len(avvisi))
    # ...e le righe del nodo non contano
    con.execute("INSERT INTO ordini(stato, cassaforte) VALUES('locked','nodo')")
    con.execute("INSERT INTO pagamenti(stato, cassaforte) VALUES('creato','nodo')")
    con.execute("UPDATE ordini SET stato='released' WHERE cassaforte='saas'")
    giro()
    prova("a zero doveri (e righe del nodo aperte): UN avviso", 1, len(avvisi))
    prova("...che dice la fase 5", True, "fase 5" in avvisi[-1])
    prova("...e il timbro e' il giorno", True,
          timbri.get("saas_senza_doveri", "").count("-") == 2)
    # 3) il giorno dopo: niente
    giro(); giro()
    prova("a giri successivi non si ripete", 1, len(avvisi))
    # 4) un dovere ricompare: il timbro si riarma, senza avvisare
    con.execute("UPDATE ordini SET payout_stato='da_riprovare' WHERE cassaforte='saas'")
    giro()
    prova("un'uscita da riprovare sul SaaS: si riarma, senza suonare",
          (1, ""), (len(avvisi), timbri.get("saas_senza_doveri")))
    con.execute("UPDATE ordini SET payout_stato='uscito'")
    giro()
    prova("...e alla prossima discesa a zero suona di nuovo", 2, len(avvisi))
    # 5) i cinque registri contano, uno per uno
    casi = [
        ("versamento su un'asta viva",
         "INSERT INTO puntate(id, stato) VALUES(1,'attiva'); "
         "INSERT INTO rilanci(puntata_id, stato) VALUES(1,'saldato')",
         "UPDATE puntate SET stato='chiusa'"),
        ("rimborso d'asta da riscuotere senza cassaforte (nel dubbio e' SaaS)",
         "INSERT INTO rimborsi_asta(puntata_id, stato) VALUES(9,'da_riscuotere')",
         "UPDATE rimborsi_asta SET stato='riscosso'"),
        ("fattura nostra viva",
         "INSERT INTO pagamenti(stato) VALUES('creato')",
         "UPDATE pagamenti SET stato='annullato' WHERE cassaforte='saas'"),
        ("rimborso d'asta da decidere",
         "INSERT INTO rimborsi_asta(puntata_id, stato, payout_stato, cassaforte) "
         "VALUES(9,'riscosso','incerto','saas')",
         "UPDATE rimborsi_asta SET payout_stato='uscito'"),
        # IL SESTO (21 set 2026): l'ordine e' chiuso — pagato dal nodo —
        # ma sul SaaS c'e' un pagamento appeso coi suoi sats dentro
        ("credito da recuperare sul SaaS",
         "INSERT INTO crediti_cassaforte(cassaforte) VALUES('saas')",
         "UPDATE crediti_cassaforte SET stato='rientrato'"),
        ("credito saldato due volte sul SaaS",
         "INSERT INTO crediti_cassaforte(cassaforte, stato) "
         "VALUES('saas','doppio')",
         "UPDATE crediti_cassaforte SET stato='recuperato'"),
    ]
    for nome, apri, chiudi in casi:
        prima = len(avvisi)
        con.executescript(apri)
        giro()
        prova(f"{nome}: e' un dovere (silenzio, timbro riarmato)",
              (prima, ""), (len(avvisi), timbri.get("saas_senza_doveri")))
        con.executescript(chiudi)
        giro()
        prova(f"...chiuso, suona", prima + 1, len(avvisi))
    # ...e la puntata del NODO senza colonna sul rimborso non e' un dovere del SaaS
    con.executescript("INSERT INTO puntate(id, stato) VALUES(2,'chiusa'); "
                      "INSERT INTO rilanci(puntata_id, stato, cassaforte) VALUES(2,'saldato','nodo'); "
                      "INSERT INTO rimborsi_asta(puntata_id, stato) VALUES(2,'da_riscuotere')")
    prima = len(avvisi)
    timbri["saas_senza_doveri"] = ""
    giro()
    prova("rimborso senza colonna ma con la puntata sul nodo: non conta", prima + 1, len(avvisi))
    # 6) nel dubbio non e' zero: una query che esplode ferma tutto
    timbri["saas_senza_doveri"] = ""
    con.execute("DROP TABLE pagamenti")
    prima = len(avvisi)
    giro()
    prova("schema cambiato sotto: niente avviso e niente timbro",
          (prima, ""), (len(avvisi), timbri.get("saas_senza_doveri")))
    con.close()

    # --- le sentinelle
    corpo = pezzo("avvisa_saas_senza_doveri")
    prova("l'orologio lo chiama", True,
          "await avvisa_saas_senza_doveri()" in pezzo("orologio"))
    prova("il timbro si scrive PRIMA di parlare", True,
          corpo.index("timbro_scrivi(TIMBRO_SAAS_SENZA_DOVERI, oggi)")
          < corpo.index("await notifica_admin("))
    prova("non corregge NULLA", False,
          any(v in corpo.split('"""')[-1].upper()
              for v in ("UPDATE ", "INSERT ", "DELETE ")))
    prova("i doveri sono cinque e ognuno conta una cosa sola", True,
          _SORGENTE.count('SELECT COUNT(*) FROM') >= 5
          and 'DOVERI_SAAS = (' in _SORGENTE)
    prova("il polso 24 conta solo le aste VIVE fra i rilanci", True,
          "stato = 'attiva'" in open("query_libro_mastro.sql",
                                      encoding="utf-8").read())


def prove_esito_pagamento():
    """IL GIUDICE VERO DEI PAGAMENTI IN USCITA (set 2026).

    Dal campo, e il fatto e' datato: il 14 settembre un payout da
    67.672 sats e' fallito per mancanza di rotta, e il mercatino ha
    scritto 'released', dato gli XP e annunciato «✅ Ordine concluso»
    perche' guardava SOLO il numero HTTP. LNbits aveva risposto 201 —
    la richiesta era stata presa in carico — e 86 secondi dopo il nodo
    tornava indietro con un fallimento che non ascoltava nessuno.

    Qui si prova la cura in tre pezzi: il CORPO si legge (un 201 puo'
    portare dentro `status: failed`), l'ESITO si chiede per hash
    finche' non e' deciso, e l'ECO si riconosce PRIMA di pagare —
    perche' LNbits tiene una riga per payment hash e a una seconda
    richiesta sulla stessa bolt11 restituisce il record vecchio senza
    ritentare niente."""
    print("\n[l'esito del pagamento]")
    import asyncio
    import sqlite3

    def gira(coro):
        return asyncio.new_event_loop().run_until_complete(coro)

    def pezzo_async(nome):
        return "async " + pezzo(nome)

    ESITI = {"PAGATO": "pagato", "NON_PAGATO": "non_pagato",
             "INCERTO": "incerto", "NON_CHIESTO": "non_chiesto", "OCCUPATO": "occupato",
             "LnbitsMuto": LnbitsMuto}
    leggi = reale("_esito_lnbits")

    async def _zitto(*a, **k):
        return None

    # --- 1. Il lettore del corpo ------------------------------------
    # LA RIGA DEL 14 SETTEMBRE, per prima: e' la sola che il vecchio
    # codice sbagliava, ed e' quella che costa i sats.
    prova("corpo: un 201 con «failed» dentro e' un FALLIMENTO",
          "failed", leggi({"status": "failed", "paid": False}))
    prova("corpo: «success» e' un successo", "success",
          leggi({"status": "success"}))
    prova("corpo: paid=true basta da solo", "success", leggi({"paid": True}))
    # le istanze vecchie non dicono `status`: la' l'assenza di attesa
    # E' il successo, ed e' l'unico caso in cui un'assenza vale un si'
    prova("corpo: le istanze vecchie dicono pending=False", "success",
          leggi({"pending": False}))
    # ...e nel dubbio non si dice mai di si': un «non lo so» tiene la
    # domanda aperta e il giro ci torna, un falso si' chiude e mente
    prova("corpo: un corpo muto NON e' un successo", "pending", leggi({}))
    prova("corpo: uno stato mai visto NON e' un successo", "pending",
          leggi({"status": "chissa"}))
    prova("corpo: «pending» resta pending", "pending",
          leggi({"status": "pending"}))

    # --- 2. La domanda per hash -------------------------------------
    def stato(codice=200, corpo=None, esplode=False):
        import types

        class Rotto:
            def __init__(self, **kw):
                pass

            async def __aenter__(self):
                raise ConnectionError("nodo irraggiungibile")

            async def __aexit__(self, *a):
                return False

        amb = {"httpx": (types.SimpleNamespace(AsyncClient=Rotto) if esplode
                         else _finto_lnbits([], codice, corpo=corpo)),
               "LNBITS_URL": "http://x", "LNBITS_INVOICE_KEY": "k",
               "_chiavi_cassaforte": _cassaforte_finta(),
               "LnbitsMuto": LnbitsMuto, "_esito_lnbits": leggi}
        exec(pezzo_async("_stato_pagamento"), amb)
        try:
            return gira(amb["_stato_pagamento"]("abc123", "saas"))
        except LnbitsMuto:
            return "muto"

    # LA DIFFERENZA CHE VALE I SATS: «non l'ho mai visto» (404) e «non
    # si sa ancora» sono due cose diverse. Il primo autorizza a pagare,
    # il secondo lo vieta — e scambiarli fa uscire i sats due volte.
    prova("hash mai visto: nessuna traccia, non «in corso»", "",
          stato(codice=404))
    prova("hash gia' fallito: lo dice", "failed",
          stato(corpo={"status": "failed"}))
    prova("hash gia' saldato: lo dice", "success",
          stato(corpo={"status": "success"}))
    # e un guasto del canale non e' MAI «non c'e' nessun pagamento»
    prova("LNbits a 520: e' il canale, non una risposta", "muto",
          stato(codice=520))
    prova("rete caduta: idem", "muto", stato(esplode=True))

    # --- 3. paga_venditore, dal corpo all'eco -----------------------
    def paga(corpo=None, eco=(), codice=201, muto=False, chiesto=1000):
        uscite, avvisi, chieste = [], [], []
        fila = list(eco)
        taccuino = {"etichetta": "una prova"}

        async def _decodifica(_b, _cf=""):
            return {"payment_hash": "abc123"}

        async def _importo(_b, _dec=None):
            return chiesto

        async def _stato(h, _cf=""):
            chieste.append(h)
            if not fila:
                return ""
            v = fila.pop(0)
            if v == "muto":
                raise LnbitsMuto("stato del pagamento: LNbits a 520")
            return v

        async def _avvisa(t):
            avvisi.append(t)

        amb = {**ambiente_scadenza(),
               "httpx": _finto_lnbits(uscite, codice, muto, corpo),
               "decodifica_invoice": _decodifica, "importo_invoice": _importo,
               "_stato_pagamento": _stato, "_esito_lnbits": leggi,
               "notifica_admin": _avvisa, "asyncio": asyncio,
               "print": lambda *a, **k: None,
               "_fmt_sats": reale("_fmt_sats"),
               "ATTESE_ESITO": 4, "SECONDI_FRA_ATTESE": 0,
               "LNBITS_URL": "http://x", "LNBITS_ADMIN_KEY": "k",
               "_chiavi_cassaforte": _cassaforte_finta(), **ESITI}
        exec(pezzo_async("_avvisa_payout_fallito"), amb)
        exec(pezzo_async("paga_venditore"), amb)
        esito = gira(amb["paga_venditore"]("lnbc1", 1000, taccuino, cassaforte="saas"))
        return esito, len(uscite), len(avvisi), taccuino

    # IL CASO DEL 14 SETTEMBRE, rifatto al banco: HTTP 201, corpo che
    # dice «failed». Prima di oggi qui usciva «pagato».
    prova("201 col fallimento nel corpo: NON_PAGATO (era 'pagato')",
          ("non_pagato", 1, 1),
          paga(corpo={"status": "failed", "paid": False})[:3])
    prova("201 col successo nel corpo: PAGATO senza aspettare",
          ("pagato", 1, 0), paga(corpo={"status": "success"})[:3])
    # il corpo non decide: si richiede per hash finche' non e' deciso
    prova("corpo in sospeso, poi l'hash dice di si': PAGATO",
          ("pagato", 1, 0), paga(corpo={}, eco=("", "success"))[:3])
    prova("corpo in sospeso, poi l'hash dice di no: NON_PAGATO",
          ("non_pagato", 1, 1), paga(corpo={}, eco=("", "failed"))[:3])
    # ...e se a budget scaduto non si sa ancora, non si indovina
    prova("in corso a budget scaduto: INCERTO, mai 'pagato'",
          ("incerto", 1, 0), paga(corpo={}, eco=("",))[:3])

    # L'ECO. LNbits tiene una riga per hash: una seconda richiesta
    # sulla stessa bolt11 torna col record vecchio senza ritentare.
    # Quindi la si riconosce PRIMA, e non si bussa nemmeno al nodo.
    prova("eco di un fallito: NON_PAGATO e ZERO pagamenti partiti",
          ("non_pagato", 0, 1), paga(eco=("failed",))[:3])
    prova("eco di un saldato: PAGATO e zero pagamenti partiti",
          ("pagato", 0, 0), paga(eco=("success",))[:3])
    prova("eco di uno in volo: INCERTO e zero pagamenti partiti",
          ("incerto", 0, 0), paga(eco=("pending",))[:3])
    # e se la domanda dell'eco tace, nessun sat si e' mosso: e' il
    # quarto esito, quello che si puo' ritentare senza pericolo
    prova("eco muta: NON_CHIESTO e zero pagamenti partiti",
          ("non_chiesto", 0, 0), paga(eco=("muto",))[:3])

    # il taccuino torna pieno a chi ha chiamato: senza l'hash, di un
    # pagamento riuscito non resterebbe traccia da nessuna parte
    prova("il taccuino porta l'hash del pagamento", "abc123",
          paga(corpo={"status": "success"})[3].get("hash"))
    prova("...e dice che il nodo e' stato toccato davvero", True,
          paga(corpo={"status": "success"})[3].get("tentato") is True)
    prova("l'eco invece non tocca il nodo, e il taccuino lo dice",
          None, paga(eco=("failed",))[3].get("tentato"))

    # --- 4. Il diario nella riga ------------------------------------
    def timbro(*diari):
        vero = sqlite3.connect(":memory:")
        vero.execute(
            "CREATE TABLE ordini(id INTEGER PRIMARY KEY, "
            "payout_stato TEXT DEFAULT '', payout_hash TEXT DEFAULT '', "
            "payout_tentativi INT DEFAULT 0, payout_ultimo INT DEFAULT 0, "
            "payout_errore TEXT DEFAULT '', aggiornato INT DEFAULT 7)")
        vero.execute("INSERT INTO ordini(id) VALUES(1)")
        amb = {"time": __import__("time")}
        exec(pezzo("_timbra_pagamento"), amb)
        for d in diari:
            amb["_timbra_pagamento"](vero, "ordini", 1, d)
        r = vero.execute(
            "SELECT payout_hash, payout_tentativi, payout_errore, "
            "payout_stato, aggiornato FROM ordini WHERE id=1").fetchone()
        vero.close()
        return tuple(r)

    # il patto del quarto esito: se non si sa niente, non si scrive
    # niente — la riga dev'essere identica a com'era
    prova("diario vuoto: la riga non si muove", ("", 0, "", "", 7),
          timbro({}))
    prova("diario con la sola etichetta: la riga non si muove",
          ("", 0, "", "", 7), timbro({"etichetta": "x"}))
    prova("diario con l'hash: scrive l'hash e basta",
          ("abc123", 0, "", "", 7), timbro({"hash": "abc123"}))
    prova("diario di un tentativo: hash, conto e motivo",
          ("abc123", 1, "LNbits: failed", "", 7),
          timbro({"hash": "abc123", "tentato": True,
                  "errore": "LNbits: failed"}))
    # il conto e' RELATIVO: due strade diverse timbrano la stessa riga
    prova("due tentativi: il conto sale, non si riazzera", 2,
          timbro({"hash": "a", "tentato": True},
                 {"hash": "a", "tentato": True})[1])
    # e le due colonne che NON sono sue restano intatte
    prova("il diario non scrive lo stato del payout", "",
          timbro({"hash": "a", "tentato": True})[3])
    prova("il diario non muove l'ancora dei promemoria", 7,
          timbro({"hash": "a", "tentato": True})[4])

    # --- 5. SENTINELLE ----------------------------------------------
    pv = codice(pezzo("paga_venditore"))
    # LA SENTINELLA DEL CANTIERE: il numero HTTP non decide piu' da
    # solo. Se questa torna rossa, e' tornato il difetto del 14 set.
    prova("sentinella: il numero HTTP non decide piu' da solo", True,
          "r.status_code < 300" not in pv)
    prova("sentinella: il corpo della risposta si legge davvero", True,
          "_esito_lnbits(r.json())" in pv)
    prova("sentinella: l'esito si richiede per hash, alla cassaforte giusta",
          True, "_stato_pagamento(phash, cf.nome)" in pv)
    # l'eco si chiede PRIMA di toccare la chiave che paga, o non
    # servirebbe a niente: e' li' che si evita il secondo pagamento
    prova("sentinella: l'eco si chiede prima della chiave che paga",
          True, pv.index("_stato_pagamento") < pv.index("LNBITS_ADMIN_KEY"))
    # i quattro rami riusciti timbrano, e il conto cresce A MANO come
    # quello dell'INCERTO: se CALA, qualcuno ha tolto una traccia
    prova("sentinella: tutt'e quattro i rami riusciti timbrano 'uscito'",
          4, _SORGENTE.count("payout_stato='uscito', "))
    prova("sentinella: tutt'e quattro le uscite scrivono il diario",
          4, _SORGENTE.count('_timbra_pagamento(con, "'))
    # il diario dice cos'e' successo, lo stato dice cosa fare: se
    # questo timbro scrivesse anche lo stato, i suoi tre scrittori si
    # metterebbero a litigare. ⚠️ SENZA LA PROSA: la docstring nomina
    # apposta le due colonne che non tocca.
    tp = codice(_senza_prosa(pezzo("_timbra_pagamento")))
    prova("sentinella: il diario non scrive payout_stato", True,
          "payout_stato" not in tp)
    prova("sentinella: il diario non tocca `aggiornato`", True,
          "aggiornato" not in tp)
    prova("sentinella: il diario non committa e non chiude", True,
          "commit()" not in tp and "close()" not in tp)
    # il quinto tubo verso LNbits dice quanto aspetta, come gli altri
    prova("sentinella: il tubo dell'esito dice quanto aspetta", True,
          "httpx.AsyncClient(timeout=" in pezzo("_stato_pagamento"))
    # e il 404 non si confonde col resto: e' l'unica risposta che
    # autorizza a pagare
    prova("sentinella: il 404 ha il suo ramo, separato dal resto", True,
          "r.status_code == 404" in codice(pezzo("_stato_pagamento")))

    # --- 11. LA RONDA DI RICONCILIAZIONE, PER ORDINE ----------------
    # Il 14 set 2026 un payout e' fallito e l'ordine e' stato scritto
    # 'released' lo stesso, e il guasto era invisibile perche' di un
    # pagamento riuscito non restava scritto NIENTE. Adesso l'hash c'e',
    # e questa ronda va a chiedere alla CONTROPARTE se quel che diamo
    # per fatto sia davvero uscito. E' la protezione per RIGA — quella
    # di cassa, su un wallet misto, non torna mai e non e' un allarme.
    def ronda(verdetti, gia_visto=False, hash_riga="h-1", verificato=0,
              acceso=True, oggi_gia_fatto=False):
        vero = sqlite3.connect(":memory:")
        vero.row_factory = sqlite3.Row
        vero.execute(
            "CREATE TABLE ordini(id INTEGER PRIMARY KEY, stato TEXT, "
            "prezzo_sats INT, payout_stato TEXT DEFAULT '', "
            "payout_hash TEXT DEFAULT '', payout_verificato INT DEFAULT 0)")
        # una riga CHIUSA che porta gia' il nostro timbro 'uscito': la
        # ronda deve guardarla lo stesso, o chiederebbe conferma solo di
        # cio' di cui gia' non dubita
        vero.execute("INSERT INTO ordini VALUES(1,'released',67672,'uscito',"
                     "?,?)", (hash_riga, verificato))
        for tb in ("rimborsi_asta", "pagamenti"):
            vero.execute(f"CREATE TABLE {tb}(id INTEGER PRIMARY KEY, "
                         "stato TEXT, importo_sats INT, "
                         "payout_hash TEXT DEFAULT '', "
                         "payout_verificato INT DEFAULT 0)")

        class Con:
            def execute(self, *a):
                return vero.execute(*a)

            def commit(self):
                vero.commit()

            def close(self):
                pass

        chieste, avvisi, timbri = [], [], {}

        async def _stato(h, _cf=""):
            chieste.append(h)
            v = verdetti.pop(0) if verdetti else ""
            if v == "muto":
                raise LnbitsMuto("stato del pagamento: LNbits a 520")
            return v

        async def _avvisa(testo):
            avvisi.append(testo)

        amb = {"db": Con, "time": __import__("time"),
               "_stato_pagamento": _stato, "notifica_admin": _avvisa,
               "_cassaforte_riga": lambda con, tab, rid: "saas",
               "LnbitsMuto": LnbitsMuto, "_fmt_sats": reale("_fmt_sats"),
               "RICONCILIA_PAYOUT": acceso, "RICONCILIA_PER_GIRO": 50,
               "TIMBRO_RICONCILIA": "ric",
               "timbro_letto": lambda n: ("2000-01-01" if oggi_gia_fatto
                                          else timbri.get(n, "")),
               "timbro_scrivi": lambda n, v: timbri.__setitem__(n, v),
               "print": lambda *a, **k: None,
               # dal 21 set 2026 la ronda chiede ogni hash alla cassaforte
               # che l'ha TENTATO, e ripiega su quella della riga
               **ambiente_altra_cassaforte()}
        if oggi_gia_fatto:
            # il timbro del giorno gia' scritto DA OGGI: si finge che
            # `time.strftime` e il timbro combacino
            amb["time"] = type("T", (), {
                "strftime": staticmethod(lambda f: "2000-01-01"),
                "time": staticmethod(lambda: 111)})
        exec(pezzo_async("riconcilia_payout"), amb)
        gira(amb["riconcilia_payout"]())
        r = vero.execute("SELECT payout_verificato FROM ordini "
                         "WHERE id=1").fetchone()[0]
        vero.close()
        return len(chieste), bool(r), (avvisi[0] if avvisi else "")

    quante, timbrata, avviso = ronda(["success"])
    prova("payout confermato: si chiede una volta e la riga si timbra",
          (1, True, ""), (quante, timbrata, avviso))

    quante, timbrata, avviso = ronda(["failed"])
    prova("payout FALLITO: la riga non si timbra", (1, False), (quante, timbrata))
    prova("...e l'avviso lo nomina, con tabella, id, importo e hash", True,
          "FALLITI" in avviso and "ordini #1" in avviso
          and "67.672" in avviso and "h-1" in avviso)
    # e dice che da li' non parte niente: questa ronda legge e basta
    prova("...e dice che nessun ritentativo parte da qui", True,
          "legge e" in avviso and "nuova" in avviso)

    # «nessuna traccia» NON e' un fallimento: confonderli manderebbe chi
    # modera a cercare la cosa sbagliata
    quante, timbrata, avviso = ronda([""])
    prova("nessuna traccia: si dice, ma separata dai falliti", True,
          "nessuna traccia" in avviso and "FALLITI" not in avviso)
    prova("...e nemmeno quella si timbra", False, timbrata)

    quante, timbrata, avviso = ronda(["pending"])
    prova("ancora in corso: non si timbra e non si grida",
          (1, False, ""), (quante, timbrata, avviso))

    quante, timbrata, avviso = ronda(["muto"])
    prova("LNbits muto: si ferma, non timbra e non avvisa",
          (1, False, ""), (quante, timbrata, avviso))

    # il timbro della RIGA: un pagamento saldato e' terminale, quindi non
    # si richiede mai piu'
    quante, _, _ = ronda(["success"], verificato=1757900000)
    prova("gia' verificata: non si richiede piu'", 0, quante)
    # ...e una riga senza hash non si puo' chiedere
    quante, _, _ = ronda(["success"], hash_riga="")
    prova("senza hash non c'e' niente da chiedere", 0, quante)
    # il timbro del GIORNO: la ronda non gira a ogni battito
    quante, _, _ = ronda(["success"], oggi_gia_fatto=True)
    prova("gia' girata oggi: non chiede niente", 0, quante)
    # e la leva la spegne davvero
    quante, _, _ = ronda(["success"], acceso=False)
    prova("leva spenta: la ronda non parte", 0, quante)

    # --- 12. SENTINELLE DELLA RONDA ---------------------------------
    ric = codice(_senza_prosa(pezzo("riconcilia_payout")))
    # LEGGE E BASTA, come la sorella del libro mastro: ripagare da qui
    # sarebbe pagare due volte il giorno che la lettura sbaglia
    prova("sentinella: la ronda non ripaga niente", True,
          "paga_venditore" not in ric and "invoice_da_ln_address" not in ric)
    prova("sentinella: la ronda non corregge nessuno stato", True,
          "SET stato=" not in ric and "payout_stato=" not in ric)
    # l'unica scrittura ammessa e' il timbro della verifica
    prova("sentinella: l'unica cosa che scrive e' il timbro", 1,
          ric.count("UPDATE "))
    # NON SI FIDA DEL NOSTRO TIMBRO: se filtrasse su payout_stato
    # chiederebbe conferma solo di cio' di cui gia' non dubita
    prova("sentinella: guarda anche le righe che diciamo gia' uscite",
          True, "payout_stato" not in ric)
    prova("sentinella: si ferma al primo silenzio", True, "break" in ric)
    # il timbro del giorno si scrive PRIMA delle domande, o un errore a
    # meta' giro la farebbe ripartire a ogni battito
    prova("sentinella: il timbro del giorno precede le domande", True,
          ric.index("timbro_scrivi") < ric.index("_stato_pagamento"))
    # e gira nell'orologio accanto alla sorella
    _oro2 = codice(pezzo("orologio"))
    prova("sentinella: la ronda gira nell'orologio", True,
          "riconcilia_payout()" in _oro2)


    # --- 6. IL VOLO (cantiere B) ------------------------------------
    # Un pagamento senza verdetto a budget scaduto non chiama piu' una
    # persona: ha un NOME, quindi la domanda si rifa' da soli al battito
    # dopo. Qui si prova che il timbro nuovo non paga, che il giro lo
    # scioglie nelle tre direzioni, e che dopo mezz'ora si arrende.
    def in_volo(verdetto="success", eta=60, phash="h-volo", muto=False):
        vero = sqlite3.connect(":memory:")
        vero.row_factory = sqlite3.Row
        vero.execute(
            "CREATE TABLE ordini(id INTEGER PRIMARY KEY, payout_stato TEXT, "
            "payout_hash TEXT, payout_verso TEXT, payout_ultimo INT, "
            "aggiornato INT DEFAULT 7)")
        adesso = int(__import__("time").time())
        vero.execute("INSERT INTO ordini VALUES(1,'in_volo',?,'venditore',?,7)",
                     (phash, adesso - eta))

        class Con:
            def execute(self, *a):
                return vero.execute(*a)

            def commit(self):
                vero.commit()

            def close(self):
                pass

        ripresi, avvisi = [], []

        async def _stato(_h, _cf=""):
            if muto:
                raise LnbitsMuto("stato del pagamento: LNbits a 520")
            return verdetto

        async def _riprendi(tab, rid, verso):
            ripresi.append((tab, rid, verso))
            return {"ok": True}

        async def _avvisa(t):
            avvisi.append(t)

        async def _lnd_spento(_h, _cf=""):
            return "n/a"      # la riga del SaaS: dal 22 set non e' «spento»

        amb = {"db": Con, "time": __import__("time"),
               "_stato_pagamento": _stato, "_riprendi_uscita": _riprendi,
               "_cassaforte_riga": lambda con, tab, rid: "saas",
               "notifica_admin": _avvisa, "LnbitsMuto": LnbitsMuto,
               "MAX_RIPRESE_GIRO": 20, "IN_VOLO_LIMITE_S": 1800,
               # dal cantiere dei pagamenti in volo la ronda chiede la
               # VERITA' a due fonti: qui il giudice e' quello vero, e
               # LND e' spento — cioe' la riga del SaaS, dove decide
               # LNbits da sola come ha sempre fatto
               "_stato_lnd": _lnd_spento, **costanti_verita(),
               **ambiente_in_pagamento(),
               "print": lambda *a, **k: None}
        exec(pezzo("_verdetto_pagamento"), amb)
        exec(pezzo_async("_verita_pagamento"), amb)
        exec(pezzo_async("_arrenditi_in_volo"), amb)
        exec(pezzo_async("risolvi_pagamenti_in_volo"), amb)
        gira(amb["risolvi_pagamenti_in_volo"]())
        r = vero.execute("SELECT * FROM ordini WHERE id=1").fetchone()
        fuori = (r["payout_stato"], r["aggiornato"], ripresi, avvisi)
        vero.close()
        return fuori

    stato, ancora, ripresi, avvisi = in_volo("success")
    prova("volo saldato: la riga timbra 'uscito'", "uscito", stato)
    prova("...e si ripassa dalla strada di sempre, che NON ripaga",
          [("ordini", 1, "venditore")], ripresi)
    prova("...senza svegliare nessuno", [], avvisi)

    stato, _, ripresi, avvisi = in_volo("failed")
    prova("volo fallito: il fermo si toglie", "", stato)
    prova("...e si ripassa di li', dove l'eco fara' il resto",
          [("ordini", 1, "venditore")], ripresi)

    # «nessuna traccia» si tratta come un fallimento, ed e' voluto: si
    # ripassa dalla strada di sempre, che ricontrolla tutto da capo
    # prima di muovere un sat
    # ...ma NON SUBITO (cantiere dei pagamenti in volo): una richiesta
    # appena partita «non c'e'» per definizione, e prima di
    # MAI_PARTITO_DOPO_S la traccia che manca non autorizza niente
    stato, _, ripresi, _ = in_volo("", eta=60)
    prova("volo senza traccia, ma giovane: si aspetta",
          ("in_volo", []), (stato, ripresi))
    stato, _, ripresi, _ = in_volo("", eta=1000)
    prova("volo senza traccia: si ripassa dalla strada di sempre",
          ("", [("ordini", 1, "venditore")]), (stato, ripresi))

    stato, ancora, ripresi, avvisi = in_volo("pending", eta=60)
    prova("volo ancora in corso: la riga non si muove", "in_volo", stato)
    prova("...e non si ripassa da nessuna parte", ([], []), (ripresi, avvisi))
    prova("...e nemmeno l'ancora dei promemoria", 7, ancora)

    stato, _, ripresi, avvisi = in_volo("pending", eta=3600)
    prova("volo troppo lungo: adesso decide una persona", "incerto", stato)
    prova("...e non si ripassa a pagare", [], ripresi)
    prova("...ai moderatori arriva l'hash, non un'alzata di spalle",
          True, len(avvisi) == 1 and "h-volo" in avvisi[0])

    stato, _, ripresi, avvisi = in_volo(muto=True)
    prova("LNbits muto: la riga resta in volo e non si insiste",
          ("in_volo", [], []), (stato, ripresi, avvisi))

    # una riga in volo SENZA hash e' un difetto nostro: non si puo'
    # chiedere niente, quindi la guarda una persona — e glielo si dice
    stato, _, _, avvisi = in_volo(phash="")
    prova("volo senza nome: passa a una persona, e l'avviso lo dice",
          True, stato == "incerto" and len(avvisi) == 1
          and "difetto" in avvisi[0])

    # --- 7. SENTINELLE DEL VOLO -------------------------------------
    iv = codice(_senza_prosa(pezzo("_in_volo")))
    prova("sentinella: il timbro del volo non tocca `aggiornato`", True,
          "aggiornato" not in iv)
    prova("sentinella: il timbro del volo non avvisa nessuno", True,
          "notifica" not in iv)
    prova("sentinella: il timbro del volo scrive CHI aspettava i sats",
          True, "payout_verso=?" in iv)
    # l'arresa e' CONDIZIONATA come tutte le sue sorelle: se nel
    # frattempo qualcuno ha deciso, qui non si riscrive niente
    prova("sentinella: l'arresa non scavalca chi ha gia' deciso", True,
          "AND payout_stato='in_volo'" in codice(pezzo("_arrenditi_in_volo")))
    prova("sentinella: il giro del volo si ferma al primo silenzio", True,
          "break" in codice(pezzo("risolvi_pagamenti_in_volo")))
    # e il giro sta nell'orologio PRIMA della ripresa, o una riga decisa
    # aspetterebbe dieci minuti per essere riprovata
    _oro = codice(pezzo("orologio"))
    prova("sentinella: il volo si scioglie prima della ripresa", True,
          "risolvi_pagamenti_in_volo()" in _oro
          and _oro.index("risolvi_pagamenti_in_volo()")
          < _oro.index("riprova_pagamenti_sospesi()"))


    # --- 8. IL BACKOFF E LE PAROLE (cantiere B2) --------------------
    # la scala si legge DAL SORGENTE, non si ricopia qui: altrimenti le
    # righe che pinzano i cinque numeri proverebbero se stesse
    _ambq = {}
    exec([r for r in _SORGENTE.splitlines()
          if r.startswith("BACKOFF_PAYOUT = ")][0], _ambq)
    exec(pezzo("_quando_ritentare"), _ambq)
    quando = _ambq["_quando_ritentare"]
    # con `ultimo` a zero non c'e' niente da aspettare: e' la strada del
    # quarto esito, dove il nodo non e' mai stato toccato, e il
    # comportamento di ieri deve restare identico
    prova("mai bussato al nodo: si riprova subito", 0, quando(0, 0))
    prova("...anche dopo qualche giro a vuoto", 0, quando(3, 0))
    prova("primo fallimento: cinque minuti", 1000 + 300, quando(1, 1000))
    prova("secondo: mezz'ora", 1000 + 1800, quando(2, 1000))
    prova("terzo: due ore", 1000 + 7200, quando(3, 1000))
    prova("quarto: sei ore", 1000 + 21600, quando(4, 1000))
    prova("quinto: un giorno", 1000 + 86400, quando(5, 1000))
    prova("oltre la scala non si accorcia", 1000 + 86400, quando(99, 1000))

    # --- 9. IL GIRO PESCA COL BACKOFF -------------------------------
    def giro(tentativi, ultimo, esito=None):
        """riprova_pagamenti_sospesi su UNA riga timbrata: dice se e'
        stata pescata, e se il timbro e' sopravvissuto."""
        vero = sqlite3.connect(":memory:")
        vero.row_factory = sqlite3.Row
        vero.execute(
            "CREATE TABLE ordini(id INTEGER PRIMARY KEY, payout_stato TEXT, "
            "payout_verso TEXT, payout_tentativi INT, payout_ultimo INT)")
        vero.execute("INSERT INTO ordini VALUES(1,'da_riprovare','venditore',?,?)",
                     (tentativi, ultimo))
        for t in ("rimborsi_asta", "pagamenti"):
            vero.execute(f"CREATE TABLE {t}(id INTEGER PRIMARY KEY, "
                         "payout_stato TEXT, payout_verso TEXT, "
                         "payout_tentativi INT, payout_ultimo INT)")

        class Con:
            def execute(self, *a):
                return vero.execute(*a)

            def commit(self):
                vero.commit()

            def close(self):
                pass

        pescate = []

        async def _riprendi(tab, rid, verso):
            pescate.append((tab, rid))
            return esito or {"ok": True}

        amb = {"db": Con, "time": __import__("time"),
               "_riprendi_uscita": _riprendi, "MAX_RIPRESE_GIRO": 20,
               "BACKOFF_PAYOUT": _ambq["BACKOFF_PAYOUT"],
               "timbro_letto": lambda _n: "gia-oggi",
               "timbro_scrivi": lambda *a: None,
               "TIMBRO_SOSPESI": "x", "notifica_admin": _zitto,
               **ambiente_in_pagamento(),
               "print": lambda *a, **k: None}
        exec(pezzo("_quando_ritentare"), amb)
        exec(pezzo_async("riprova_pagamenti_sospesi"), amb)
        gira(amb["riprova_pagamenti_sospesi"]())
        timbro = vero.execute("SELECT payout_stato FROM ordini "
                              "WHERE id=1").fetchone()[0]
        vero.close()
        return len(pescate), timbro

    adesso = int(__import__("time").time())
    prova("timbro senza tentativi: pescata subito, e il timbro si pulisce",
          (1, ""), giro(0, 0))
    prova("fallita or ora: il giro NON la ripesca", (0, "da_riprovare"),
          giro(1, adesso))
    prova("...ma dopo cinque minuti si", (1, ""), giro(1, adesso - 301))
    prova("al secondo giro aspetta mezz'ora", (0, "da_riprovare"),
          giro(2, adesso - 301))
    prova("...e dopo mezz'ora riparte", (1, ""), giro(2, adesso - 1801))
    # LA RIGA CHE TIENE VIVO IL RITENTATIVO: se l'uscita chiede un altro
    # giro, il timbro NON si cancella — altrimenti il backoff morirebbe
    # al primo fallimento, cioe' esattamente dove serve.
    prova("se l'uscita chiede un altro giro, il timbro resta",
          (1, "da_riprovare"),
          giro(1, adesso - 301, esito={"ok": False, "ritenta": True}))


def costanti_verita():
    """I nomi della VERITA' DI UN PAGAMENTO, presi dal sorgente e non
    ricopiati: il giorno che 'in_volo' cambiasse grafia di la', un
    dizionario battuto a mano qui resterebbe verde a giudice rotto."""
    amb = {}
    for inizio in ("LND_SUCCEEDED, LND_IN_FLIGHT, LND_FAILED = ",
                   "LND_ASSENTE, LND_MUTO, LND_SPENTO = ",
                   "LND_NA = ", "LND_SENZA_VOCE = ",
                   "MAI_PARTITO_DOPO_S = ", "LND_CANARINO_VALE_S = ",
                   "TIMBRO_CANARINO = ",
                   "USCITO, IN_VOLO, FALLITO, MAI_PARTITO, IGNOTO = ("):
        i = _SORGENTE.index("\n" + inizio) + 1
        fine = (_SORGENTE.index(")\n", i) + 1 if inizio.endswith("(")
                else _SORGENTE.index("\n", i))
        exec(_SORGENTE[i:fine], amb)
    amb.pop("__builtins__", None)
    return amb


NOMI_IN_PAGAMENTO = (
    "VIA_LIGHTNING", "VIA_ONCHAIN", "IN_PAGAMENTO_LUNGO_S", "BACKOFF_NOSTRO",
    "MOTIVO_LNBITS_MUTO", "MOTIVO_ALTRA_CASSAFORTE", "MOTIVO_FATTURA_NUOVA",
    "MOTIVI_NOSTRI", "PASSO_DECISO", "PASSO_PARTITO",
    "PASSO_IN_VOLO", "PASSO_IN_VERIFICA", "PASSO_GUASTO", "PASSO_FALLITO",
    "PASSO_SERVE", "PASSO_ARRIVATO", "PASSO_RIPARTE", "PASSO_CONFERME",
    "_segna_passo", "_segna_deciso", "_ultimo_passo", "_conta_guasti",
    "_gia_detto", "_quando_ritentare_nostro", "_tocca_riprovare", "_campo",
    "_in_pagamento", "_rifiuto_in_pagamento", "stadio_pagamento",
    "_stadi_ordini", "_avvisa_in_pagamento")


def ambiente_in_pagamento(notifica=None, commissione=0):
    """I pezzi VERI dello stadio «in pagamento» (set 2026), per gli
    ambienti finti che fanno girare `_sblocca_sats`, le rotte
    dell'ordine e la lista: da quel giorno li chiamano, e un ambiente
    che non li monta esplode con un NameError — la trappola delle
    funzioni estratte, che ogni cantiere dei pagamenti ha ripagato.

    UN AMBIENTE PRIVATO, e si esportano i soli NOMI del cantiere: le
    funzioni restano legate al dizionario in cui nascono, quindi le
    loro dipendenze (`netto_venditore`, la commissione, `notifica`)
    stanno qui dentro e non cadono nell'ambiente di chi le monta, dove
    coprirebbero le sue.

    SUI BANCHI DI IERI LA TABELLA `payout_passi` NON C'E', ed e' il
    fail-open dichiarato: i passi non si scrivono, `_segna_deciso` dice
    «primo giro» e tutto va come prima del cantiere — i messaggi sono
    quelli di sempre. Gli avvisi nuovi su quei banchi sono MUTI apposta
    (`notifica=None`): chi li vuole contare passa la sua `notifica`,
    come fa `prove_in_pagamento`."""
    async def _muta(*a, **k):
        return None

    p = {"time": time, "html": __import__("html"),
         "notifica": notifica or _muta,
         "COMMISSIONE_PERCENTO": commissione,
         "_fmt_sats": reale("_fmt_sats")}
    for inizio in ("IN_VOLO_LIMITE_S = ", "BACKOFF_PAYOUT = (",
                   "MOTIVO_SCADUTA, MOTIVO_STRADA, ",
                   "VIA_LIGHTNING, VIA_ONCHAIN = "):
        i = _SORGENTE.index("\n" + inizio) + 1
        exec(_SORGENTE[i:_SORGENTE.index("\n\n", i)], p)
    for nome in ("netto_venditore", "_quando_ritentare") + tuple(
            n for n in NOMI_IN_PAGAMENTO if n[0] == "_" or n[0].islower()):
        # `pezzo` taglia dal `def`: all'unica asincrona l'`async` va rimesso
        exec(("async " if nome == "_avvisa_in_pagamento" else "")
             + pezzo(nome), p)
    # ...e i quattro di «paga da un'altra cassaforte» (21 set 2026), che
    # stanno dentro le stesse funzioni d'uscita: chi monta questi monta
    # anche quelli, o `_sblocca_sats` e la ronda esplodono un cantiere dopo
    return {**{n: p[n] for n in NOMI_IN_PAGAMENTO},
            **ambiente_altra_cassaforte()}


NOMI_ALTRA_CASSAFORTE = ("DEVIATO", "_dove_tentati", "_cassaforte_tentata",
                         "_cassaforte_uscita")


def ambiente_altra_cassaforte():
    """I QUATTRO NOMI che «paga da un'altra cassaforte» (21 set 2026) ha
    messo DENTRO le funzioni d'uscita di sempre — `_verita_riga`,
    `paga_venditore`, `_sblocca_sats`, la ronda, la riconciliazione — e
    che quindi ogni ambiente finto che le fa girare deve montare, o
    esplode con un NameError: la trappola delle funzioni estratte, al
    giro dopo. Ambiente PRIVATO, come `ambiente_in_pagamento`: si
    esportano i soli nomi del cantiere.
    SUI BANCHI DI IERI le colonne nuove possono non esserci (uno schema
    di cartone scritto a mano): `_dove_tentati` allora risponde vuoto e
    `cassaforte_payout` manca dalla riga, cioe' ogni hash si chiede alla
    cassaforte della riga e si paga da quella — il comportamento di
    ieri, ed e' il fail-open dichiarato."""
    p = {"sqlite3": __import__("sqlite3")}
    i = _SORGENTE.index("\nDEVIATO = ") + 1
    exec(_SORGENTE[i:_SORGENTE.index("\n", i)], p)
    for nome in ("_campo", "_dove_tentati", "_cassaforte_tentata",
                 "_cassaforte_uscita"):
        exec(pezzo(nome), p)
    return {n: p[n] for n in NOMI_ALTRA_CASSAFORTE}


def ambiente_scadenza():
    """I pezzi VERI del cantiere delle fatture scadute (20 set 2026),
    per gli ambienti finti che fanno girare `paga_venditore` e
    `_sblocca_sats`: da quel giorno la cintura della scadenza e i motivi
    in parole stanno DENTRO quelle due, e un ambiente che non li monta
    esplode con un NameError invece di provare qualcosa — la trappola
    delle funzioni estratte, al suo ennesimo giro. Si eseguono le fette
    del sorgente, mai una copia: e' la regola di `reale`.

    Le fatture di cartone dei banchi piu' vecchi («lnbc», «lnbc1»,
    «lnbc-fattura-1») il lettore vero non le legge, quindi di loro non
    afferma niente e la strada resta quella di ieri: e' il fail-open
    dichiarato, ed e' anche il motivo per cui quei banchi restano verdi
    senza toccarne una riga."""
    amb = {"time": time, "json": json, "html": __import__("html"),
           "_ponte": {"stato": "ok"}, "_lnd_motivi": {},
           "_fmt_sats": reale("_fmt_sats")}
    for inizio in ("MARGINE_SCADENZA_PAYOUT_S = ", "_BECH32_ALFABETO = ",
                   "MSG_FATTURA_PRESTO = (",
                   "MESI_IT = (", "MOTIVO_SCADUTA, MOTIVO_STRADA, ",
                   "PAROLE_MOTIVO = {", "_MOTIVI_LND = {"):
        i = _SORGENTE.index("\n" + inizio) + 1
        exec(_SORGENTE[i:_SORGENTE.index("\n\n", i)], amb)
    for nome in ("leggi_bolt11", "vita_fattura", "giorno_scadenza",
                 "rifiuto_scadenza", "_durata_a_parole", "_motivo_payout",
                 "_annota_motivo", "_ricorda_motivo_lnd",
                 "_msg_fattura_nuova"):
        exec(pezzo(nome), amb)
    amb.pop("__builtins__", None)
    # ...e dal cantiere dopo, quelli dello stadio «in pagamento»: chi
    # monta `_sblocca_sats` ha bisogno di tutt'e due le famiglie
    amb.update(ambiente_in_pagamento())
    amb["CASSAFORTE_NODO"] = "nodo"
    return amb


def prove_pagamenti_in_volo(attrezzi=False):
    """«NON E' USCITO» CHE NON PAGA DUE VOLTE (set 2026).

    L'audit del 19 set aveva riprodotto il doppio payout con le
    funzioni vere: un pagamento tenuto in volo da una hold invoice, un
    moderatore che dichiara «non e' uscito», una fattura nuova pagata, e
    poi la prima che si salda — 1000 dovuti, 2000 usciti. Quella
    riproduzione sta QUI, ed e' la prima prova della sezione: sul codice
    di prima e' ROSSA (2000), su questo e' verde (1000 e un 409).

    IL MONDO E' DI CARTONE MA LE FUNZIONI SONO TUTTE VERE: la strada
    d'uscita, `paga_venditore`, i timbri, il giudice, la ronda e la
    rotta del moderatore. Di finto ci sono i due estremi — LNbits (un
    httpx che tiene una riga per hash, come il vero) e LND (un
    dizionario dietro `_chiedi_lnd`) — piu' l'anagrafe e le notifiche.
    Ogni scena nasce in un mondo SUO: un lucchetto asyncio conteso in un
    event loop non si riusa in un altro.

    `attrezzi=True` (20 set 2026) non gira nessuna scena: RESTITUISCE il
    banco — `mondo` e i suoi aiutanti — a `prove_fatture_scadute`, che
    ha bisogno dello stesso mondo di cartone. Una seconda copia di
    duecento righe sarebbe la copia che un giorno resta indietro."""
    if not attrezzi:
        print("\n[i pagamenti in volo: «non e' uscito» che non paga due "
              "volte]")
    import asyncio
    import collections
    import sqlite3
    import time as _time

    def gira(coro):
        return asyncio.new_event_loop().run_until_complete(coro)

    try:
        K = costanti_verita()
    except ValueError:
        # il codice di PRIMA non ha nemmeno i nomi: la scena dell'audit
        # gira lo stesso (e' la numero 1 apposta), il resto esplodera'
        K = {}

    class Rifiuto(Exception):
        def __init__(self, status_code, detail=None):
            self.status_code, self.detail = status_code, detail

    class _R:
        def __init__(self, code, dati):
            self.status_code, self._d = code, dati

        def json(self):
            return self._d

    def mondo(invoice="", address="chi@wallet.tld", stato="delivered",
              condiviso=None):
        """Torna un oggetto con dentro tutto: `m.sblocca`, `m.ronda`,
        `m.decidi`, `m.nodo` (lnbits/lnd/partiti/modi/muto), `m.vero`
        (il database), `m.detto` (i print) e `m.avvisi`. Con `condiviso`
        si monta un SECONDO processo sugli stessi database e nodo: ha i
        suoi lucchetti, che e' tutto il punto."""
        m = type("Mondo", (), {})()
        if condiviso is None:
            vero = sqlite3.connect(":memory:")
            vero.row_factory = sqlite3.Row
            vero.execute(
                "CREATE TABLE ordini(id INTEGER PRIMARY KEY, annuncio_id INT,"
                " compratore_id INT, venditore_id INT, prezzo_sats INT, "
                "protezione_sats INT, quantita INT, stato TEXT, disputata "
                "INT, invoice_venditore TEXT, aggiornato INT, cambio_eur "
                "REAL, payout_stato TEXT, payout_hash TEXT, payout_verso "
                "TEXT, sbloccato_auto_il INT DEFAULT 0, cassaforte TEXT "
                "DEFAULT 'nodo', payout_tentativi INT DEFAULT 0, "
                "payout_ultimo INT DEFAULT 0, payout_errore TEXT DEFAULT '')")
            vero.execute(
                "INSERT INTO ordini VALUES(1,7,111,222,1000,0,1,?,0,?,0,0,"
                "'','','',0,'nodo',0,0,'')", (stato, invoice))
            vero.execute("CREATE TABLE utenti(tg_id INT, ln_address TEXT, "
                         "vendite_ok INT, acquisti_ok INT)")
            vero.execute("INSERT INTO utenti VALUES(222,?,0,0)", (address,))
            # la tabella VERA, con la sua chiave: e' l'ON CONFLICT che
            # la pezza usa, e uno schema ricopiato a meta' lo farebbe
            # esplodere qui invece che in produzione
            try:
                i = _SORGENTE.index(
                    '"CREATE TABLE IF NOT EXISTS payout_tentati("')
                j = _SORGENTE.index('hash))")', i) + len('hash))"')
                vero.execute(eval("(" + _SORGENTE[i:j] + ")"))
            except ValueError:
                # il codice di PRIMA non ha la tabella: la scena
                # dell'audit gira lo stesso, ed e' rossa per i 2000
                vero.execute("CREATE TABLE payout_tentati(tabella TEXT, "
                             "riga_id INT, hash TEXT, quando INT, esito TEXT)")
            # ...e la linea del tempo (set 2026, lo stadio «in
            # pagamento»), VERA anche lei: senza, ogni scena girerebbe
            # nel fail-open dei passi non scritti, cioe' proverebbe il
            # codice di ieri con 140 righe di lamento nel journal
            try:
                i = _SORGENTE.index(
                    '"CREATE TABLE IF NOT EXISTS payout_passi("')
                j = _SORGENTE.index('DEFAULT 1)")', i) + len('DEFAULT 1)"')
                vero.execute(eval("(" + _SORGENTE[i:j] + ")"))
            except ValueError:
                pass          # il codice di PRIMA: vedi qui sopra
            vero.commit()
            nodo = type("Nodo", (), {})()
            nodo.lnbits, nodo.lnd, nodo.partiti = {}, {}, []
            nodo.modi, nodo.muto, nodo.alla_post = {}, False, None
            nodo.coniate, nodo.timbri, nodo.alla_lnd = [], {}, None
            # LE LNBITS SONO DUE (21 set 2026): `lnbits` resta quella del
            # nodo — tutte le scene di ieri vivono li' — e `saas` e'
            # l'altra, che un LND dietro non ce l'ha. A distinguerle e'
            # l'URL, come in produzione. `chiesti` ricorda A CHI si e'
            # domandato ogni hash; `hash_di` e' come il nodo da' un nome
            # a una fattura (il cartone di sempre, o quello vero per chi
            # usa bolt11 che si leggono).
            nodo.saas, nodo.muto_saas, nodo.chiesti = {}, False, []
            nodo.bolt11_di, nodo.pagati_da = {}, []
            nodo.hash_di = lambda bolt: ("hash-di-" + bolt)[:100]
        else:
            vero, nodo = condiviso.vero, condiviso.nodo
        m.vero, m.nodo, m.detto, m.avvisi = vero, nodo, [], []

        class Con:
            def execute(self, *a):
                return vero.execute(*a)

            def commit(self):
                vero.commit()

            def close(self):
                pass

        class Client:
            def __init__(self, *a, **k):
                pass

            async def __aenter__(self):
                return self

            async def __aexit__(self, *a):
                return False

            async def get(self, url, headers=None, **k):
                await asyncio.sleep(0)
                di_la = "//saas" in url
                if nodo.muto_saas if di_la else nodo.muto:
                    raise OSError("ReadTimeout")
                banca = nodo.saas if di_la else nodo.lnbits
                h = url.rsplit("/", 1)[-1]
                nodo.chiesti.append(("saas" if di_la else "nodo", h))
                if h not in banca:
                    return _R(404, {})
                return _R(200, {"status": banca[h],
                                "paid": banca[h] == "success",
                                **({"details": {"bolt11": nodo.bolt11_di[h]}}
                                   if h in nodo.bolt11_di else {})})

            async def post(self, url, headers=None, json=None, **k):
                # TRONCO A 100, come fa `paga_venditore` col payment
                # hash: con una bolt11 VERA (300 caratteri) nodo e server
                # parlerebbero altrimenti di due pagamenti diversi
                h = nodo.hash_di(json["bolt11"])
                di_la = "//saas" in url
                banca = nodo.saas if di_la else nodo.lnbits
                if nodo.alla_post:
                    nodo.alla_post(h)
                await asyncio.sleep(0)
                modo = nodo.modi.get(json["bolt11"], "ok")
                if modo == "perso":        # mai arrivata nemmeno a LNbits
                    raise OSError("ConnectTimeout")
                if h in banca:             # una riga per hash: l'eco
                    return _R(201, {"status": banca[h]})
                nodo.partiti.append(h)
                nodo.pagati_da.append(("saas" if di_la else "nodo", h))
                if isinstance(modo, tuple):
                    # IL RIFIUTO COL SUO PERCHE' (20 set 2026): LNbits
                    # segna la riga `failed` e risponde un numero >= 300
                    # col motivo nel `detail` — il 520 dell'ordine #152
                    banca[h] = "failed"
                    return _R(modo[0], {"detail": modo[1]})
                lnb, lnd = {"ok": ("success", "SUCCEEDED"),
                            "hold": ("pending", "IN_FLIGHT"),
                            "fail": ("failed", "FAILED"),
                            "timeout_ok": ("success", "SUCCEEDED"),
                            "timeout_fail": ("failed", "FAILED"),
                            "mai_a_lnd": ("pending", None)}[modo]
                banca[h] = lnb
                if lnd and not di_la:      # il SaaS un LND nostro non ce l'ha
                    nodo.lnd[h] = lnd
                if modo.startswith("timeout"):
                    nodo.muto = True
                    raise OSError("ReadTimeout")
                return _R(201, {"status": lnb})

        async def _niente(*a, **k):
            return None

        async def _chiedi_lnd(h):
            await asyncio.sleep(0)
            if nodo.alla_lnd:
                nodo.alla_lnd()
            return nodo.lnd.get(h, K["LND_ASSENTE"])

        async def _decodifica(bolt11, cassaforte=""):
            return {"payment_hash": nodo.hash_di(bolt11),
                    "amount_msat": 1000 * 1000}

        async def _importo(bolt11, dec=None, cassaforte=""):
            return 1000

        async def _address(addr, sats):
            nodo.coniate.append(addr)
            return f"lnbc-fattura-{len(nodo.coniate)}"

        async def _avvisa(t):
            m.avvisi.append(t)

        async def _corpo(req):
            return req

        Cf = collections.namedtuple(
            "Cf", "nome LNBITS_URL LNBITS_INVOICE_KEY LNBITS_ADMIN_KEY")
        amb = {
            "db": Con, "time": _time, "asyncio": asyncio,
            "html": __import__("html"), "json": __import__("json"),
            "httpx": type("H", (), {"AsyncClient": Client}),
            "_lucchetti_ordine": collections.defaultdict(asyncio.Lock),
            "_chiavi_cassaforte":
                lambda nome="": Cf(nome or "nodo",
                                   "http://saas" if nome == "saas"
                                   else "http://finto", "k", "K"),
            "_cassaforte_riga": lambda con, tab, rid: "nodo",
            "CASSAFORTE_NODO": "nodo", "_chiedi_lnd": _chiedi_lnd,
            "timbro_letto": lambda k: nodo.timbri.get(k, ""),
            "timbro_scrivi": lambda k, v: nodo.timbri.__setitem__(k, v),
            "_lnd_canarino": {"ok_fino": 0.0},
            "decodifica_invoice": _decodifica, "importo_invoice": _importo,
            "invoice_da_ln_address": _address,
            "netto_venditore": lambda p: p, "_fmt_sats": reale("_fmt_sats"),
            "_righe_ordine": lambda con, o: [],
            "_titolo_ordine": lambda righe: "una cosa",
            "cambio_btc_eur": _niente, "notifica": _niente,
            "notifica_admin": _avvisa, "premia_distintivi": _niente,
            "polso_ordini_admin": _niente, "premia_xp": _niente,
            "xp_ordine": lambda *a: 0, "premia_reputazione_nostr": _niente,
            "PAGATO": "pagato", "NON_PAGATO": "non_pagato",
            "INCERTO": "incerto", "NON_CHIESTO": "non_chiesto",
            "OCCUPATO": "occupato", "LnbitsMuto": LnbitsMuto,
            "MAX_TENTATIVI_PAYOUT": 5, "IN_VOLO_LIMITE_S": 1800,
            "MAX_RIPRESE_GIRO": 20, "ATTESE_ESITO": 1,
            "SECONDI_FRA_ATTESE": 0,
            "verifica_utente": lambda *a: {"id": 999},
            "e_admin": lambda i: True, "leggi_json": _corpo,
            "HTTPException": Rifiuto, "Header": lambda *a: "",
            "Cookie": lambda *a: "", "Request": object,
            "print": lambda *a, **k: m.detto.append(" ".join(map(str, a))),
            **ambiente_scadenza(), **K}
        # l'orologio e' di QUESTO mondo: `ambiente_scadenza` porta il
        # suo, e qui deve vincere quello che le scene possono fermare
        amb["time"] = _time
        for nome, asincrona in (
                ("_esito_lnbits", 0), ("_stato_pagamento", 1),
                ("_avvisa_payout_fallito", 1), ("_lnd_ci_vede", 1),
                ("_stato_lnd", 1), ("_voce_lnd", 0),
                ("_verdetto_pagamento", 0),
                ("_verita_pagamento", 1), ("_hash_tentati", 0),
                ("_verita_riga", 1), ("_prendi_la_mano", 0),
                ("paga_venditore", 1), ("_timbra_pagamento", 0),
                ("_in_volo", 0), ("_sospendi_pagamento", 0),
                ("_payment_hash", 1), ("_congela_pagamento", 1),
                ("_msg_ritentiamo", 0), ("_sblocca_sats", 1),
                ("_riprendi_uscita", 1), ("_arrenditi_in_volo", 1),
                ("risolvi_pagamenti_in_volo", 1), ("decidi_pagamento", 1),
                ("deposita_invoice", 1)):
            try:
                exec(("async " if asincrona else "") + pezzo(nome), amb)
            except ValueError:
                # sul codice di PRIMA i pezzi nuovi non ci sono: la scena
                # dell'audit deve poter girare anche la', ed essere rossa
                # per il motivo giusto (2000 usciti), non per un NameError
                pass
        m.amb = amb
        m.sblocca = lambda: amb["_sblocca_sats"](1)
        m.ronda = lambda: amb["risolvi_pagamenti_in_volo"]()
        m.decidi = lambda esito, **k: amb["decidi_pagamento"](
            {"tipo": "ordine", "id": 1, "esito": esito, **k})
        return m

    def riga(m):
        r = m.vero.execute("SELECT stato, payout_stato, payout_hash FROM "
                           "ordini WHERE id=1").fetchone()
        return tuple(r)

    def saldati(m):
        return [h for h in m.nodo.partiti
                if m.nodo.lnd.get(h) == "SUCCEEDED"
                or m.nodo.lnbits.get(h) == "success"]

    def invecchia(m, secondi):
        m.vero.execute("UPDATE ordini SET payout_ultimo=payout_ultimo-?",
                       (secondi,))
        m.vero.execute("UPDATE payout_tentati SET quando=quando-?",
                       (secondi,))
        m.vero.commit()

    def canarino(m):
        m.nodo.lnd["hash-di-ieri"] = "SUCCEEDED"
        m.nodo.timbri[K["TIMBRO_CANARINO"]] = "hash-di-ieri"

    def campo(risposta, chiave):
        # una risposta che doveva essere un dizionario e invece e' un
        # rifiuto deve far cadere la prova ROSSA, non farla esplodere
        return risposta.get(chiave) if isinstance(risposta, dict) else None

    async def prova_a(coro):
        try:
            return await coro
        except Rifiuto as e:
            return e

    if attrezzi:
        return {"mondo": mondo, "gira": gira, "riga": riga, "K": K,
                "prova_a": prova_a, "invecchia": invecchia,
                "canarino": canarino}

    # --- 1. LA RIPRODUZIONE DELL'AUDIT ------------------------------
    m = mondo()
    m.nodo.modi["lnbc-fattura-1"] = "hold"
    gira(m.sblocca())
    prova("audit: la hold invoice lascia il payout in volo",
          ("delivered", "in_volo", "hash-di-lnbc-fattura-1"), riga(m))
    invecchia(m, 3600)
    gira(m.ronda())
    prova("audit: dopo mezz'ora la ronda lo consegna a una persona",
          "incerto", riga(m)[1])
    # il moderatore dice «non e' uscito» col NOME DI IERI, che e' quello
    # che il codice vecchio capiva: sul nuovo vale «verifica»
    esito = gira(prova_a(m.decidi("non_uscito")))
    prova("audit: «non e' uscito» su un pagamento in volo e' RIFIUTATO",
          409, getattr(esito, "status_code", None))
    prova("...e la riga resta congelata, col nome del pagamento vero",
          ("delivered", "incerto", "hash-di-lnbc-fattura-1"), riga(m))
    gira(m.sblocca())       # il compratore ripreme «Conferma»
    m.nodo.lnd["hash-di-lnbc-fattura-1"] = "SUCCEEDED"   # e il ladro salda
    m.nodo.lnbits["hash-di-lnbc-fattura-1"] = "success"
    prova("audit: 1000 dovuti, 1000 usciti (erano 2000)",
          ["hash-di-lnbc-fattura-1"], saldati(m))
    prova("...e nessuna seconda fattura e' mai stata pagata",
          ["hash-di-lnbc-fattura-1"], m.nodo.partiti)
    gira(m.ronda())
    prova("audit: saldata la prima, la ronda chiude da sola come pagato",
          ("released", "uscito"), riga(m)[:2])
    prova("...avvisando che il congelato si e' chiarito da solo", True,
          any("chiarito da solo" in a for a in m.avvisi))

    # --- 2. IL GIUDICE, riga per riga -------------------------------
    giudice = reale("_verdetto_pagamento", dict(K))
    N = K["MAI_PARTITO_DOPO_S"]
    for lnbits, lnd, eta, atteso in (
            ("pending", "SUCCEEDED", 5, "uscito"),
            ("muto", "SUCCEEDED", 5, "uscito"),
            ("failed", "SUCCEEDED", 5, "uscito"),
            ("success", "IN_FLIGHT", 5, "in_volo"),
            ("muto", "IN_FLIGHT", 99999, "in_volo"),
            ("failed", "IN_FLIGHT", 99999, "in_volo"),
            ("success", "assente", 5, "uscito"),      # interno a LNbits
            ("success", "spento", 5, "uscito"),
            ("success", "FAILED", 5, "ignoto"),       # uno dei due mente
            ("pending", "FAILED", 5, "fallito"),
            ("muto", "FAILED", 5, "fallito"),
            ("pending", "muto", 99999, "in_volo"),
            ("pending", "spento", 99999, "in_volo"),
            ("muto", "muto", 99999, "ignoto"),
            ("muto", "spento", 99999, "ignoto"),
            ("failed", "muto", 99999, "ignoto"),
            ("assente", "muto", 99999, "ignoto"),
            ("failed", "spento", 5, "fallito"),       # la regola di sempre
            ("failed", "assente", 5, "in_volo"),
            ("failed", "assente", N, "fallito"),
            ("pending", "assente", N - 1, "in_volo"),
            ("pending", "assente", N, "mai_partito"),
            ("muto", "assente", N, "ignoto"),
            ("assente", "assente", N - 1, "in_volo"),
            ("assente", "assente", N, "mai_partito"),
            ("assente", "spento", N - 1, "in_volo"),
            ("assente", "spento", N, "mai_partito"),
            ("assente", "assente", None, "mai_partito"),   # mai tentato
            ("assente", "muto", None, "mai_partito"),
            ("assente", "spento", None, "mai_partito"),
            ("muto", "muto", None, "ignoto")):
        prova(f"giudice: LNbits {lnbits}, LND {lnd}, eta {eta} → {atteso}",
              atteso, giudice(lnbits, lnd, eta))
        if lnd == "spento":
            prova(f"giudice: ...e con LND n/a (il SaaS) e' lo stesso",
                  atteso, giudice(lnbits, "n/a", eta))
    prova("N e' almeno un battito dell'orologio (600 s)", True, N >= 600)

    # --- 3. IL LETTORE DI LND ---------------------------------------
    leggi = reale("_lnd_stato_da_riga", {**K, "json": __import__("json")})
    for corpo, atteso in (
            ('{"result":{"status":"SUCCEEDED"}}', "SUCCEEDED"),
            ('{"result":{"status":"IN_FLIGHT","htlcs":[]}}', "IN_FLIGHT"),
            ('{"result":{"status":"FAILED","failure_reason":"X"}}', "FAILED"),
            ('{"status":"SUCCEEDED"}', "SUCCEEDED"),
            ('{"error":{"code":5,"message":"payment isn\'t initiated"}}',
             "assente"),
            ('{"code":5,"message":"payment isn\'t initiated","details":[]}',
             "assente"),
            # LA RIGA CHE CONTA: «Not Found» e' anche la risposta a una
            # ROTTA sbagliata, e non deve MAI valere «il pagamento non c'e'»
            ('{"code":5,"message":"Not Found","details":[]}', "muto"),
            ('{"error":{"code":5,"message":"Not Found"}}', "muto"),
            ('{"error":{"code":2,"message":"permission denied"}}', "muto"),
            ('{"result":{"status":"UNKNOWN"}}', "muto"),
            ('<html>502 Bad Gateway</html>', "muto"), ('[]', "muto"),
            ('', "muto")):
        prova(f"LND: {corpo[:44] or '(vuoto)'} → {atteso}", atteso,
              leggi(corpo))

    # --- 4. IL CANARINO ---------------------------------------------
    m = mondo()
    prova("senza canarino un «assente» di LND NON si crede (muto)", "muto",
          gira(m.amb["_stato_lnd"]("hash-mai-visto", "nodo")))
    canarino(m)
    prova("...a canarino vivo si'", "assente",
          gira(m.amb["_stato_lnd"]("hash-mai-visto", "nodo")))
    m.amb["_lnd_canarino"]["ok_fino"] = 0.0
    m.nodo.lnd.pop("hash-di-ieri")          # LND ripristinato senza storia
    prova("...e se LND non riconosce piu' nemmeno il canarino, di nuovo no",
          "muto", gira(m.amb["_stato_lnd"]("hash-mai-visto", "nodo")))
    # LND=n/a (22 set 2026): il 20 set, sull'ordine #152, la riga del
    # SaaS diceva «LND=spento» nel journal — la stessa parola del
    # macaroon che manca — e ci ha fatto cercare un guasto che non c'era
    prova("una riga del SaaS non ha un LND nostro: n/a, NON spento", "n/a",
          gira(m.amb["_stato_lnd"]("hash-mai-visto", "saas")))
    prova("...e una senza hash nemmeno", "n/a",
          gira(m.amb["_stato_lnd"]("", "nodo")))
    _amb_chiedi = {**K, "_lnd_configurato": lambda: False}
    exec("async " + pezzo("_chiedi_lnd"), _amb_chiedi)
    _chiedi_vero = _amb_chiedi["_chiedi_lnd"]
    prova("...mentre «spento» resta del NODO senza macaroon di lettura",
          "spento", gira(_chiedi_vero("ab" * 32)))
    _amb_spento = dict(m.amb)
    _amb_spento["_chiedi_lnd"] = _chiedi_vero
    exec("async " + pezzo("_stato_lnd"), _amb_spento)
    prova("...cioe' una riga del nodo, a macaroon mancante, dice spento",
          "spento", gira(_amb_spento["_stato_lnd"]("ab" * 32, "nodo")))
    voce = m.amb["_voce_lnd"]
    prova("il pannello 🧊 dice PERCHE' LND non ha parlato, nei due casi",
          [True, True, "LND dice «FAILED»"],
          ["non è un pagamento del nodo" in voce("n/a"),
           "manca il macaroon" in voce("spento"), voce("FAILED")])

    # --- 5. LNBITS MUTO, LND CHE SA (l'ordine #163 del 18 set) ------
    m = mondo()
    m.nodo.modi["lnbc-fattura-1"] = "timeout_ok"
    gira(m.sblocca())
    prova("#163: ReadTimeout sulla richiesta → in volo, non perso",
          ("delivered", "in_volo"), riga(m)[:2])
    gira(m.ronda())
    prova("#163: LNbits muto ma LND dice SUCCEEDED → chiuso da solo",
          ("released", "uscito"), riga(m)[:2])
    prova("...con un pagamento solo", 1, len(m.nodo.partiti))
    prova("...senza svegliare nessuno", [], m.avvisi)

    m = mondo()
    m.nodo.modi["lnbc-fattura-1"] = "timeout_fail"
    gira(m.sblocca())
    gira(m.ronda())
    prova("LNbits muto e LND dice FAILED → il fermo cade, e a LNbits "
          "muto non parte niente", ("delivered", "da_riprovare"),
          riga(m)[:2])
    m.nodo.muto = False
    gira(m.sblocca())
    prova("...tornata LNbits si ripaga, con una fattura NUOVA",
          ("released", 2, True),
          (riga(m)[0], len(m.nodo.partiti),
           m.nodo.partiti[-1] != "hash-di-lnbc-fattura-1"))
    prova("...e di saldato ce n'e' uno solo",
          [m.nodo.partiti[-1]], saldati(m))

    # --- 6. LND NON HA MAI VISTO L'HASH ------------------------------
    m = mondo(invoice="lnbc-del-venditore", address="")
    canarino(m)
    m.nodo.modi["lnbc-del-venditore"] = "perso"
    gira(m.sblocca())
    prova("richiesta persa: la riga e' in volo col suo nome",
          ("delivered", "in_volo", "hash-di-lnbc-del-venditore"), riga(m))
    gira(m.ronda())
    prova("...e prima di N minuti «non c'e' traccia» NON vale mai partito",
          "in_volo", riga(m)[1])
    invecchia(m, N + 1)
    m.nodo.modi["lnbc-del-venditore"] = "ok"
    gira(m.ronda())
    prova("...dopo N si chiude come mai partito e si RITENTA, con la "
          "stessa fattura che e' ancora buona",
          ("released", ["hash-di-lnbc-del-venditore"]),
          (riga(m)[0], m.nodo.partiti))

    m = mondo()
    m.nodo.modi["lnbc-fattura-1"] = "mai_a_lnd"     # LNbits pending, LND no
    gira(m.sblocca())
    invecchia(m, N + 1)
    gira(m.ronda())
    prova("assente SENZA canarino: non si ritenta, nemmeno dopo N",
          ("delivered", "in_volo", 1),
          (*riga(m)[:2], len(m.nodo.partiti)))

    # --- 7. IL BOTTONE «VERIFICA E RIPROVA» -------------------------
    def congelato(modo):
        m = mondo()
        m.nodo.modi["lnbc-fattura-1"] = modo
        gira(m.sblocca())
        m.vero.execute("UPDATE ordini SET payout_stato='incerto'")
        m.vero.commit()
        return m

    m = congelato("fail")
    # `fail` torna NON_PAGATO e non congela: la riga si congela a mano,
    # com'era sul #163 dopo il giro della ronda
    esito = gira(prova_a(m.decidi("verifica")))
    prova("verifica su FALLITO: RITENTA DAVVERO (il #163 sbloccava e basta)",
          ("ritentato", "released", 2),
          (campo(esito, "esito"), riga(m)[0], len(m.nodo.partiti)))
    prova("...e lo dice con parole sue", True,
          "ripagato" in (campo(esito, "messaggio") or "").lower())
    prova("...pagando una volta sola", ["hash-di-lnbc-fattura-2"],
          saldati(m))

    m = congelato("timeout_ok")
    m.nodo.muto = False
    esito = gira(prova_a(m.decidi("verifica")))
    prova("verifica su USCITO: chiude come pagato, senza pagare",
          ("chiuso", "released", 1),
          (campo(esito, "esito"), riga(m)[0], len(m.nodo.partiti)))

    m = congelato("hold")
    for gesto, extra in (("verifica", {}), ("uscito", {}),
                         ("uscito", {"conferma": True})):
        esito = gira(prova_a(m.decidi(gesto, **extra)))
        prova(f"in volo: «{gesto}»{' con conferma' if extra else ''} → 409, "
              f"resta congelato", (409, "incerto"),
              (getattr(esito, "status_code", None), riga(m)[1]))
    prova("...e la frase dice IN VOLO", True,
          "IN VOLO" in str(getattr(esito, "detail", "")))

    m = congelato("timeout_fail")          # LNbits muta, LND dice FAILED
    esito = gira(prova_a(m.decidi("uscito")))
    prova("«uscito» con LND che dice FAILED: chiede la conferma esplicita",
          (409, True, "incerto"),
          (getattr(esito, "status_code", None),
           isinstance(getattr(esito, "detail", None), dict)
           and esito.detail.get("serve_conferma"), riga(m)[1]))
    prova("...mostrando cosa dicono le fonti", True,
          "FAILED" in str(getattr(esito, "detail", "")))
    esito = gira(prova_a(m.decidi("uscito", conferma=True)))
    prova("...e con la conferma la parola della persona vale",
          ("chiuso", "released", 1),
          (campo(esito, "esito"), riga(m)[0], len(m.nodo.partiti)))

    # LND=n/a NEL PANNELLO 🧊 (22 set 2026): un tentativo sulla
    # cassaforte SaaS, appena partito. LND li' non si applica, e chi
    # modera deve leggere che non e' un guasto del ponte — non un
    # «spento» nudo, che il 20 set sul #152 ha fatto cercare quello
    m = congelato("hold")
    m.amb["_cassaforte_riga"] = lambda con, tab, rid: "saas"
    m.vero.execute("UPDATE payout_tentati SET cassaforte='saas'")
    m.vero.execute("UPDATE ordini SET cassaforte='saas'")
    m.vero.commit()
    esito = gira(prova_a(m.decidi("verifica")))
    prova("tentativo sul SaaS: il pannello dice «n/a» e PERCHE', mai "
          "«spento»", (409, True, False),
          (getattr(esito, "status_code", None),
           "LND dice «n/a» (non è un pagamento del nodo"
           in str(getattr(esito, "detail", "")),
           "spento" in str(getattr(esito, "detail", ""))))

    m = congelato("hold")
    m.nodo.muto = True
    m.nodo.lnd.clear()                      # tacciono tutti: LND 'assente'
    esito = gira(prova_a(m.decidi("verifica")))   # ...e senza canarino
    prova("non verificabile: 503, non parte niente, resta congelato",
          (503, "incerto", 1),
          (getattr(esito, "status_code", None), riga(m)[1],
           len(m.nodo.partiti)))

    # --- 8. UNA SOLA MANO PAGA --------------------------------------
    m = congelato("fail")

    async def due_click():
        return await asyncio.gather(prova_a(m.decidi("verifica")),
                                    prova_a(m.decidi("verifica")))
    primo, secondo = gira(due_click())
    prova("doppio click: uno decide, l'altro trova il 409",
          ["409", "deciso"],
          sorted(str(getattr(x, "status_code", "deciso"))
                 for x in (primo, secondo)))
    prova("...e il ritentativo e' uno solo", 2, len(m.nodo.partiti))

    m = mondo()

    async def due_conferme():
        return await asyncio.gather(m.sblocca(), m.sblocca())
    gira(due_conferme())
    prova("due conferme insieme, stesso processo: un pagamento solo",
          (1, "released"), (len(m.nodo.partiti), riga(m)[0]))

    a = mondo()
    b = mondo(condiviso=a)      # un SECONDO processo: lucchetti suoi

    async def due_processi():
        return await asyncio.gather(a.sblocca(), b.sblocca())
    esiti = gira(due_processi())
    prova("due giri concorrenti, due processi: un pagamento solo",
          1, len(a.nodo.partiti))
    prova("...e chi perde la mano esce senza toccare la riga",
          ("released", "uscito"), riga(a)[:2])
    prova("...rispondendo «in volo», non «serve una fattura nuova»",
          [{"ok": False, "stato": "delivered", "in_volo": True}],
          [e for e in esiti if not e.get("ok")])

    # LA SECONDA CINTURA, quella che regge anche se la prima cede: la
    # riga e' LIBERA (uno l'ha liberata a mano, o e' una riga di ieri)
    # ma un suo pagamento di prima e' ancora in volo. Non si paga.
    m = mondo()
    m.nodo.modi["lnbc-fattura-1"] = "hold"
    gira(m.sblocca())
    m.vero.execute("UPDATE ordini SET payout_stato=''")
    m.vero.commit()
    gira(m.sblocca())
    prova("riga liberata a mano col vecchio in volo: NON si paga, e torna "
          "in volo col nome del pagamento vero",
          ("delivered", "in_volo", "hash-di-lnbc-fattura-1", 1),
          (*riga(m), len(m.nodo.partiti)))
    # ...e se quel pagamento di prima e' USCITO, la riga e' pagata
    m.nodo.lnd["hash-di-lnbc-fattura-1"] = "SUCCEEDED"
    m.vero.execute("UPDATE ordini SET payout_stato=''")
    m.vero.commit()
    gira(m.sblocca())
    prova("riga libera col vecchio USCITO: si chiude come pagata, senza "
          "pagare la fattura nuova",
          ("released", "uscito", "hash-di-lnbc-fattura-1", 1),
          (*riga(m), len(m.nodo.partiti)))

    # la ronda chiede (e ci mette dei secondi, su tor): se nel frattempo
    # ha deciso una persona, la ronda NON riscrive
    m = mondo()
    m.nodo.modi["lnbc-fattura-1"] = "timeout_fail"
    gira(m.sblocca())

    def una_persona_decide():
        m.vero.execute("UPDATE ordini SET payout_stato='uscito', "
                       "stato='released'")
        m.vero.commit()
    m.nodo.alla_lnd = una_persona_decide
    gira(m.ronda())
    prova("la ronda non riscrive una riga decisa mentre lei chiedeva",
          ("released", "uscito"), riga(m)[:2])

    # a tentativi finiti un INCERTO congela: e il nome che resta sulla
    # riga dev'essere quello del pagamento IN VOLO, non quello della
    # fattura nuova che non abbiamo pagato
    m = mondo()
    m.nodo.modi["lnbc-fattura-1"] = "hold"
    gira(m.sblocca())
    m.vero.execute("UPDATE ordini SET payout_stato='', payout_tentativi=5")
    m.vero.commit()
    gira(m.sblocca())
    prova("il vecchio e' in volo e i tentativi sono finiti: si congela "
          "col nome del pagamento VERO",
          ("delivered", "incerto", "hash-di-lnbc-fattura-1", 1),
          (*riga(m), len(m.nodo.partiti)))
    prova("...dicendolo nel journal", True,
          any("un'altra mano" in r for r in a.detto + b.detto))

    # --- 9. IL RIAVVIO A META' PAYOUT -------------------------------
    m = mondo()
    visto = []
    m.nodo.alla_post = lambda h: visto.append(
        (riga(m), [tuple(r) for r in m.vero.execute(
            "SELECT tabella, riga_id, hash FROM payout_tentati")]))
    gira(m.sblocca())
    prova("lo stato e' scritto PRIMA di chiamare LNbits: in volo, col nome",
          (("delivered", "in_volo", "hash-di-lnbc-fattura-1"),
           [("ordini", 1, "hash-di-lnbc-fattura-1")]), visto[0])

    # --- 10. IL JOURNAL ---------------------------------------------
    m = congelato("hold")
    gira(prova_a(m.decidi("verifica")))
    verifica = [r for r in m.detto if "Verifica pagamento" in r]
    prova("journal: ogni verifica scrive ordine, hash, LNbits, LND, esito",
          True, any("ordini#1" in r and "hash-di-lnbc-fat" in r
                    and "LNbits=pending" in r and "LND=IN_FLIGHT" in r
                    and "→ in_volo" in r for r in verifica))
    prova("journal: ogni decisione scrive chi, cosa ha chiesto e com'e' "
          "finita", True,
          any("Decisione sul pagamento ordini#1" in r and "999" in r
              and "verifica" in r and "RIFIUTATO" in r for r in m.detto))

    # --- 11. LE SENTINELLE ------------------------------------------
    sorg = codice(_SORGENTE)
    chiamate = re.findall(
        r"await paga_venditore\((?:[^()]|\([^()]*\))*\)", sorg)
    prova("le funzioni d'uscita sono quattro", 4, len(chiamate))
    prova("...e tutte passano la RIGA a paga_venditore", [],
          [c for c in chiamate if "riga=(" not in c])
    pv = codice(pezzo("paga_venditore"))
    prova("la mano si prende PRIMA della chiave che paga", True,
          0 < pv.find("_prendi_la_mano(") < pv.find("LNBITS_ADMIN_KEY"))
    prova("...e gli hash di prima si guardano prima ancora", True,
          0 < pv.find("_verita_riga(") < pv.find("_prendi_la_mano("))
    dec = codice(pezzo("decidi_pagamento"))
    prova("la rotta del moderatore chiede la verita' PRIMA di scrivere",
          True, 0 < dec.find("_verita_riga(")
          < dec.find('f"UPDATE {tabella} SET payout_stato=?'))
    prova("...e ritenta passando dalla funzione d'uscita", True,
          "_riprendi_uscita(tabella, riga_id, verso)" in dec)
    ronda = codice(pezzo("risolvi_pagamenti_in_volo"))
    prova("la ronda chiede a tutt'e due le fonti, non alla sola LNbits",
          True, "_verita_pagamento(" in ronda
          and "_stato_pagamento(" not in ronda)
    prova("...e riguarda anche i congelati che hanno un nome", True,
          "payout_stato='incerto'" in ronda)
    lnd = codice(pezzo("_chiedi_lnd"))
    prova("a LND si parla col certificato guardato, mai a occhi chiusi",
          True, "cafile=LND_PONTE_CERT" in lnd and "verify=False" not in lnd)
    prova("...e del guasto si stampa il tipo, mai il macaroon", True,
          "type(e).__name__" in lnd
          and "MACAROON" not in lnd[lnd.find("except Exception"):])
    mini = open("miniapp.html", encoding="utf-8").read()
    prova("il bottone si chiama «Verifica e riprova» e manda 'verifica'",
          True, "Verifica e riprova" in mini
          and "decidiPagamento('${esc(p.tipo)}',${p.id},'verifica')" in mini)
    prova("...e il vecchio «Non è uscito — riprova» non c'e' piu'", False,
          "Non è uscito — riprova" in mini)
    prova("...e la conferma esplicita ha la sua strada nel client", True,
          "serve_conferma" in mini and "conferma:true" in
          mini.replace(" ", ""))


def prove_fatture_scadute():
    """UNA FATTURA SCADUTA NON SI TENTA, E SI DICE PERCHE' (20 set 2026).

    IL CASO VERO, ordine #152: fattura Zeus incollata alla spedizione,
    payout alla consegna confermata quattro giorni dopo, fattura
    scaduta da quattro. LND la rifiuta prima di cercare una strada,
    LNbits risponde 520, noi scrivevamo «LNbits ha risposto 520» a chi
    modera e «la rete non ha trovato una strada» a chi vendeva.

    IL MONDO E' QUELLO DEI PAGAMENTI IN VOLO (`attrezzi=True`), con le
    funzioni tutte vere; di nuovo ci sono le FATTURE, che qui sono
    bolt11 sintatticamente vere (`bolt11_finta`: bech32 col suo
    checksum, la scadenza nel campo `x`) — perche' il giudice della
    scadenza la legge dalla fattura, e una stringa di cartone non gli
    dice niente. L'hash resta quello di cartone del banco."""
    print("\n[le fatture scadute al payout: non si tentano, e si dice "
          "perche']")
    import calendar
    import shutil
    import subprocess
    import tempfile

    a = prove_pagamenti_in_volo(attrezzi=True)
    mondo, gira, riga = a["mondo"], a["gira"], a["riga"]
    prova_a, canarino = a["prova_a"], a["canarino"]
    S = ambiente_scadenza()
    adesso = int(time.time())
    GIORNO = 86400
    M = S["MARGINE_SCADENZA_PAYOUT_S"]
    MI = S["MARGINE_SCADENZA_INCOLLA_S"]

    # --- 0. I DUE NUMERI (il terzo e' uscito il 21 set 2026) ---------
    # Le scene del limite SEGUONO le costanti (o resterebbero rosse a
    # ogni taratura), quindi da sole non le difendono: a margine zero
    # erano tutte verdi, l'ha trovato la tortura. Qui si difende il
    # SENSO: minuti e non secondi, e ogni margine piu' largo del
    # precedente, che e' l'ordine in cui il tempo passa.
    prova("il margine del payout e' di MINUTI: non zero, non ore", True,
          60 <= M <= 600)
    prova("...quello della porta lo contiene, e resta sotto l'ora dei "
          "wallet comuni", True, M < MI <= 1800)
    # L'ANTICIPATA NON C'E' PIU' (21 set 2026): la fattura si incolla
    # solo all'incasso, quindi il numero che giudicava quella incollata
    # prima non ha piu' un caso. Si guardano i NOMI dell'albero
    # sintattico e non il testo: commenti e docstring la nominano
    # apposta, per dire perche' e' uscita, e una ricerca sul testo
    # risponderebbe per loro.
    import ast
    nomi = {n.id for n in ast.walk(ast.parse(_SORGENTE))
            if isinstance(n, ast.Name)}
    prova("`FATTURA_ANTICIPATA_GIORNI` e' uscita: nessuno la assegna, "
          "nessuno la legge", (False, False),
          ("FATTURA_ANTICIPATA_GIORNI" in S,
           "FATTURA_ANTICIPATA_GIORNI" in nomi))
    prova("...e il controllo dei nomi vede davvero (la sorella c'e')", True,
          "MARGINE_SCADENZA_INCOLLA_S" in nomi)

    # --- 1. IL LETTORE ----------------------------------------------
    leggi = S["leggi_bolt11"]
    vera = leggi(BOLT11_VERA_7468) or {}
    prova("lettore: la fattura vera del 16 set nasce alle 14:28:38 UTC",
          calendar.timegm((2026, 9, 16, 14, 28, 38)), vera.get("quando"))
    prova("...dura un'ora, e scade un'ora dopo", (3600, 3600),
          (vera.get("scadenza"), vera.get("scade", 0) - vera.get("quando", 0)))
    f30 = bolt11_finta(1000, 30 * GIORNO, adesso)
    prova("lettore: una fattura da trenta giorni, andata e ritorno",
          {"quando": adesso, "scadenza": 30 * GIORNO,
           "scade": adesso + 30 * GIORNO}, leggi(f30))
    prova("lettore: senza il campo della scadenza vale un'ora (BOLT-11)",
          3600, (leggi(bolt11_finta(1000, None, adesso)) or {}).get(
              "scadenza"))
    prova("lettore: MAIUSCOLA si legge uguale", leggi(f30),
          leggi(f30.upper()))
    # LA FIRMA NON SONO CAMPI: questi 104 gruppi cominciano come un
    # campo `x` da 31 secondi, e un lettore che non si ferma prima della
    # firma darebbe per morta una fattura da trenta giorni
    firmata = bolt11_finta(1000, 30 * GIORNO, adesso,
                           firma=[6, 0, 1, 31] + [0] * 100)
    prova("lettore: la firma non si legge come un campo", 30 * GIORNO,
          (leggi(firmata) or {}).get("scadenza"))
    rotta = f30[:-1] + ("q" if f30[-1] != "q" else "p")
    prova("lettore: un carattere cambiato e il checksum la boccia", None,
          leggi(rotta))
    prova("lettore: il cartone dei banchi vecchi non si legge (e va bene)",
          [None] * 7,
          [leggi(x) for x in ("", None, "lnbc", "lnbc1", "lnbc-fattura-1",
                              "lnurl1dp68gurn8ghj7", "ciao")])

    # --- 2. IL GEMELLO: client e server leggono le stesse fatture ----
    node = shutil.which("node")
    if not node:
        salta("il lettore del server e quello del client sono gemelli",
              "node non c'e'")
    else:
        mini = open("miniapp.html", encoding="utf-8").read()
        mazzo = [BOLT11_VERA_7468, f30, rotta, "lnbc1", firmata,
                 bolt11_finta(1000, None, adesso),
                 bolt11_finta(21, 600, adesso - 900),
                 bolt11_finta(0, 86400, adesso)]
        js = (pezzo_js(mini, "function importoBolt11(pr){", "\n}\n") + "\n}\n"
              + pezzo_js(mini, "function leggiBolt11(pr){", "\n}\n") + "\n}\n"
              + "console.log(JSON.stringify(" + json.dumps(mazzo)
              + ".map(leggiBolt11)));\n")
        with tempfile.NamedTemporaryFile("w", suffix=".js", delete=False,
                                         encoding="utf-8") as f:
            f.write(js)
        try:
            out = subprocess.run([node, f.name], capture_output=True,
                                 encoding="utf-8", timeout=60)
            dal_client = [None if x is None else
                          {k: x[k] for k in ("quando", "scadenza", "scade")}
                          for x in json.loads(out.stdout or "[]")]
        except Exception as e:
            dal_client = f"node e' esploso: {e}"
        finally:
            os.unlink(f.name)
        prova("gemelli: `leggiBolt11` e `leggi_bolt11` dicono le stesse "
              "cose di otto fatture", [leggi(x) for x in mazzo], dal_client)

    # --- 3. LA VITA, IL GIORNO, IL RIFIUTO ALLA PORTA ---------------
    vita = S["vita_fattura"]
    prova("vita: quel che resta, al secondo", 30 * GIORNO - 5,
          vita(f30, adesso + 5))
    prova("vita: negativa se e' scaduta", True,
          vita(BOLT11_VERA_7468) < -3 * GIORNO)
    prova("vita: di una fattura che non si legge non si afferma niente",
          None, vita("lnbc-fattura-1"))
    prova("giorno: «il 16 settembre», senza l'ora", "il 16 settembre",
          S["giorno_scadenza"](BOLT11_VERA_7468))
    prova("giorno: scaduta oggi si dice «oggi»", "oggi",
          S["giorno_scadenza"](bolt11_finta(1000, 3600, adesso - 3600)))
    prova("giorno: vuoto se non si legge", "", S["giorno_scadenza"]("lnbc1"))
    no = S["rifiuto_scadenza"]
    prova("porta: una fattura scaduta si rifiuta, col giorno", True,
          "già scaduta" in no(BOLT11_VERA_7468)
          and "16 settembre" in no(BOLT11_VERA_7468))
    al_limite = bolt11_finta(1000, 3600, adesso - 3600 + MI)
    prova("porta: al LIMITE del margine passa", "",
          no(al_limite, adesso))
    prova("...e un secondo sotto no", True,
          "scade fra" in no(al_limite, adesso + 1))
    un_ora = bolt11_finta(1000, 3600, adesso - 5)
    prova("porta: la fattura «da un'ora» va bene — da qui si paga subito",
          "", no(un_ora))
    prova("porta: il cartone non si rifiuta (fail-open dichiarato)", "",
          no("lnbc-fattura-1"))
    # UNA DOMANDA SOLA (21 set 2026): il ramo «si paga fra giorni» e'
    # uscito col caso che giudicava. Se tornasse un secondo parametro
    # tornerebbe anche la domanda «e quando NON si paga subito?», che
    # da questa porta non ha piu' una risposta.
    import inspect
    prova("porta: `rifiuto_scadenza` fa UNA domanda (la fattura, e "
          "l'orologio per le prove)", ["bolt11", "adesso"],
          list(inspect.signature(no).parameters))

    # --- 4. I MOTIVI, IN PAROLE -------------------------------------
    motivo = S["_motivo_payout"]
    for testo, lnd, atteso in (
            ("", "FAILURE_REASON_NO_ROUTE", "nessuna_strada"),
            ("", "FAILURE_REASON_TIMEOUT", "tempo"),
            ("", "FAILURE_REASON_INSUFFICIENT_BALANCE", "saldo"),
            ("", "FAILURE_REASON_INCORRECT_PAYMENT_DETAILS", "rifiutata"),
            # LND vince sul testo di LNbits: e' lui che l'ha avuto in mano
            ("invoice expired", "FAILURE_REASON_NO_ROUTE", "nessuna_strada"),
            ("Payment failed: invoice expired. Valid until 2026", "",
             "scaduta"),
            ("Payment failed: no_route", "", "nessuna_strada"),
            ("unable to find a path to destination", "", "nessuna_strada"),
            ("Insufficient balance.", "", "saldo"),
            ("Unable to connect to LND", "", "ponte"),
            ("payment timed out", "", "tempo"),
            ("FAILURE_REASON_ERROR", "FAILURE_REASON_ERROR", "ignoto"),
            ("una frase mai vista", "", "ignoto"),
            ("", "", "ignoto")):
        prova(f"motivo: LNbits «{testo[:28]}», LND «{lnd[15:]}»", atteso,
              motivo(un_ora, testo, lnd))
    prova("motivo: senza nessuna voce, la fattura SCADUTA parla da sola",
          "scaduta", motivo(BOLT11_VERA_7468))
    prova("...ma se LND dice perche', ha ragione LND", "nessuna_strada",
          motivo(BOLT11_VERA_7468, "", "FAILURE_REASON_NO_ROUTE"))
    motivo.__globals__["_ponte"]["stato"] = "giu"
    prova("motivo: nessuno sa niente e il ponte e' giu' adesso → ponte",
          "ponte", motivo(un_ora, "boh"))
    motivo.__globals__["_ponte"]["stato"] = "ok"
    prova("ogni motivo ha le sue parole, e nessuna e' vuota", True,
          all(S["PAROLE_MOTIVO"].get(m) for m in (
              "scaduta", "nessuna_strada", "saldo", "ponte", "tempo",
              "rifiutata", "bruciata", "ignoto")))
    ricorda, visti = S["_ricorda_motivo_lnd"], S["_lnd_motivi"]
    ricorda("h1", json.dumps({"result": {
        "status": "FAILED", "failure_reason": "FAILURE_REASON_NO_ROUTE"}}))
    ricorda("h2", json.dumps({
        "status": "FAILED", "failure_reason": "FAILURE_REASON_TIMEOUT"}))
    ricorda("h3", json.dumps({
        "status": "SUCCEEDED", "failure_reason": "FAILURE_REASON_NONE"}))
    for storta in ("non e' json", "[1, 2]", "null", ""):
        ricorda("h4", storta)
    prova("LND: il `failure_reason` si tiene, nelle due forme della riga",
          {"h1": "FAILURE_REASON_NO_ROUTE", "h2": "FAILURE_REASON_TIMEOUT"},
          dict(visti))
    prova("...e `_chiedi_lnd` lo mette da parte PRIMA di rispondere", True,
          "_ricorda_motivo_lnd(payment_hash, riga)" in
          codice(pezzo("_chiedi_lnd")))

    # --- 5. LE SCENE -------------------------------------------------
    def orecchie(m, chi=222):
        """Le notifiche si SENTONO (nel banco di ieri erano mute), e a
        bussare alle rotte e' il venditore, non il moderatore."""
        m.sentite = []

        async def _n(a_chi, testo):
            m.sentite.append((a_chi, testo))
        m.amb["notifica"] = _n
        m.amb["verifica_utente"] = lambda *a: {"id": chi}
        return m

    def ferma(m, t):
        """L'orologio del mondo, fermo a `t`: il limite del margine si
        guarda al secondo, e un banco che corre non lo sa fare."""
        class Fermo:
            def time(self):
                return t

            def __getattr__(self, nome):
                return getattr(time, nome)
        m.amb["time"] = Fermo()
        m.amb["vita_fattura"].__globals__["time"] = Fermo()

    def colonne(m, *nomi):
        return tuple(m.vero.execute(
            f"SELECT {', '.join(nomi)} FROM ordini WHERE id=1").fetchone())

    def incolla(m, bolt11):
        return gira(prova_a(m.amb["deposita_invoice"](
            1, {"invoice": bolt11}, "", "")))

    def H(bolt11):
        """L'hash che il nodo di cartone da' a una fattura: tronco a
        100, come quello vero sulla riga."""
        return ("hash-di-" + bolt11)[:100]

    quattro_giorni_fa = bolt11_finta(1000, 3600, adesso - 4 * GIORNO - 3600)
    il_giorno = S["giorno_scadenza"](quattro_giorni_fa)

    # 5a. L'ORDINE #152: incollata alla spedizione, scaduta al payout
    m = orecchie(mondo(invoice=quattro_giorni_fa, address=""))
    esito = gira(m.sblocca())
    prova("#152: a LNbits non si chiede di pagare NIENTE", [],
          m.nodo.partiti)
    prova("...e su LNbits non nasce nessuna riga `failed` da chiarire", {},
          m.nodo.lnbits)
    prova("...l'ordine va in «confirmed»: i sats spettano a lui, manca il "
          "modo", ("confirmed", "", ""), riga(m))
    prova("...la fattura morta si toglie, il giro a vuoto si conta, e "
          "l'eta' dell'ultimo tentativo VERO non si tocca", ("", 1, 0),
          colonne(m, "invoice_venditore", "payout_tentativi",
                  "payout_ultimo"))
    prova("...il diario dice perche'", True,
          "scaduta" in colonne(m, "payout_errore")[0])
    prova("...e nessun hash entra nella memoria dei tentativi", 0,
          m.vero.execute("SELECT COUNT(*) FROM payout_tentati").fetchone()[0])
    al_venditore = " ".join(t for chi, t in m.sentite if chi == 222)
    prova("#152: al venditore si dice CHE e' scaduta e QUANDO", True,
          f"è scaduta {il_giorno}" in al_venditore)
    prova("...cosa fare, con la cifra, e la cura che non scade mai", True,
          "fattura <b>nuova</b>" in al_venditore and "1.000" in al_venditore
          and "Lightning address" in al_venditore)
    prova("...e MAI PIU' che la rete non ha trovato una strada", False,
          "non ha trovato una strada" in al_venditore)
    prova("#152: ai moderatori «NON TENTATO», col giorno — non «FALLITO»",
          (True, False),
          (any("NON TENTATO" in x and il_giorno in x for x in m.avvisi),
           any("FALLITO" in x for x in m.avvisi)))
    prova("...e il journal ha la sua riga ⌛", True,
          any("⌛" in d and "scaduta" in d for d in m.detto))
    prova("...e chi ha chiamato lo sa (e' quel che legge il pannello 🧊)",
          "scaduta", esito.get("motivo"))
    # Pedro rincolla LA STESSA: si rifiuta alla porta, con le parole
    e = incolla(m, quattro_giorni_fa)
    prova("#152: la STESSA fattura rincollata si rifiuta alla porta",
          (400, True), (getattr(e, "status_code", None),
                        "già scaduta" in str(getattr(e, "detail", ""))))
    # ...e ne incolla una NUOVA: parte subito, una volta sola
    nuova = bolt11_finta(1000, 3600, adesso - 5)
    e = incolla(m, nuova)
    prova("#152: la fattura NUOVA si paga subito, una volta",
          ("released", [H(nuova)]),
          (e.get("stato") if isinstance(e, dict) else e, m.nodo.partiti))

    # 5a-bis. LA FATTURA SI INCOLLA SOLO ALL'INCASSO (21 set 2026).
    # Prima della conferma la porta e' chiusa, e lo dice con le parole
    # che servono: perche', cosa succedera', e la strada che non scade.
    # Si guarda anche cosa NON succede: LNbits non si scomoda (il no
    # arriva prima dell'importo) e la colonna resta com'era.
    buona = bolt11_finta(1000, 7 * GIORNO, adesso - 5)
    for prima in ("locked", "shipped", "delivered"):
        m = orecchie(mondo(invoice="", address="", stato=prima))
        chiesto = []

        async def _conta(bolt11, dec=None, cassaforte="", _c=chiesto):
            _c.append(bolt11)
            return 1000
        m.amb["importo_invoice"] = _conta
        e = incolla(m, buona)
        d = str(getattr(e, "detail", ""))
        prova(f"porta chiusa a «{prima}»: una fattura BUONA, da sette "
              "giorni, si rifiuta lo stesso", 400,
              getattr(e, "status_code", None))
        prova("...con le parole: solo all'incasso, ti avvisiamo noi, e "
              "l'address che non scade", True,
              "solo al momento dell'incasso" in d and "ti avvisiamo" in d
              and "Lightning address" in d and "non scade" in d)
        prova("...senza scomodare LNbits, senza scrivere la colonna, "
              "senza pagare", ([], ("", prima), []),
              (chiesto, colonne(m, "invoice_venditore", "stato"),
               m.nodo.partiti))
    # ...e a 'confirmed' la porta e' aperta: e' la scena del #152 qui
    # sopra (la NUOVA pagata subito). Qui il caso che mancava: chi
    # compra NON e' chi vende, e da 'confirmed' non incolla niente.
    m = orecchie(mondo(invoice="", address="", stato="confirmed"), chi=111)
    e = incolla(m, buona)
    prova("porta: a 'confirmed' chi COMPRA non incolla la fattura di chi "
          "vende", (400, []),
          (getattr(e, "status_code", None), m.nodo.partiti))
    # GLI ORDINI DI IERI: una fattura gia' in colonna, incollata alla
    # spedizione e ancora VIVA, si paga come ieri — il cantiere chiude
    # la porta, non butta via quel che c'e' dentro.
    di_ieri = bolt11_finta(1000, 7 * GIORNO, adesso - 2 * GIORNO)
    m = orecchie(mondo(invoice=di_ieri, address="", stato="shipped"))
    gira(m.sblocca())
    prova("ordini di ieri: la fattura gia' in colonna, viva, si paga "
          "come sempre", ("released", [H(di_ieri)]),
          (riga(m)[0], m.nodo.partiti))

    # 5b. scaduta, ma c'e' il Lightning address: ci pensiamo noi
    m = orecchie(mondo(invoice=quattro_giorni_fa, address="chi@wallet.tld"))
    gira(m.sblocca())
    prova("address: la scaduta non si tenta e la riga aspetta il giro",
          ([], ("confirmed", "da_riprovare", "")),
          (m.nodo.partiti, riga(m)))
    al_venditore = " ".join(t for chi, t in m.sentite if chi == 222)
    prova("...e al venditore si dice che ci pensiamo noi, dall'address",
          True, "è scaduta" in al_venditore
          and "Lightning address" in al_venditore
          and "non devi fare niente" in al_venditore)
    gira(m.sblocca())
    prova("...al giro dopo si conia dall'address e si paga, una volta",
          ("released", ["hash-di-lnbc-fattura-1"]),
          (riga(m)[0], m.nodo.partiti))

    # 5c. IL LIMITE DEL MARGINE, al secondo
    sul_filo = bolt11_finta(1000, 3600, adesso - 3600 + M)
    m = mondo(invoice=sul_filo, address="")
    ferma(m, adesso + 1)                 # le restano M-1 secondi
    gira(m.sblocca())
    prova(f"limite: a {M - 1} secondi dalla scadenza NON si tenta", [],
          m.nodo.partiti)
    m = mondo(invoice=sul_filo, address="")
    ferma(m, adesso)                     # le restano M secondi esatti
    gira(m.sblocca())
    prova(f"...a {M} secondi esatti si paga", [H(sul_filo)],
          m.nodo.partiti)

    # 5d. IMPORTO DIVERSO: e' un allarme, e vince sulla scadenza
    async def _storto(bolt11, dec=None, cassaforte=""):
        return 999
    m = orecchie(mondo(invoice=quattro_giorni_fa, address=""))
    m.amb["importo_invoice"] = _storto
    gira(m.sblocca())
    prova("importo: storto E scaduta → «rifiutato», non «scaduta»",
          ([], True, False),
          (m.nodo.partiti,
           any("Pagamento rifiutato" in x and "999" in x for x in m.avvisi),
           any("NON TENTATO" in x for x in m.avvisi)))
    m = orecchie(mondo(address="", stato="confirmed"))
    m.amb["importo_invoice"] = _storto
    e = incolla(m, nuova)
    prova("importo: alla porta l'importo sbagliato si rifiuta, e si dice "
          "quale", (400, True),
          (getattr(e, "status_code", None),
           "Importo sbagliato" in str(getattr(e, "detail", ""))
           and "999" in str(getattr(e, "detail", ""))))

    # 5e. IL 520 COL SUO PERCHE': il numero non e' il motivo
    for detail, spia_admin, spia_venditore, vietata in (
            ("Payment failed: invoice expired. Valid until 16 set",
             "<b>scaduta</b>", "è scaduta", "non ha trovato una strada"),
            ("Payment failed: no_route", "non ha trovato una strada",
             "non ha trovato una strada", "è scaduta"),
            ("Insufficient balance.", "NOSTRO saldo", "non per colpa tua",
             "non ha trovato una strada"),
            ("Unable to connect to LND", "ponte verso il nodo",
             "non per colpa tua", "non ha trovato una strada"),
            ("una frase mai vista", "non si è potuto leggere",
             "non è riuscito", "non ha trovato una strada")):
        m = orecchie(mondo(invoice=nuova, address=""))
        m.nodo.modi[nuova] = (520, detail)
        gira(m.sblocca())
        avviso = " ".join(m.avvisi)
        al_venditore = " ".join(t for chi, t in m.sentite if chi == 222)
        prova(f"520 «{detail[:24]}»: ai moderatori il PERCHE' in parole",
              True, "FALLITO" in avviso and "Perché:" in avviso
              and spia_admin in avviso)
        prova("...col testo grezzo di LNbits accanto, e nel diario", True,
              detail[:20] in avviso
              and detail[:20] in colonne(m, "payout_errore")[0])
        prova("...e al venditore la frase giusta, non quella di un altro "
              "guasto", (True, False),
              (spia_venditore in al_venditore, vietata in al_venditore))
        if "expired" in detail:
            prova("...senza un giorno: per il nostro orologio era ancora "
                  "viva, e una data nel futuro farebbe dubitare del resto",
                  True, "è scaduta</b>" in al_venditore
                  and "<b>scaduta</b>. LND" in avviso)

    # 5f. SCADUTA ≠ IN VOLO: la forma del #152 DOPO il fatto — l'hash ha
    # una riga `failed` su LNbits, LND non l'ha mai visto, la fattura
    # morta e' ancora in colonna — finita sul tavolo dei moderatori
    def congelata(eta_s):
        m = orecchie(mondo(invoice=quattro_giorni_fa, address=""))
        h = H(quattro_giorni_fa)
        m.nodo.lnbits[h] = "failed"
        m.vero.execute("INSERT INTO payout_tentati(tabella, riga_id, hash, "
                       "quando, esito) VALUES('ordini',1,?,?,'')",
                       (h, adesso - eta_s))
        m.vero.execute("UPDATE ordini SET payout_stato='incerto', "
                       "payout_hash=?, payout_verso='venditore', "
                       "payout_ultimo=?, payout_tentativi=1",
                       (h, adesso - eta_s))
        m.vero.commit()
        canarino(m)
        m.amb["verifica_utente"] = lambda *a: {"id": 999}
        return m, h
    m, h = congelata(4 * GIORNO)
    r = gira(prova_a(m.decidi("verifica")))
    prova("🧊 «Verifica e riprova» su una scaduta: NON ripaga la vecchia",
          [], m.nodo.partiti)
    prova("...toglie il fermo e chiede una fattura nuova",
          ("confirmed", "", h), riga(m))
    prova("...per la strada delle FONTI: e' un tentativo FALLITO di una "
          "fattura scaduta, non un «non tentato»", (True, False),
          (any("FALLITO" in x and "<b>scaduta</b>" in x for x in m.avvisi),
           any("NON TENTATO" in x for x in m.avvisi)))
    prova("...e al moderatore dice che era SCADUTA, non «in volo»", True,
          isinstance(r, dict) and "SCADUTA" in r.get("messaggio", "")
          and "niente in volo" in r.get("messaggio", ""))
    prova("...e al venditore pure", True,
          any("è scaduta" in t for chi, t in m.sentite if chi == 222))
    m, h = congelata(60)
    r = gira(prova_a(m.decidi("verifica")))
    prova("🧊 ...ma un tentativo di UN MINUTO fa resta «in volo»: i 15 "
          "minuti di ieri non li scavalca nessun calendario", (409, []),
          (getattr(r, "status_code", None), m.nodo.partiti))

    # 5g. LA PORTA: quando si incolla. A ordine SPEDITO non si incolla
    # piu' niente, nemmeno la fattura da 31 giorni che fino al 20 set si
    # salvava (la scena sta in 5a-bis, coi tre stati): qui resta la
    # porta APERTA, quella di 'confirmed', coi suoi due limiti.
    lunga = bolt11_finta(1000, 31 * GIORNO, adesso - 5)
    m = orecchie(mondo(address="", stato="shipped"))
    e = incolla(m, lunga)
    prova("porta: spedito, fattura da 31 giorni → NON si salva piu'",
          (400, "", "shipped", []),
          (getattr(e, "status_code", None),
           colonne(m, "invoice_venditore")[0], riga(m)[0], m.nodo.partiti))
    m = orecchie(mondo(address="", stato="confirmed"))
    e = incolla(m, bolt11_finta(1000, 3600, adesso - 3600 + 300))
    prova("porta: confermato, fattura che muore fra 5 minuti → rifiutata",
          (400, True, []),
          (getattr(e, "status_code", None),
           "scade fra" in str(getattr(e, "detail", "")), m.nodo.partiti))
    e = incolla(m, un_ora)
    prova("porta: confermato, fattura da un'ora → pagata all'istante",
          "released", e.get("stato") if isinstance(e, dict) else e)

    # 5h. SCADUTA MA GIA' PAGATA: la fattura e' morta DOPO che il suo
    # pagamento era partito (e arrivato). A dire com'e' finita sono le
    # fonti, non il calendario: l'affare si chiude, e non si chiede
    # nessuna fattura nuova a chi i sats li ha gia'.
    def gia_tentata(lnbits, lnd, eta_s=4 * GIORNO, address=""):
        m = orecchie(mondo(invoice=quattro_giorni_fa, address=address))
        h = H(quattro_giorni_fa)
        if lnbits:
            m.nodo.lnbits[h] = lnbits
        if lnd:
            m.nodo.lnd[h] = lnd
        m.vero.execute("INSERT INTO payout_tentati(tabella, riga_id, hash, "
                       "quando, esito) VALUES('ordini',1,?,?,'')",
                       (h, adesso - eta_s))
        m.vero.commit()
        canarino(m)
        return m
    m = gia_tentata("success", "SUCCEEDED")
    gira(m.sblocca())
    prova("scaduta ma GIA' USCITA: l'affare si chiude come pagato, senza "
          "un secondo pagamento", ("released", "uscito", []),
          (riga(m)[0], riga(m)[1], m.nodo.partiti))
    prova("...e a nessuno si chiede una fattura nuova", False,
          any("scaduta" in t for _, t in m.sentite))
    # 5i. gia' tentata, MAI PARTITA (le fonti non ne sanno niente, ed e'
    # passato il tempo), e adesso scaduta: si potrebbe riprovare — ma la
    # fattura e' morta. E' il secondo passaggio della cintura.
    m = gia_tentata("", "")
    gira(m.sblocca())
    prova("gia' tentata, mai partita, e adesso scaduta: NON si ritenta",
          ([], True), (m.nodo.partiti,
                       any("è scaduta" in t for _, t in m.sentite)))
    # 5j. LA FATTURA BRUCIATA: viva, ma gia' fallita una volta
    m = orecchie(mondo(invoice=nuova, address=""))
    m.nodo.lnbits[H(nuova)] = "failed"
    m.vero.execute("INSERT INTO payout_tentati(tabella, riga_id, hash, "
                   "quando, esito) VALUES('ordini',1,?,?,'')",
                   (H(nuova), adesso - GIORNO))
    m.vero.commit()
    canarino(m)
    gira(m.sblocca())
    prova("bruciata: ai moderatori «già stata tentata», e non si ripaga",
          (True, []), (any("già stata tentata" in x for x in m.avvisi),
                       m.nodo.partiti))
    m = mondo(address="")
    m.nodo.lnbits[H(nuova)] = "failed"
    tac = {}
    gira(m.amb["paga_venditore"](nuova, 1000, tac, cassaforte="nodo"))
    prova("...anche sulla strada vecchia, senza la riga", "bruciata",
          tac.get("motivo"))
    # 5k. COLPA NOSTRA, e c'e' l'address: ci riproviamo, senza accusare
    m = orecchie(mondo(invoice=nuova, address="chi@wallet.tld"))
    m.nodo.modi[nuova] = (520, "Insufficient balance.")
    gira(m.sblocca())
    al_venditore = " ".join(t for chi, t in m.sentite if chi == 222)
    prova("saldo nostro + address: «non per colpa tua», e ci riproviamo",
          ("da_riprovare", True, False),
          (riga(m)[1], "non per colpa tua" in al_venditore
           and "ci riproviamo noi" in al_venditore,
           "non ha trovato una strada" in al_venditore))

    # --- 6. LE SENTINELLE: la forma che non deve sparire -------------
    pv = codice(pezzo("paga_venditore"))
    ordine = [pv.index(x) for x in (
        "chiesto != atteso_sats", "scade_presto =", "_verita_riga(",
        "_prendi_la_mano(", "c.post(")]
    prova("la cintura della scadenza sta DOPO l'importo e PRIMA della "
          "verita', della mano e della POST", sorted(ordine), ordine)
    prova("...e ripassa una seconda volta prima della mano (gia' tentata, "
          "mai partita, e adesso scaduta)", True,
          pv.count("return await _non_si_tenta()") == 2
          and pv.rindex("return await _non_si_tenta()")
          < pv.index("_prendi_la_mano("))
    corpo = pv[pv.index("async def _non_si_tenta("):pv.index("if scade_presto:")]
    prova("...chi non tenta non tocca la rete e non lascia un nome sulla "
          "riga", (False, True),
          ("httpx" in corpo or "_stato_pagamento" in corpo,
           'taccuino.pop("hash", None)' in corpo))
    dep = codice(pezzo("deposita_invoice"))
    prova("alla porta la scadenza si guarda dopo l'importo e prima di "
          "salvare", True,
          dep.index("Importo sbagliato") < dep.index("rifiuto_scadenza(")
          < dep.index("UPDATE ordini SET"))
    prova("...anche sui rimborsi d'asta, dove si paga all'istante", True,
          "rifiuto_scadenza(bolt11)" in codice(pezzo(
              "deposita_invoice_rimborso")))
    # LA PORTA CHIUSA STA PRIMA DI TUTTO (21 set 2026): prima
    # dell'importo — cioe' prima di LNbits — e prima della scrittura
    prova("alla porta il «troppo presto» si dice PRIMA di chiedere "
          "l'importo a LNbits", True,
          # `find` e non `index`: una sentinella che ESPLODE si porta via
          # la sezione, e una mutazione morta cosi' non e' uccisa
          0 < dep.find("MSG_FATTURA_PRESTO") < dep.find("importo_invoice(")
          < dep.find("UPDATE ordini SET"))
    prova("...e non esiste piu' un ramo che salva e aspetta: da qui si "
          "paga, o si rimborsa", (False, True),
          ('"netto": atteso' in dep,
           "    return await _sblocca_sats(ordine_id)" in dep))
    sbl = codice(pezzo("_sblocca_sats"))
    prova("in `_sblocca_sats` le parole le sceglie il MOTIVO, nei due "
          "rami", (True, True),
          ("_msg_fattura_nuova(netto, taccuino)" in sbl,
           "_msg_ritentiamo(netto, taccuino)" in sbl))


def prove_fattura_solo_incasso():
    """LIGHTNING ADDRESS PREFERITO, FATTURA SOLO ALL'INCASSO (21 set
    2026, deciso con Alan) — il lato del CLIENT.

    Il server la sua meta' la prova in `prove_fatture_scadute` (la porta
    chiusa prima di 'confirmed'). Qui si prova quel che VEDE chi vende:
    prima della conferma il foglio dell'incasso ha UN campo, il
    Lightning address, con la ragione scritta («non scade mai, lo usiamo
    al momento del pagamento»); il campo della fattura compare quando
    tocca, a 'confirmed'. `payoutPanel` e' quello VERO, fatto girare in
    node: una prova sul testo del sorgente direbbe di si' anche a un
    ramo che non si raggiunge.

    GLI ORDINI DI IERI che una fattura in colonna ce l'hanno gia' si
    vedono dire la verita' su di lei — viva o scaduta, letta dalla
    bolt11 — senza un bottone per sostituirla: prima dell'incasso da
    qui non si incolla piu' niente."""
    print("\n[Lightning address preferito: la fattura si incolla solo "
          "all'incasso]")
    import shutil
    import subprocess
    import tempfile

    mini = open("miniapp.html", encoding="utf-8").read()
    pp = pezzo_js(mini, "function payoutPanel(o){", "\n}\n") + "\n}\n"
    ss = pezzo_js(mini, "async function saveSellerInvoice(btn){", "\n}\n")

    # --- 1. LA FORMA: quel che non deve tornare ----------------------
    senza_commenti = re.sub(r"/\*.*?\*/", "", pp, flags=re.S)
    prova("il foglio non ha piu' ne' «Salva invoice» ne' «Sostituisci»",
          [], [x for x in ("Salva invoice", "Sostituisci invoice",
                           "Invoice salvata in cassaforte",
                           "Incasso pronto") if x in senza_commenti])
    prova("...e nessun toast promette piu' un incasso «alla conferma» da "
          "una fattura salvata", False,
          "incasso automatico alla conferma" in
          re.sub(r"/\*.*?\*/", "", ss, flags=re.S))
    prova("il profilo dice perche' l'address: non scade, e si usa al "
          "momento del pagamento", True,
          "<b>non scade mai</b>, lo usiamo\n      al momento del pagamento"
          in pezzo_js(mini, "function renderLnAddress(){", "\n}\n")
          .replace("\r\n", "\n"))
    prova("«I tuoi dati» dice che nel Profilo non si salva nessuna fattura",
          True, "nel Profilo non se ne salva nessuna" in mini)
    prova("Info dice a chi vende le due strade, e quando si incolla", True,
          "<b>Se sei tu a vendere:</b>" in mini
          and "in quel momento incolli una fattura nell'ordine" in mini)

    # --- 2. IL FOGLIO VERO, in node ----------------------------------
    node = shutil.which("node")
    if not node:
        salta("il foglio dell'incasso prima e dopo la conferma",
              "node non c'e'")
        return
    adesso = int(time.time())
    viva = bolt11_finta(1000, 7 * 86400, adesso - 86400)
    morta = bolt11_finta(1000, 3600, adesso - 4 * 86400)
    js = ("const fmt = n => String(n);\n"
          "const esc = x => String(x);\n"
          "let myLnAddress = '';\n"
          "function nettoVenditore(o){ return o.listing.price; }\n"
          + pezzo_js(mini, "function importoBolt11(pr){", "\n}\n") + "\n}\n"
          + pezzo_js(mini, "function leggiBolt11(pr){", "\n}\n") + "\n}\n"
          + pp +
          "const o = (state, inv, gesto) => ({state, sellerInvoice: inv || '',"
          " listing: {price: 1000},"
          " pagamento: gesto ? {gesto_venditore: true} : null});\n"
          "const out = {};\n"
          "for (const st of ['locked', 'shipped', 'delivered'])\n"
          "  out[st] = payoutPanel(o(st));\n"
          "out.confirmed = payoutPanel(o('confirmed', '', true));\n"
          "out.viva = payoutPanel(o('shipped', " + json.dumps(viva) + "));\n"
          "out.morta = payoutPanel(o('shipped', " + json.dumps(morta) + "));\n"
          "out.cartone = payoutPanel(o('shipped', 'lnbc-fattura-1'));\n"
          "myLnAddress = 'io@wallet.com';\n"
          "out.conAddress = payoutPanel(o('shipped'));\n"
          "out.conAddressConfermato = payoutPanel(o('confirmed'));\n"
          "console.log(JSON.stringify(out));\n")
    with tempfile.NamedTemporaryFile("w", suffix=".js", delete=False,
                                     encoding="utf-8") as f:
        f.write(js)
    try:
        r = subprocess.run([node, f.name], capture_output=True,
                           encoding="utf-8", timeout=60)
        out = json.loads(r.stdout or "{}")
        if not out:
            print("      node:", (r.stderr or "")[-400:])
    except Exception as e:
        out = {}
        print(f"      node e' esploso: {e}")
    finally:
        os.unlink(f.name)

    for st in ("locked", "shipped", "delivered"):
        h = out.get(st, "")
        prova(f"«{st}»: il foglio ha il campo dell'address e NON quello "
              "della fattura", (True, False, False),
              ('id="lnAddrInput"' in h, 'id="sellerInvoice"' in h,
               "saveSellerInvoice" in h))
        prova("...dice perche' l'address, e cosa succede a chi non ce l'ha",
              True, "<b>non scade mai</b>, lo usiamo al momento del "
              "pagamento" in h and "<b>ti avvisiamo noi</b>" in h
              and "arriverebbe scaduta" in h)
    h = out.get("confirmed", "")
    prova("«confirmed»: tocca a lui, e il campo della fattura C'E', in "
          "evidenza", (True, True, True),
          ('id="sellerInvoice"' in h, "saveSellerInvoice(this)" in h,
           "pag-evidenza" in h))
    prova("...con l'address ancora consigliato, e la fattura «adesso»",
          True, 'id="lnAddrInput"' in h and "<b>non scade mai</b>" in h
          and "genera <b>adesso</b>" in h and "La paghiamo subito" in h)
    h = out.get("viva", "")
    prova("ordine di ieri, fattura VIVA in colonna: lo dice, e non offre "
          "di sostituirla", (True, False, False),
          ("avevi già salvato una fattura" in h, 'id="sellerInvoice"' in h,
           "è già scaduta" in h))
    h = out.get("morta", "")
    prova("ordine di ieri, fattura SCADUTA in colonna: lo dice adesso, "
          "non il giorno dei sats", (True, False),
          ("<b>è già scaduta</b>" in h and "ne incolli una nuova" in h,
           'id="sellerInvoice"' in h))
    prova("...e una fattura che non si legge non si da' per morta", True,
          "avevi già salvato una fattura" in out.get("cartone", "")
          and "è già scaduta" not in out.get("cartone", ""))
    h = out.get("conAddress", "")
    prova("chi ha gia' l'address non vede cambiare niente", True,
          "Incasso automatico attivo" in h and "io@wallet.com" in h
          and 'id="sellerInvoice"' not in h)
    prova("...e se a 'confirmed' i sats non sono partiti, la fattura "
          "resta la sua uscita", True,
          'id="sellerInvoice"' in out.get("conAddressConfermato", ""))


def prove_in_pagamento():
    """LO STADIO «💸 IN PAGAMENTO AL VENDITORE» (set 2026).

    Fra la conferma e 'released' c'e' un tempo che non vedeva nessuno, e
    in quel tempo un guasto NOSTRO sembrava colpa di chi compra o di chi
    vende. Qui si prova: il giudice unico (`stadio_pagamento`, puro), la
    linea del tempo, la conferma DEFINITIVA (tre rotte che rifiutano),
    gli avvisi senza doppioni, il ritentativo per cause nostre a 1, 5,
    15, 30 minuti e poi ogni ora SENZA TETTO — con la scena che il
    cantiere chiedeva per nome: il nodo giu' per un'ora, e poi il payout
    che parte da solo senza che nessuno abbia sentito niente.

    IL MONDO E' QUELLO DEI PAGAMENTI IN VOLO (`attrezzi=True`), con tre
    aggiunte: la tabella VERA dei passi (il suo DDL si esegue dal
    sorgente), le notifiche che si SENTONO, e i pezzi del cantiere
    rimontati DENTRO il mondo — quelli di `ambiente_in_pagamento` sono
    muti apposta, e qui sono proprio gli avvisi la cosa da contare."""
    print("\n[lo stadio «in pagamento»: il tempo fra la conferma e i sats "
          "arrivati]")
    import shutil
    import subprocess
    import tempfile
    a = prove_pagamenti_in_volo(attrezzi=True)
    mondo0, gira, riga = a["mondo"], a["gira"], a["riga"]
    prova_a, invecchia = a["prova_a"], a["invecchia"]
    P = ambiente_in_pagamento()
    adesso = int(time.time())
    src = _SORGENTE
    mini = open("miniapp.html", encoding="utf-8").read()

    def pezzo_async(nome):
        return "async " + pezzo(nome)

    def mondo(**k):
        chi = k.pop("chi", 111)
        m = mondo0(**k)
        i = src.index('"CREATE TABLE IF NOT EXISTS payout_passi("')
        j = src.index('DEFAULT 1)")', i) + len('DEFAULT 1)"')
        m.vero.execute(eval("(" + src[i:j] + ")"))
        m.vero.commit()
        m.sentite = []

        async def _n(a_chi, testo):
            m.sentite.append((a_chi, testo))
        m.amb["notifica"] = _n
        m.amb["verifica_utente"] = lambda *x: {"id": chi}
        m.amb.update({"TIMBRO_SOSPESI": "sospesi-prova",
                      "BACKOFF_PAYOUT": (300, 1800, 7200, 21600, 86400)})
        for nome, asincrona in (
                ("_quando_ritentare", 0), ("_avvisa_in_pagamento", 1),
                ("riprova_pagamenti_sospesi", 1), ("conferma_ricezione", 1),
                ("apri_disputa", 1), ("sollecita_acquirente", 1)):
            exec(("async " if asincrona else "") + pezzo(nome), m.amb)
        m.giro = lambda: m.amb["riprova_pagamenti_sospesi"]()
        return m

    def passi(m):
        return [(r[0], r[1], r[2]) for r in m.vero.execute(
            "SELECT passo, motivo, volte FROM payout_passi "
            "WHERE tabella='ordini' AND riga_id=1 ORDER BY id")]

    def stadio(m):
        # UNO STADIO CHE MANCA FA CADERE LA PROVA ROSSA, NON LA SEZIONE:
        # alla tortura, con la guardia rotta, qui tornava None e il banco
        # esplodeva — cioe' la mutazione moriva per la ragione sbagliata
        o = dict(m.vero.execute("SELECT * FROM ordini WHERE id=1").fetchone())
        return m.amb["_stadi_ordini"](m.vero, [o]).get(1) or {
            "passo": None, "motivo": None, "deciso_da": None, "nostro": None,
            "gesto_venditore": None, "lungo": None, "linea": []}

    def passa_il_tempo(m, secondi):
        """L'orologio non si ferma: si INVECCHIA quel che e' scritto,
        come fa `invecchia` coi tentativi. E' lo stesso tempo per tutti."""
        m.vero.execute("UPDATE payout_passi SET quando=quando-?, "
                       "ultimo=ultimo-?", (secondi, secondi))
        m.vero.commit()
        invecchia(m, secondi)

    async def tenta(coro):
        """Una rotta che doveva rifiutare e invece PROSEGUE va a sbattere
        nel mondo di cartone (colonne che non ha): la prova deve uscirne
        rossa, col suo «nessun 409», non esplodere."""
        try:
            return await coro
        except Exception as e:
            return e

    def detti(m, a_chi, spia):
        return sum(1 for c, t in m.sentite if c == a_chi and spia in t)

    # --- 0. I NUMERI, e il loro senso --------------------------------
    prova("il ritentativo per cause nostre: 1, 5, 15, 30 minuti, poi l'ora",
          (60, 300, 900, 1800, 3600), P["BACKOFF_NOSTRO"])
    qn = P["_quando_ritentare_nostro"]
    prova("...letto dal numero dei giri a vuoto di fila",
          [60, 300, 900, 1800, 3600],
          [qn(v, 1000) - 1000 for v in (1, 2, 3, 4, 5)])
    prova("...e SENZA TETTO: al cinquantesimo giro e' ancora un'ora", 3600,
          qn(50, 1000) - 1000)
    prova("«ci stiamo lavorando» scatta quando scatta il 🧊: un numero solo",
          True, "\nIN_PAGAMENTO_LUNGO_S = IN_VOLO_LIMITE_S\n" in src)
    prova("i guasti di casa sono tre: saldo, ponte, LNbits muta",
          ("saldo", "ponte", "lnbits_muto"), P["MOTIVI_NOSTRI"])

    # --- 1. IL GIUDICE, riga per riga --------------------------------
    # (un «non e' in pagamento» torna come stadio VUOTO: a guardia rotta
    # le prove qui sotto devono cadere rosse una per una, non far
    # esplodere la sezione al primo `s["passo"]` — l'ha chiesto la tortura)
    VUOTO = {"passo": None, "motivo": None, "deciso_da": None,
             "nostro": None, "gesto_venditore": None, "lungo": None,
             "prossimo": None, "via": None, "linea": [{"passo": None}]}

    def giudice(*a):
        return P["stadio_pagamento"](*a) or VUOTO

    def o_(**k):
        base = {"id": 1, "stato": "shipped", "payout_stato": "",
                "payout_verso": "", "disputata": 0, "sbloccato_auto_il": 0,
                "aggiornato": adesso - 10, "prezzo_sats": 1000,
                "protezione_sats": 0, "payout_tentativi": 0,
                "payout_ultimo": 0}
        base.update(k)
        return base

    def p_(passo, motivo="", eta=10, volte=1, via="lightning"):
        return {"passo": passo, "motivo": motivo, "via": via,
                "quando": adesso - eta, "ultimo": adesso - eta,
                "volte": volte}

    def passo_di(o, ps=()):
        return giudice(o, ps, (), adesso)["passo"]

    for nome, o, ps, atteso in (
            ("un ordine spedito e basta NON e' in pagamento", o_(), (), None),
            ("'confirmed' lo e' sempre", o_(stato="confirmed"), (),
             "serve_fattura"),
            ("spedito + in volo verso chi VENDE lo e'",
             o_(payout_stato="in_volo", payout_verso="venditore"), (),
             "in_volo"),
            ("...e 'incerto' e' «in verifica»",
             o_(payout_stato="incerto", payout_verso="venditore"), (),
             "in_verifica"),
            ("...e 'da_riprovare' e' «riparte da solo»",
             o_(payout_stato="da_riprovare", payout_verso="venditore"), (),
             "riparte"),
            ("un'uscita verso chi COMPRA non e' questo stadio",
             o_(stato="dispute", payout_stato="in_volo",
                payout_verso="compratore"), (), None),
            ("una disputa decisa a chi vende, col payout in volo, si'",
             o_(stato="dispute", payout_stato="in_volo",
                payout_verso="venditore", disputata=1), (), "in_volo"),
            ("un rimborso in corso no", o_(stato="refund"), (), None),
            ("'released' SENZA storia tace (gli affari di ieri)",
             o_(stato="released"), (), None),
            ("'released' con la sua storia dice «arrivato»",
             o_(stato="released"), (p_("deciso", "conferma"),
                                    p_("arrivato")), "arrivato")):
        prova("giudice: " + nome, atteso, passo_di(o, ps))
    s = giudice(o_(stato="confirmed"), (), (), adesso)
    prova("senza metodo il gesto e' di chi vende, e il motivo e' «metodo»",
          (True, "metodo", False),
          (s["gesto_venditore"], s["motivo"], s["lungo"]))
    s = giudice(o_(stato="confirmed"),
                (p_("deciso", "conferma"), p_("fallito", "scaduta"),
                 p_("serve_fattura", "scaduta")), (), adesso)
    prova("fattura scaduta: serve una fattura nuova, col motivo in parole",
          ("serve_fattura", "scaduta", True, False),
          (s["passo"], s["motivo"], s["gesto_venditore"], s["nostro"]))
    s = giudice(o_(payout_stato="da_riprovare", payout_verso="venditore"),
                (p_("deciso", "conferma", 400),
                 p_("guasto_nostro", "ponte", 100, volte=2)), (), adesso)
    prova("guasto nostro: riparte da solo, e' NOSTRO, nessun gesto",
          ("riparte", "ponte", True, False),
          (s["passo"], s["motivo"], s["nostro"], s["gesto_venditore"]))
    prova("...e dice quando si riprova: 5 minuti dopo il secondo giro",
          adesso - 100 + 300, s["prossimo"])
    s = giudice(o_(payout_stato="da_riprovare", payout_verso="venditore",
                   payout_tentativi=1, payout_ultimo=adesso - 50),
                (p_("deciso", "conferma", 60),
                 p_("fallito", "nessuna_strada", 50)), (), adesso)
    prova("una ROTTA che manca tiene la cadenza di sempre (5 minuti)",
          (adesso - 50 + 300, False), (s["prossimo"], s["nostro"]))
    L = P["IN_PAGAMENTO_LUNGO_S"]
    for nome, o, eta, atteso in (
            ("in volo da 29 minuti non e' ancora lungo",
             o_(payout_stato="in_volo", payout_verso="venditore"),
             L - 60, False),
            ("in volo da 31 minuti: «ci stiamo lavorando»",
             o_(payout_stato="in_volo", payout_verso="venditore"),
             L + 60, True),
            ("un 'incerto' e' lungo per definizione (il 🧊 e' gia' partito)",
             o_(payout_stato="incerto", payout_verso="venditore"), 5, True),
            ("chi vende che non ci da' un metodo NON e' «ci lavoriamo noi»",
             o_(stato="confirmed"), L * 10, False)):
        s = giudice(o, (p_("deciso", "conferma", eta),), (), adesso)
        prova("giudice: " + nome, atteso, s["lungo"])
    s = giudice(o_(payout_stato="in_volo", payout_verso="venditore"),
                (p_("deciso", "timer", 30),), (), adesso)
    prova("chi ha deciso si legge dal primo passo", "timer", s["deciso_da"])
    s = giudice(o_(stato="confirmed", disputata=1), (), (), adesso)
    prova("...e sugli ordini di ieri si ricava dalla riga", "disputa",
          s["deciso_da"])
    s = giudice(o_(payout_stato="in_volo", payout_verso="venditore"),
                (p_("deciso", "conferma", 30),), (), adesso)
    prova("la via di oggi e' Lightning", "lightning", s["via"])
    s = giudice(o_(payout_stato="in_volo", payout_verso="venditore"),
                (p_("deciso", "conferma", 900, via="onchain"),
                 p_("attesa_conferme", "", 600, via="onchain")), (), adesso)
    prova("lo spazio dell'on-chain: la via viaggia coi passi",
          ("onchain", "attesa_conferme"), (s["via"], s["linea"][-1]["passo"]))
    s = giudice(o_(payout_stato="in_volo", payout_verso="venditore"),
                (p_("deciso", "conferma", 20), p_("in_volo", "", 18)),
                (("h1", adesso - 20, ""),), adesso)
    prova("la linea mette «partito» dall'ora VERA della mano, fra deciso "
          "e in volo", ["deciso", "partito", "in_volo"],
          [x["passo"] for x in s["linea"]])
    prova("...e nella linea non viaggia nessun hash", False,
          "h1" in json.dumps(s))

    # --- 2. I PASSI UGUALI SI COMPRIMONO ------------------------------
    m = mondo()
    sp = m.amb["_segna_passo"]
    nuovi = [sp(m.vero, "ordini", 1, "guasto_nostro", "ponte"),
             sp(m.vero, "ordini", 1, "guasto_nostro", "ponte"),
             sp(m.vero, "ordini", 1, "guasto_nostro", "lnbits_muto")]
    prova("lo stesso guasto due volte e' UNA riga (e non e' una notizia)",
          ([True, False, True],
           [("guasto_nostro", "ponte", 2), ("guasto_nostro", "lnbits_muto", 1)]),
          (nuovi, passi(m)))
    senza = a["mondo"]()      # un database di ieri: la tabella non c'e'
    senza.vero.execute("DROP TABLE payout_passi")
    prova("senza la tabella il passo non ferma niente, e dice «nuovo»", True,
          senza.amb["_segna_passo"](senza.vero, "ordini", 1, "in_volo"))
    prova("...e `_segna_deciso` dice «primo giro»: i messaggi di sempre",
          True, senza.amb["_segna_deciso"](
              senza.vero, 1, senza.vero.execute(
                  "SELECT * FROM ordini WHERE id=1").fetchone(), False))

    # --- 3. IN VOLO: la conferma e' DEFINITIVA ------------------------
    m = mondo(stato="shipped")
    m.nodo.modi["lnbc-fattura-1"] = "hold"
    esito = gira(m.amb["conferma_ricezione"](1))
    prova("conferma con una hold invoice: il payout resta in volo",
          ("shipped", "in_volo"), riga(m)[:2])
    prova("...e chi compra sente UNA volta che ha finito", 1,
          detti(m, 111, "Hai confermato: i sats vanno al venditore, ci "
                        "pensa Barattolo"))
    prova("...e chi vende UNA volta che i sats sono in arrivo", 1,
          detti(m, 222, "I tuoi 1.000 sats sono in arrivo"))
    prova("...detto col PERCHE' vero: ha confermato l'acquirente", 1,
          detti(m, 222, "L'acquirente ha confermato la ricezione"))
    s = stadio(m)
    prova("lo stadio: in volo, deciso da una conferma, nessun gesto",
          ("in_volo", "conferma", False, False),
          (s["passo"], s["deciso_da"], s["gesto_venditore"], s["lungo"]))
    prova("la linea del tempo: deciso, partito, in volo",
          ["deciso", "partito", "in_volo"], [x["passo"] for x in s["linea"]])
    for rotta, spia in (("conferma_ricezione", "Hai già confermato"),
                        ("apri_disputa", "la conferma è definitiva")):
        e = gira(tenta(m.amb[rotta](1)))
        prova(f"{rotta}: a conferma data e' un 409",
              409, getattr(e, "status_code", None))
        prova("...con le parole di chi ha confermato", True,
              spia in str(getattr(e, "detail", "")))
    prova("...e l'ordine NON e' andato in disputa", "shipped", riga(m)[0])
    m.amb["verifica_utente"] = lambda *x: {"id": 222}
    e = gira(tenta(m.amb["sollecita_acquirente"](1)))
    prova("chi vende non puo' sollecitare una conferma gia' data", 409,
          getattr(e, "status_code", None))
    prova("nessuno di questi rifiuti ha detto niente a nessuno", 2,
          len(m.sentite))
    prova("...e nessun secondo pagamento e' partito", 1, len(m.nodo.partiti))
    # ...il ladro salda: la ronda chiude, e chi vende sente «Arrivati ✓»
    m.nodo.lnd["hash-di-lnbc-fattura-1"] = "SUCCEEDED"
    m.nodo.lnbits["hash-di-lnbc-fattura-1"] = "success"
    gira(m.ronda())
    prova("saldata, la ronda chiude da sola", ("released", "uscito"),
          riga(m)[:2])
    prova("chi vende sente «Arrivati ✓»", 1, detti(m, 222, "Arrivati ✓"))
    prova("...e NON si sente ridire «L'acquirente ha confermato»", 1,
          detti(m, 222, "ha confermato la ricezione"))
    prova("...ne' una seconda volta «sono in arrivo»", 1,
          detti(m, 222, "sats sono in arrivo.</b>"))
    prova("chi compra sente che l'affare e' concluso", 1,
          detti(m, 111, "Affare concluso"))
    s = stadio(m)
    prova("lo stadio resta come storia: arrivato ✓",
          ("arrivato", ["deciso", "partito", "in_volo", "arrivato"]),
          (s["passo"], [x["passo"] for x in s["linea"]]))

    # --- 4. SUBITO RIUSCITO: nessun avviso in piu' ---------------------
    m = mondo(stato="shipped")
    gira(m.amb["conferma_ricezione"](1))
    prova("payout riuscito nello stesso giro: released", "released",
          riga(m)[0])
    prova("...e gli avvisi sono i DUE di sempre, non quattro", 2,
          len(m.sentite))
    prova("...«Sats sbloccati!» a chi vende, come ieri", 1,
          detti(m, 222, "Sats sbloccati!"))
    prova("...e nessun «sono in arrivo» tre secondi prima", 0,
          detti(m, 222, "sats sono in arrivo.</b>")
          + detti(m, 111, "Hai confermato"))
    prova("la storia c'e' lo stesso: deciso, partito, arrivato",
          ["deciso", "partito", "arrivato"],
          [x["passo"] for x in stadio(m)["linea"]])

    # --- 5. IL NODO GIU' PER UN'ORA ------------------------------------
    # La scena che il cantiere chiedeva per nome. Fattura INCOLLATA e
    # buona, nessun address: il caso peggiore, perche' se la bruciassimo
    # toccherebbe a chi vende darcene un'altra per un guasto nostro.
    m = mondo(invoice="lnbc-incollata", address="", stato="shipped")
    m.amb["_ponte"]["stato"] = "giu"
    try:
        gira(m.amb["conferma_ricezione"](1))
        prova("ponte giu': la conferma passa, il payout NON si tenta",
              ("shipped", "da_riprovare", []),
              (riga(m)[0], riga(m)[1], m.nodo.partiti))
        prova("...la fattura incollata resta al suo posto, NON bruciata",
              ("lnbc-incollata", {}),
              (m.vero.execute("SELECT invoice_venditore FROM ordini")
               .fetchone()[0], m.nodo.lnbits))
        prova("...e sulla riga non resta il nome di un pagamento mai nato",
              "", riga(m)[2])
        prova("il passo dice di chi e' il guasto",
              [("deciso", "conferma", 1), ("guasto_nostro", "ponte", 1)],
              passi(m))
        prova("chi compra e chi vende sentono SOLO che ci pensiamo noi", 2,
              len(m.sentite))
        prova("...e a nessuno dei due si nomina il guasto", False,
              any("ponte" in t.lower() or "nodo" in t.lower()
                  or "problema" in t.lower() for _, t in m.sentite))
        s = stadio(m)
        prova("lo stadio: riparte da solo, guasto nostro, nessun gesto",
              ("riparte", True, False),
              (s["passo"], s["nostro"], s["gesto_venditore"]))
        # l'ORA: un battito al minuto, col ponte sempre giu'
        bussate = []
        for minuto in range(1, 61):
            passa_il_tempo(m, 60)
            prima = len([d for d in m.detto if "ponte verso LND" in d])
            gira(m.giro())
            if len([d for d in m.detto if "ponte verso LND" in d]) > prima:
                bussate.append(minuto)
        prova("in un'ora si ribussa a 1, 6, 21 e 51 minuti — e basta",
              [1, 6, 21, 51], bussate)
        prova("...LNbits non ha visto NIENTE, la fattura e' ancora buona",
              ([], {}), (m.nodo.partiti, m.nodo.lnbits))
        prova("...e a compratore e venditore non e' arrivata una parola in "
              "piu'", 2, len(m.sentite))
        prova("...un'ora di guasto e' UNA riga nella linea del tempo",
              [("deciso", "conferma", 1), ("guasto_nostro", "ponte", 5)],
              passi(m))
        prova("...chi modera ha il suo avviso di sempre, UNA volta", 1,
              sum(1 for x in m.avvisi if "Pagamenti in uscita fermi" in x))
        s = stadio(m)
        prova("dopo un'ora le due parti leggono «ci stiamo lavorando»", True,
              s["lungo"])
        e = gira(tenta(m.amb["apri_disputa"](1)))
        prova("...e la conferma resta definitiva anche a payout sospeso",
              (409, "shipped"), (getattr(e, "status_code", None), riga(m)[0]))
        # IL NODO TORNA
        m.amb["_ponte"]["stato"] = "ok"
        gira(m.giro())
        prova("appena tornato NON si bussa: si aspetta il proprio turno",
              [], m.nodo.partiti)
        passa_il_tempo(m, 3600)
        gira(m.giro())
        prova("al suo turno il payout PARTE DA SOLO e arriva",
              ("released", "uscito", ["hash-di-lnbc-incollata"]),
              (riga(m)[0], riga(m)[1], m.nodo.partiti))
        prova("...con la STESSA fattura incollata un'ora prima", True,
              m.nodo.lnbits.get("hash-di-lnbc-incollata") == "success")
        prova("chi vende sente «Arrivati ✓»: e' il suo secondo messaggio",
              (1, 2), (detti(m, 222, "Arrivati ✓"),
                       sum(1 for c, _ in m.sentite if c == 222)))
        prova("la linea racconta l'ora per intero",
              ["deciso", "guasto_nostro", "partito", "arrivato"],
              [x["passo"] for x in stadio(m)["linea"]])
    finally:
        m.amb["_ponte"]["stato"] = "ok"
    # dove il guardiano non gira `_ponte` vale «attesa», e non morde
    m = mondo(invoice="lnbc-incollata", address="", stato="shipped")
    m.amb["_ponte"]["stato"] = "attesa"
    try:
        gira(m.amb["conferma_ricezione"](1))
        prova("senza guardiano («attesa») si paga come ieri", "released",
              riga(m)[0])
    finally:
        m.amb["_ponte"]["stato"] = "ok"
    # ...e la cassaforte del SaaS col ponte non c'entra
    m = mondo(invoice="lnbc-incollata", address="", stato="shipped")
    m.amb["_ponte"]["stato"] = "giu"
    m.amb["_chiavi_cassaforte"] = lambda nome="": type(
        "Cf", (), {"nome": "saas", "LNBITS_URL": "http://finto",
                   "LNBITS_INVOICE_KEY": "k", "LNBITS_ADMIN_KEY": "K"})()
    try:
        gira(m.amb["conferma_ricezione"](1))
        prova("il ponte giu' non ferma un ordine del SaaS", "released",
              riga(m)[0])
    finally:
        m.amb["_ponte"]["stato"] = "ok"

    # --- 6. LNBITS MUTA, poi torna -------------------------------------
    m = mondo(invoice="lnbc-incollata", address="", stato="delivered")
    m.nodo.muto = True
    gira(m.amb["conferma_ricezione"](1))
    prova("LNbits muta: sospeso, guasto nostro, fattura al suo posto",
          ("da_riprovare", [("deciso", "conferma", 1),
                            ("guasto_nostro", "lnbits_muto", 1)], []),
          (riga(m)[1], passi(m), m.nodo.partiti))
    gira(m.giro())
    prova("prima del suo minuto il giro non la tocca", 1, passi(m)[-1][2])
    m.nodo.muto = False
    passa_il_tempo(m, 61)
    gira(m.giro())
    prova("un minuto dopo, a LNbits tornata, parte da solo", "released",
          riga(m)[0])

    # --- 7. GUASTO NOSTRO DOPO LA POST, con l'address ------------------
    # LNbits risponde 520 «non raggiungo LND»: la fattura coniata e'
    # bruciata, ma dall'address se ne conia un'altra — senza tetto.
    # E QUI IL RITENTATIVO HA DUE TEMPI, non uno: il nostro (1, 5, 15...)
    # e quello della VERITA' — un tentativo fallito dopo la chiamata che
    # paga non si ripete finche' LND non dice che non e' mai partito (un
    # quarto d'ora: e' il cantiere dei pagamenti in volo, e non si tocca).
    m = mondo(stato="shipped")
    a["canarino"](m)
    m.vero.execute("UPDATE ordini SET payout_tentativi=9")
    m.vero.commit()
    # (la fattura 2 e la 4 si coniano e NON si pagano: il giro le conia
    # prima di sapere che il tentativo di prima non e' ancora chiaro)
    m.nodo.modi["lnbc-fattura-1"] = (520, "Unable to connect to LND")
    m.nodo.modi["lnbc-fattura-3"] = (520, "Unable to connect to LND")
    gira(m.amb["conferma_ricezione"](1))
    prova("guasto nostro oltre il tetto dei cinque: si ritenta LO STESSO",
          ("confirmed", "da_riprovare"), riga(m)[:2])
    prova("...chi vende sente che non e' colpa sua, UNA volta", 1,
          detti(m, 222, "non per colpa tua"))
    gira(m.giro())
    prova("...e prima del minuto non si ribussa", 1, len(m.nodo.partiti))
    passa_il_tempo(m, 61)
    gira(m.giro())
    prova("al suo minuto si riprova, ma PRIMA si chiede a LND: il tentativo "
          "di prima non e' ancora chiaro, e si aspetta in volo",
          ("in_volo", 1), (riga(m)[1], len(m.nodo.partiti)))
    prova("...in volo e NON congelato, anche oltre il tetto: nessun 🧊", 0,
          sum(1 for x in m.avvisi if "verificare a mano" in x))
    passa_il_tempo(m, 900)
    gira(m.ronda())
    prova("dopo il quarto d'ora LND dice «mai partito»: si ritenta davvero",
          ("da_riprovare", 2), (riga(m)[1], len(m.nodo.partiti)))
    prova("...ma chi vende NON lo risente: non e' una notizia", 1,
          detti(m, 222, "non per colpa tua"))
    prova("...e i guasti di fila sono DUE, anche con un «in volo» in mezzo",
          (2, [("guasto_nostro", "ponte", 1), ("in_volo", "", 1),
               ("guasto_nostro", "ponte", 1)]),
          (P["_conta_guasti"]([dict(zip(("passo", "motivo", "volte",
                                         "quando", "ultimo"), r))
                               for r in m.vero.execute(
              "SELECT passo, motivo, volte, quando, ultimo FROM "
              "payout_passi ORDER BY id")])[0], passi(m)[1:]))
    passa_il_tempo(m, 61)
    gira(m.giro())
    prova("...quindi al giro dopo non basta piu' un minuto: ne servono 5",
          "da_riprovare", riga(m)[1])
    passa_il_tempo(m, 240)
    gira(m.giro())
    passa_il_tempo(m, 900)
    gira(m.ronda())
    prova("al terzo tentativo il nodo c'e': arrivato, con la terza fattura",
          ("released", 3), (riga(m)[0], len(m.nodo.partiti)))
    prova("...e chi vende ha sentito in tutto DUE cose: il motivo, e "
          "«Arrivati ✓»", (1, 1, 2),
          (detti(m, 222, "non per colpa tua"), detti(m, 222, "Arrivati ✓"),
           sum(1 for c, _ in m.sentite if c == 222)))
    # ...mentre una ROTTA che manca il tetto ce l'ha ancora
    m = mondo(stato="shipped")
    m.vero.execute("UPDATE ordini SET payout_tentativi=9")
    m.vero.commit()
    m.nodo.modi["lnbc-fattura-1"] = (520, "no_route")
    gira(m.amb["conferma_ricezione"](1))
    prova("una rotta che manca, oltre il tetto, chiede un gesto a chi vende",
          ("confirmed", "", "serve_fattura", "nessuna_strada"),
          (riga(m)[0], riga(m)[1], stadio(m)["passo"], stadio(m)["motivo"]))

    # --- 8. LA FATTURA SCADUTA: l'unico gesto, e solo a chi vende ------
    scaduta = bolt11_finta(1000, 3600, adesso - 4 * 86400)
    m = mondo(invoice=scaduta, address="", stato="shipped")
    gira(m.amb["conferma_ricezione"](1))
    s = stadio(m)
    prova("fattura scaduta: serve una fattura nuova, e lo dice il motivo",
          ("confirmed", "serve_fattura", "scaduta", True),
          (riga(m)[0], s["passo"], s["motivo"], s["gesto_venditore"]))
    prova("...a chi compra si dice solo che ha finito", (1, 1),
          (detti(m, 111, "Hai confermato"),
           sum(1 for c, _ in m.sentite if c == 111)))
    prova("...a chi vende il SUO messaggio, e non anche «in arrivo»", (1, 0),
          (detti(m, 222, "è scaduta"),
           detti(m, 222, "sats sono in arrivo.</b>")))
    prova("la linea: deciso, non arrivato (scaduta), serve un gesto",
          [("deciso", "conferma", 1), ("fallito", "scaduta", 1),
           ("serve_fattura", "scaduta", 1)], passi(m))
    # nessun metodo: non e' un fallimento, e' un'attesa di chi vende
