def prove_pagamento_incerto():
    """Il timeout di paga_venditore (ago 2026, audit). LNbits puo'
    aver pagato e non essere riuscito a dircelo: prima l'eccezione
    risaliva, il database non registrava NIENTE e il tentativo dopo
    coniava una fattura nuova dal Lightning address — cioe' pagava
    una seconda volta per davvero. Qui si prova il non-fatto: nessuna
    seconda uscita, nessuno stato riscritto."""
    print("\n[il pagamento incerto]")
    import asyncio
    import sqlite3

    def gira(coro):
        return asyncio.new_event_loop().run_until_complete(coro)

    def pezzo_async(nome):
        return "async " + pezzo(nome)

    async def _niente(*a, **k):
        return None

    ESITI = {"PAGATO": "pagato", "NON_PAGATO": "non_pagato",
             "INCERTO": "incerto", "NON_CHIESTO": "non_chiesto", "OCCUPATO": "occupato",
             "LnbitsMuto": LnbitsMuto, "_sospendi_pagamento": lambda *a: None}

    # --- 1. I quattro esiti di paga_venditore -----------------------
    def paga(codice=200, muto=False, chiesto=1000, muto_decode=False):
        uscite, avvisi = [], []

        async def _importo(_b, _dec=None):
            return chiesto

        async def _decodifica(_b, _cf=""):
            # `muto_decode` e' il caso di ago 2026: non e' il NODO a
            # tacere mentre paga, e' la DOMANDA che lo precede — «quanto
            # chiede questa fattura?» — a non aver ricevuto risposta. Da
            # li' nessun sat si e' mosso. Dal set 2026 quella domanda la
            # fa `decodifica_invoice`, che serve anche l'hash.
            if muto_decode:
                raise LnbitsMuto("decode: LNbits ha risposto 520")
            return {"payment_hash": "abc123"}

        async def _mai_visto(_h, _cf=""):
            return ""

        async def _avvisa(t):
            avvisi.append(t)

        amb = {**ambiente_scadenza(),
               "httpx": _finto_lnbits(uscite, codice, muto,
                                      corpo={"status": "success"}),
               "importo_invoice": _importo, "notifica_admin": _avvisa,
               "decodifica_invoice": _decodifica,
               "_stato_pagamento": _mai_visto,
               "_esito_lnbits": reale("_esito_lnbits"),
               "asyncio": __import__("asyncio"),
               "ATTESE_ESITO": 4, "SECONDI_FRA_ATTESE": 0,
               "print": lambda *a, **k: None,
               # chi estrae una funzione ne eredita le dipendenze
               "_fmt_sats": reale("_fmt_sats"),
               "LNBITS_URL": "http://x", "LNBITS_ADMIN_KEY": "k",
               "_chiavi_cassaforte": _cassaforte_finta(), **ESITI}
        exec(pezzo_async("_avvisa_payout_fallito"), amb)
        exec(pezzo_async("paga_venditore"), amb)
        return (gira(amb["paga_venditore"]("lnbc1", 1000, cassaforte="saas")),
                len(uscite), len(avvisi))

    prova("nodo che risponde ok: PAGATO", ("pagato", 1, 0), paga())
    # ...e dal set 2026 un no lo sanno anche i moderatori: prima un
    # payout che falliva non lo sapeva NESSUNO di noi — l'unico avviso
    # parlava di importi storti, cioe' di wallet rotti e di tentativi
    # di prelievo, mai di sats che non arrivano a chi li aspetta.
    prova("nodo che risponde no: NON_PAGATO, e i moderatori lo sanno",
          ("non_pagato", 1, 1), paga(codice=500))
    prova("nodo che TACE: INCERTO, non un fallimento", ("incerto", 1, 0),
          paga(muto=True))
    prova("importo storto: NON_PAGATO e zero uscite", ("non_pagato", 0, 1),
          paga(chiesto=999))

    # --- 1-bis. Dove nasce la distinzione: decodifica_invoice --------
    # SOLO 400 e 422 parlano della FATTURA. Tutto il resto parla del
    # canale, e prima finiva nello stesso `None` — da li' il ramo del
    # rifiuto cancellava la invoice di un venditore per un 520 nostro.
    def decodifica(codice=200, esplode=False):
        uscite = []

        class Rotto:
            def __init__(self, **kw):
                pass

            async def __aenter__(self):
                raise ConnectionError("nodo irraggiungibile")

            async def __aexit__(self, *a):
                return False

        amb = {"httpx": (__import__("types").SimpleNamespace(
                   AsyncClient=Rotto) if esplode
                   else _finto_lnbits(uscite, codice)),
               "LNBITS_URL": "http://x", "LNBITS_INVOICE_KEY": "k",
               "_chiavi_cassaforte": _cassaforte_finta(),
               "LnbitsMuto": LnbitsMuto}
        exec(pezzo_async("decodifica_invoice"), amb)
        try:
            return gira(amb["decodifica_invoice"]("lnbc1"))
        except LnbitsMuto:
            return "muto"

    prova("decode: 400 vuol dire che la FATTURA non si legge",
          None, decodifica(codice=400))
    prova("decode: 422 idem", None, decodifica(codice=422))
    prova("decode: 520 e' il CANALE, non la fattura",
          "muto", decodifica(codice=520))
    prova("decode: 502 idem", "muto", decodifica(codice=502))
    # la chiave rifiutata: imperfezione dichiarata, diventa «non lo so»
    prova("decode: 401 non accusa la fattura", "muto", decodifica(codice=401))
    prova("decode: rete caduta e' il canale", "muto", decodifica(esplode=True))
    prova("decode: 200 risponde come sempre", {}, decodifica())
    # IL QUARTO ESITO (ago 2026). Le due cose che si guardano sono
    # quelle che NON succedono: nessuna POST verso la chiave che paga —
    # cioe' il pagamento non e' partito — e NESSUN avviso ai moderatori,
    # perche' un guasto nostro non e' un tentativo di prelievo.
    prova("decode muto: NON_CHIESTO, zero uscite, zero avvisi",
          ("non_chiesto", 0, 0), paga(muto_decode=True))

    # --- 2. _sblocca_sats: il congelamento --------------------------
    # Un ordine vero in un database vero (in memoria), e tutto il
    # resto di cartone: quello che si guarda e' la riga dopo.
    def mondo(payout_stato="", esiti=("incerto",), muta=False,
              invoice="", risolvibile=False, ritentabile=False,
              address="io@wallet.tld", tentativi=0):
        vero = sqlite3.connect(":memory:")
        vero.row_factory = sqlite3.Row
        vero.execute(
            "CREATE TABLE ordini(id INTEGER PRIMARY KEY, annuncio_id INT, "
            "compratore_id INT, venditore_id INT, prezzo_sats INT, "
            "protezione_sats INT, quantita INT, stato TEXT, disputata INT, "
            "invoice_venditore TEXT, aggiornato INT, cambio_eur REAL, "
            "payout_stato TEXT, payout_hash TEXT, payout_verso TEXT, "
            "sbloccato_auto_il INT DEFAULT 0, cassaforte TEXT DEFAULT 'saas', "
            "payout_tentativi INT DEFAULT 0, payout_ultimo INT DEFAULT 0, "
            "payout_errore TEXT DEFAULT '')")
        vero.execute(
            "INSERT INTO ordini VALUES(1,7,111,222,1000,0,1,'delivered',0,"
            f"'{invoice}',0,0,'{payout_stato}','','',0,'saas',{tentativi},0,'')")
        vero.execute("CREATE TABLE utenti(tg_id INT, ln_address TEXT, "
                     "vendite_ok INT, acquisti_ok INT)")
        vero.execute("INSERT INTO utenti VALUES(222,?,0,0)", (address,))
        vero.commit()

        class Con:
            """close() non chiude davvero: il :memory: deve
            sopravvivere fra una chiamata e l'altra."""
            def execute(self, *a):
                return vero.execute(*a)

            def commit(self):
                vero.commit()

            def close(self):
                pass

        tentativi, coniate, detto = [], [], []
        resto = list(esiti)

        async def _dice(chi, testo, *a, **k):
            detto.append((chi, testo))

        async def _paga(bolt11, atteso, diario=None, cassaforte="",
                        riga=()):
            tentativi.append((bolt11, atteso))
            # il taccuino di set 2026: chi chiama lo pre-riempie con
            # l'etichetta e lo ritrova pieno. Qui si risponde come il
            # vero, cioe' scrivendoci dentro quel che si e' saputo.
            if diario is not None and resto[:1] != ["non_chiesto"]:
                diario["hash"] = "abc123"
                # dal cantiere B: con un hash in mano l'incerto si
                # risolve da solo, e il finto deve dirlo come il vero
                diario["risolvibile"] = risolvibile
                # ...e se una fattura NUOVA avrebbe senso: e' la leva
                # che accende il ritentativo col backoff
                diario["ritentabile"] = ritentabile
            return resto.pop(0) if resto else "non_pagato"

        async def _address(addr, importo):
            # OGNI chiamata conia una fattura NUOVA: e' esattamente il
            # motivo per cui un ritentativo pagherebbe due volte
            if muta:
                # il nostro nodo non risponde alla rilettura: la
                # fattura del wallet e' stata coniata e SCARTATA
                raise LnbitsMuto("decode: LNbits ha risposto 520")
            coniate.append(addr)
            return f"lnbc-nuova-{len(coniate)}"

        amb = {**ambiente_scadenza(),
               "db": Con, "time": __import__("time"),
               "_lucchetti_ordine": __import__("collections").defaultdict(
                   asyncio.Lock),
               "netto_venditore": lambda p: p,
               "_fmt_sats": reale("_fmt_sats"),
               "invoice_da_ln_address": _address, "paga_venditore": _paga,
               "_righe_ordine": lambda con, o: [],
               "_titolo_ordine": lambda righe: "una cosa",
               "cambio_btc_eur": _niente, "notifica": _dice,
               "premia_distintivi": _niente, "polso_ordini_admin": _niente,
               "notifica_admin": _niente, "_payment_hash": _niente,
               # Gli XP dell'affare concluso (ago 2026): qui non si
               # misurano, ma _sblocca_sats li chiama — e senza questi
               # due la prova ESPLODE invece di fallire, che e' la
               # trappola scritta in docs/ sulle funzioni estratte.
               "premia_xp": _niente, "xp_ordine": lambda *a: 0,
               # Il gancio della reputazione Nostr (set 2026): stessa
               # trappola, terzo giro — _sblocca_sats lo chiama DOPO
               # il giro degli XP, vedi prove_reputazione_nostr.
               "premia_reputazione_nostr": _niente,
               # ...e il titolo delle notifiche passa da html.escape
               # (ago 2026, la famiglia di B6): stessa trappola, secondo
               # giro — chi estrae una funzione ne eredita le dipendenze.
               "html": __import__("html"),
               # le due leve del cantiere B: senza i nomi il ramo del
               # volo non si valuta nemmeno, e la prova ESPLODE invece
               # di fallire — la trappola delle funzioni estratte
               "MAX_TENTATIVI_PAYOUT": 3, "IN_VOLO_LIMITE_S": 1800,
               "print": lambda *a, **k: None, **ESITI}
        exec(pezzo_async("_congela_pagamento"), amb)
        # il diario VERO, come i due timbri qui sotto: quel che si
        # guarda e' proprio quali colonne muove — e quali no
        exec(pezzo("_timbra_pagamento"), amb)
        # il timbro VERO, non la lambda di ESITI: quel che si guarda e'
        # proprio quel che scrive — e quel che NON scrive
        exec(pezzo("_sospendi_pagamento"), amb)
        # e il terzo, quello del volo: stessa ragione dei due sopra
        exec(pezzo("_in_volo"), amb)
        # la frase del ritentativo gira DAVVERO: uno stub direbbe di si'
        # a prescindere, e qui il punto e' proprio CHE COSA dice
        exec(pezzo("_msg_ritentiamo"), amb)
        exec(pezzo_async("_sblocca_sats"), amb)
        return amb["_sblocca_sats"], vero, tentativi, coniate, detto

    def riga(vero):
        r = vero.execute("SELECT * FROM ordini WHERE id=1").fetchone()
        return (r["stato"], r["payout_stato"], r["payout_verso"])

    # il nodo tace e il pagamento non ha un nome: si congela come
    # sempre — e' la strada che resta quando non c'e' niente da chiedere
    sblocca, vero, tentativi, coniate, _d = mondo(esiti=("incerto",))
    gira(sblocca(1))
    prova("incerto: lo stato dell'ordine NON si riscrive",
          ("delivered", "incerto", "venditore"), riga(vero))
    prova("incerto: un tentativo solo, e si ferma li'", 1, len(tentativi))
    # ...e ora tutte le strade normali ci riprovano: non deve uscire
    # nemmeno una fattura nuova
    gira(sblocca(1))
    gira(sblocca(1))
    prova("incerto: nessun secondo pagamento, mai", 1, len(tentativi))
    prova("incerto: nessuna fattura nuova coniata dall'address", 1,
          len(coniate))
    vero.close()

    # ...ma se quel pagamento un NOME ce l'ha, nessuno sveglia
    # nessuno: la riga va IN VOLO e il giro la scioglie da solo.
    sblocca, vero, tentativi, coniate, _d = mondo(esiti=("incerto",),
                                              risolvibile=True)
    esito = gira(sblocca(1))
    prova("incerto con un nome: la riga vola, non si congela",
          ("delivered", "in_volo", "venditore"), riga(vero))
    prova("...e chi ha chiamato lo sa", True, bool(esito.get("in_volo")))
    # e da 'in_volo' non parte un secondo pagamento, come dal gelo
    gira(sblocca(1))
    gira(sblocca(1))
    prova("in volo: nessun secondo pagamento, mai", 1, len(tentativi))
    prova("in volo: nessuna fattura nuova coniata", 1, len(coniate))
    vero.close()

    # il nodo risponde di no: il ramo di sempre, invariato
    sblocca, vero, tentativi, _, _d = mondo(esiti=("non_pagato",))
    gira(sblocca(1))
    prova("fallimento vero: si va in 'confirmed' come sempre",
          ("confirmed", "", ""), riga(vero))
    vero.close()

    # il moderatore ha guardato su LNbits: era uscito
    sblocca, vero, tentativi, coniate, _d = mondo(payout_stato="uscito")
    gira(sblocca(1))
    prova("«è uscito»: si chiude l'ordine SENZA pagare di nuovo",
          ("released", "uscito", ""), riga(vero))
    prova("«è uscito»: zero tentativi e zero fatture coniate",
          (0, 0), (len(tentativi), len(coniate)))
    vero.close()

    # regressione: il giorno buono resta il giorno buono
    sblocca, vero, tentativi, _, _d = mondo(esiti=("pagato",))
    gira(sblocca(1))
    # 'uscito' dal set 2026: prima il vuoto voleva dire sia «mai
    # provato» sia «riuscito», cioe' non voleva dire niente — ed e'
    # esattamente il buco per cui il 14 settembre non si e' potuto
    # sapere da qui se un payout fosse davvero uscito.
    prova("pagamento riuscito: 'released', e il payout si timbra",
          ("released", "uscito", ""), riga(vero))
    prova("...e il diario porta l'hash di quel pagamento", "abc123",
          vero.execute("SELECT payout_hash FROM ordini "
                       "WHERE id=1").fetchone()[0])
    vero.close()

    # --- 2-bis. NON_CHIESTO: quel che NON si tocca ------------------
    # E' il cuore del cantiere di ago 2026, e si guarda una riga sola:
    # la invoice che il venditore aveva incollato deve essere ANCORA
    # LI'. Prima veniva cancellata, e il venditore riceveva pure la
    # notizia che il suo wallet non aveva risposto come doveva.
    # (a) la strada dell'invoice INCOLLATA A MANO: `paga_venditore` ha
    #     chiesto il decode, non ha avuto risposta, e torna NON_CHIESTO
    sblocca, vero, tentativi, coniate, _d = mondo(esiti=("non_chiesto",),
                                              invoice="lnbc-del-venditore")
    prima = dict(vero.execute("SELECT * FROM ordini WHERE id=1").fetchone())
    gira(sblocca(1))
    dopo = dict(vero.execute("SELECT * FROM ordini WHERE id=1").fetchone())
    prova("non chiesto: la invoice del venditore NON si cancella",
          "lnbc-del-venditore", dopo["invoice_venditore"])
    prova("non chiesto: la riga si timbra e lo stato resta com'era",
          ("delivered", "da_riprovare", "venditore"), riga(vero))
    # `aggiornato` e' l'ANCORA dei promemoria e della coda dei fermi:
    # toccarla farebbe ripartire da capo l'attesa di qualcuno
    prova("non chiesto: `aggiornato` non si muove",
          prima["aggiornato"], dopo["aggiornato"])
    # e nient'altro della riga si muove: solo le due colonne del timbro
    prova("non chiesto: nient'altro cambia nella riga",
          ["payout_stato", "payout_verso"],
          sorted(k for k in prima if prima[k] != dopo[k]))
    vero.close()

    # (a-bis) e se a chiudere era stato un TIMER, il ramo mite deve
    #     lasciarne traccia: e' quel che il giro rilegge per sapere
    #     con che parole notificare, e senza l'ordine ripreso direbbe
    #     al venditore «l'acquirente ha confermato la ricezione»
    sblocca, vero, _, _, _d = mondo(esiti=("non_chiesto",),
                                invoice="lnbc-del-venditore")
    gira(sblocca(1, automatico=True))
    prova("non chiesto: il timbro del timer resta scritto", True,
          vero.execute("SELECT sbloccato_auto_il FROM ordini "
                       "WHERE id=1").fetchone()[0] > 0)
    vero.close()

    # (b) la strada del LIGHTNING ADDRESS, che e' quella che gira da
    #     sola senza che nessuno guardi: qui a tacere e' la rilettura
    #     della fattura appena coniata dal wallet del venditore, e
    #     l'eccezione deve arrivare fin qui invece di travestirsi da
    #     «nessun metodo di pagamento»
    sblocca, vero, tentativi, coniate, _d = mondo(muta=True)
    gira(sblocca(1))
    prova("non chiesto (address): si timbra, non si va in 'confirmed'",
          ("delivered", "da_riprovare", "venditore"), riga(vero))
    prova("non chiesto (address): nessun pagamento tentato",
          0, len(tentativi))
    vero.close()

    # e il giro dopo, col nodo tornato, paga davvero
    sblocca, vero, tentativi, _, _d = mondo(esiti=("pagato",),
                                        invoice="lnbc-del-venditore")
    vero.execute("UPDATE ordini SET payout_stato='da_riprovare', "
                 "payout_verso='venditore' WHERE id=1")
    gira(sblocca(1))
    prova("da riprovare: il timbro non blocca il ritentativo",
          "released", riga(vero)[0])
    prova("da riprovare: si riusa la invoice di prima, non se ne conia",
          [("lnbc-del-venditore", 1000)], tentativi)
    vero.close()

    # --- 2-ter. LE PAROLE AL VENDITORE (cantiere B2) ----------------
    # Quella che se ne va diceva «il tuo wallet non ha risposto come
    # doveva»: su un fallimento di ROTTA il wallet non era mai stato
    # RAGGIUNTO, e la colpa cadeva addosso a chi aspettava i soldi.
    # ⚠️ SENZA LA PROSA: la docstring della frase nuova CITA quella
    # vecchia per dire perche' se n'e' andata, e una sentinella che
    # cercasse nel file intero diventerebbe rossa per colpa della
    # spiegazione — la trappola gia' pagata tre volte in due giorni.
    _sbl2 = codice(_senza_prosa(pezzo("_sblocca_sats")))
    prova("sentinella: la frase che accusava il wallet non c'e' piu'",
          True, "il tuo wallet non ha risposto" not in _sbl2)

    def parole(**kw):
        sblocca2, vero2, _, _, detto = mondo(esiti=("non_pagato",), **kw)
        esito = gira(sblocca2(1))
        r2 = vero2.execute("SELECT payout_stato FROM ordini "
                           "WHERE id=1").fetchone()
        vero2.close()
        return (" ".join(t for chi, t in detto if chi == 222),
                r2[0], bool(esito.get("ritenta")))

    testo, timbro, ritenta = parole(ritentabile=True)
    prova("fallito col Lightning address: la riga si timbra",
          ("da_riprovare", True), (timbro, ritenta))
    prova("...e al venditore si dice che ci pensiamo NOI", True,
          "ci riproviamo noi" in testo)
    prova("...che i sats sono suoi e dove stanno", True,
          "Sono tuoi" in testo and "deposito di garanzia" in testo)
    # LA RIGA PIU' IMPORTANTE DELLE PAROLE: mentre una macchina sta
    # gia' agendo, un invito ad agire produce due fatture e nessuna
    # certezza — e al venditore fa credere che tocchi a lui.
    prova("...e non gli si chiede di fare niente", False,
          "incolla una invoice" in testo)

    testo, timbro, ritenta = parole(ritentabile=True, tentativi=5)
    prova("esauriti i tentativi: niente timbro, e adesso si chiede a lui",
          ("", False), (timbro, ritenta))
    prova("...con le parole della resa", True,
          "Non siamo riusciti a consegnarti i sats" in testo
          and "incolla una invoice" in testo)

    testo, timbro, _ = parole(ritentabile=True, address="",
                              invoice="lnbc-bruciata")
    prova("senza address non si ritenta da soli", "", timbro)
    # dirgli «riprova» senza dirgli «con una NUOVA» lo manderebbe a
    # incollare la stessa, che LNbits non ripaghera' mai
    prova("...e gli si dice che quella fattura e' bruciata", True,
          "non si può più usare" in testo and "<b>nuova</b>" in testo)

    testo, timbro, _ = parole()
    prova("non ritentabile: nessun timbro", "", timbro)
    prova("...e NON si dichiara un fallimento che non si e' visto",
          True, "non sono ancora partiti" in testo
          and "fallito" not in testo)

    # e il giro giornaliero non chiama «fermo» quel che sta lavorando:
    # il suo avviso dice «non e' partito niente», che su una riga
    # rinviata sarebbe falso due volte
    prova("sentinella: i rinviati non contano fra i fermi", True,
          "rimasti = len(righe) - ripresi - rinviati"
          in codice(pezzo("riprova_pagamenti_sospesi")))

    # --- 3. SENTINELLE ----------------------------------------------
    # Il tri-stato sparisce in un riordino: basta che qualcuno rimetta
    # un `if await paga_venditore(...)` e «incerto» torna a leggersi
    # come successo, senza che nessuna prova funzionale si rompa.
    prova("sentinella: paga_venditore non si legge come booleano", [],
          re.findall(r"(?:and|not|if) await paga_venditore\(", _SORGENTE))
    # QUATTRO dall'ago 2026: la quarta e' `_rimborsa_sblocco`, il
    # rimborso del primo incasso nostro. Il conto cresce A MANO,
    # come il censimento delle leve-lista, ed e' il verso giusto:
    # una strada d'uscita NUOVA che non guardasse l'INCERTO
    # leggerebbe «non lo sappiamo» come «e' andata bene», e i sats
    # uscirebbero due volte. Se questo numero CALA, qualcuno ha
    # tolto una guardia.
    prova("sentinella: tutt'e quattro le uscite guardano l'INCERTO",
          4, _SORGENTE.count("esito == INCERTO"))
    # dal set 2026 la guardia ferma DUE timbri: 'incerto' (decide una
    # persona) e 'in_volo' (decide il giro, chiedendo per hash). Da
    # nessuno dei due parte un pagamento, ed e' la proprieta' che il
    # conto a mano difende — se CALA, qualcuno ha tolto una guardia.
    prova("sentinella: tutt'e quattro si fermano se sono congelate", 4,
          _SORGENTE.count('payout_stato"] in ("incerto", "in_volo")'))
    prova("sentinella: il congelamento scrive CHI aspettava i sats",
          True, "payout_verso=?" in pezzo("_congela_pagamento"))
    # e la coda admin non deve indovinare la strada dallo stato
    prova("sentinella: la coda admin legge payout_verso, non lo stato",
          True, 'verso = r["payout_verso"]' in pezzo("decidi_pagamento")
          and "_riprendi_uscita(tabella, riga_id, verso)"
          in pezzo("decidi_pagamento")
          and 'verso == "compratore"' in pezzo("_riprendi_uscita"))

    # --- 4. SENTINELLE DEL QUARTO ESITO (ago 2026) ------------------
    # LA PIU' PERICOLOSA DI TUTTO IL CANTIERE: NON_CHIESTO e' sicuro da
    # ritentare SOLO perche' nasce prima che il nodo venga toccato. Se
    # un domani quel ramo scivolasse dopo la chiamata che paga, un
    # ritentativo automatico coprirebbe un pagamento davvero in volo e
    # i sats uscirebbero due volte — cioe' esattamente il disastro che
    # l'INCERTO esiste per impedire, reintrodotto dalla sua cura.
    pv4 = codice(pezzo("paga_venditore"))
    prova("sentinella: il quarto esito nasce PRIMA della chiave che paga",
          True, ("except LnbitsMuto" in pv4
                 and pv4.index("except LnbitsMuto")
                 < pv4.index("LNBITS_ADMIN_KEY")))
    # gemelle del conto a mano dell'INCERTO, stessa ragione
    prova("sentinella: tutt'e quattro le uscite guardano il NON_CHIESTO",
          4, _SORGENTE.count("esito == NON_CHIESTO"))
    prova("sentinella: tutt'e quattro sanno prenderlo dall'eccezione",
          4, _SORGENTE.count("esito = NON_CHIESTO"))
    # IL TIMBRO E' MITE: se un giorno tocca `aggiornato` fa ripartire da
    # capo l'attesa dei promemoria e della coda dei fermi, e se avvisa
    # qualcuno diventa il rumore che il quarto esito esiste per togliere
    # ⚠️ SENZA LA PROSA: la docstring di quel timbro NOMINA apposta
    # `aggiornato` per dire che non lo tocca, e una sentinella che
    # cerca la parola diventerebbe rossa per colpa della spiegazione.
    sp = codice(_senza_prosa(pezzo("_sospendi_pagamento")))
    prova("sentinella: il timbro non tocca l'ancora dei promemoria",
          True, "aggiornato" not in sp)
    prova("sentinella: il timbro non avvisa nessuno",
          True, "notifica" not in sp)
    prova("sentinella: il timbro non chiede il payment_hash",
          True, "_payment_hash" not in sp)
    # L'AZZERAMENTO VIVE NEL GIRO, e CONDIZIONATO: senza la clausola
    # cancellerebbe il timbro di un moderatore ('incerto') o quello di
    # un pagamento gia' verificato ('uscito').
    rip = codice(pezzo("riprova_pagamenti_sospesi"))
    prova("sentinella: il giro azzera il timbro, e solo il suo",
          True, "AND payout_stato='da_riprovare'" in rip)
    # ...e si ferma alla prima riga che tace ancora, o busserebbe ai
    # wallet di venti venditori per niente a ogni battito
    prova("sentinella: il giro si ferma al primo silenzio",
          True, 'if esito.get("non_chiesto"):' in rip and "break" in rip)
    # `automatico` non si perde, o l'ordine chiuso da un timer e ripreso
    # dal giro direbbe «l'acquirente ha confermato la ricezione»
    # `automatico` si rilegge in `_riprendi_uscita`, che dal cantiere B
    # e' la strada comune ai DUE giri (i sospesi e quelli in volo): una
    # seconda copia di quella scelta e' una copia che un giorno manda i
    # sats alla persona sbagliata.
    prova("sentinella: la ripresa rilegge se era un timer", True,
          "automatico=bool(" in codice(pezzo("_riprendi_uscita")))
    prova("sentinella: la scelta della strada vive in un posto solo",
          True, "_paga_rimborso(riga_id)" not in rip
          and "_riprendi_uscita(tab, riga_id, verso)" in rip)
    # e il ramo mite di _sblocca_sats quel timbro lo SCRIVE, o non ci
    # sarebbe niente da rileggere. ⚠️ Si guarda la SCRITTURA e non la
    # parola: l'ha detto la tortura, un `_ = ("UPDATE ordini SET
    # sbloccato_auto_il=` lasciava verde la prima stesura.
    prova("sentinella: il ramo mite timbra anche il timer",
          True, 'con.execute("UPDATE ordini SET sbloccato_auto_il='
          in codice(pezzo("_sblocca_sats")).split("esito == NON_CHIESTO")[1]
          .split("if esito == PAGATO")[0])
    # `_payment_hash` la ingoia APPOSTA: e' l'unico punto del file dove
    # e' la risposta giusta, perche' li' il congelamento vale piu'
    # dell'hash — e senza questa riga al prossimo riordino qualcuno
    # «aggiusta» quell'except e il congelamento salta proprio quando i
    # sats possono essere usciti davvero.
    prova("sentinella: _payment_hash resta fail-open sul canale muto",
          True, "except Exception" in codice(pezzo("_payment_hash")))
    # e il ramo del Lightning address deve RILANCIARE, o la cura
    # coprirebbe l'invoice a mano e lascerebbe scoperto l'incasso
    # automatico, che e' la strada che gira senza che nessuno guardi.
    # ⚠️ NON basta che la parola ci sia — l'ha detto la tortura: un
    # `except LnbitsMuto: return None` la lascerebbe verde. Si guarda il
    # GESTO, e sotto si fa GIRARE la funzione.
    _lna = codice(_senza_prosa(pezzo("invoice_da_ln_address")))
    prova("sentinella: l'address rilancia invece di ingoiare",
          True, "except LnbitsMuto:" in _lna
          and "raise" in _lna.split("except LnbitsMuto:")[1]
          .split("except Exception")[0])

    def address(muto_decode):
        """La funzione VERA, col wallet del beneficiario di cartone:
        quel che si guarda e' se l'eccezione ESCE o viene ingoiata."""
        async def _importo(_b):
            if muto_decode:
                raise LnbitsMuto("decode: LNbits ha risposto 520")
            return 100

        amb = {"httpx": _finto_lnurl(
                   {"tag": "payRequest", "minSendable": 1,
                    "maxSendable": 10**9, "callback": "http://w/cb"},
                   "lnbc1-coniata"),
               "importo_invoice": _importo,
               "print": lambda *a, **k: None, "LnbitsMuto": LnbitsMuto}
        exec(pezzo_async("invoice_da_ln_address"), amb)
        try:
            return gira(amb["invoice_da_ln_address"]("io@wallet.tld", 100))
        except LnbitsMuto:
            return "muto"

    prova("address: col nodo vivo la fattura si rilegge e passa",
          "lnbc1-coniata", address(False))
    prova("address: col nodo muto l'eccezione ESCE, non diventa None",
          "muto", address(True))

    # --- 5. I QUATTRO RAMI DEL CLIENT -------------------------------
    # Chi ha appena premuto un bottone merita una risposta vera; chi non
    # ha premuto niente non merita un allarme — per questo dal ramo mite
    # non parte NESSUNA notifica e ci sono invece questi quattro toast.
    cl = open("miniapp.html", encoding="utf-8").read()
    prova("client: i quattro gesti sanno leggere il quarto esito",
          4, cl.count("d.non_chiesto"))
    # IL PEGGIORE ERA IL PRIMO: `confirmReceived` scriveva 'confirmed'
    # in locale su tutto cio' che non era 'released', quindi chi compra
    # vedeva «confermato» su un ordine rimasto dov'era, non riprovava, e
    # il promemoria automatico che gli resta gli sembrava sbagliato.
    _cr = cl[cl.index("async function confirmReceived"):]
    _cr = _cr[:_cr.index("\nasync function")]
    prova("client: chi conferma non si vede riscrivere lo stato a mano",
          True, "d.non_chiesto" in _cr and "d.stato || currentOrder.state" in _cr)


def prove_disputa_incagliata():
    """Una disputa non si chiude da sola (ago 2026, audit). Quando lo
    sblocco non riusciva a pagare, l'ordine passava a 'confirmed' —
    che e' giusto — ma la coda di risolvi_disputa guardava solo gli
    stati di disputa, e da li' il moderatore non poteva piu' decidere
    NIENTE: in particolare non poteva piu' rimborsare il compratore, e
    i sats restavano fermi senza rimedio."""
    print("\n[la disputa incagliata]")
    import sqlite3

    con = sqlite3.connect(":memory:")
    con.row_factory = sqlite3.Row
    con.execute("CREATE TABLE ordini(id INTEGER PRIMARY KEY, stato TEXT, "
                "disputata INT, sbloccato_auto_il INT DEFAULT 0)")
    con.executemany("INSERT INTO ordini VALUES(?,?,?,?)", [
        (1, "dispute", 1, 0),        # la coda di sempre
        (2, "return_shipped", 1, 0), # idem
        (3, "confirmed", 1, 0),      # incagliato: sblocco fallito
        (4, "refund", 1, 0),         # incagliato: rimborso fallito
        (5, "confirmed", 0, 0),      # un ordine normale: NON e' una disputa
        (6, "released", 1, 0),       # chiuso davvero: mai piu' in coda
        (7, "refunded", 1, 0),       # idem
        # LA PORTA DEL TIMER (ago 2026): nessuno ha disputato, ha
        # deciso una macchina — e i sats sono ancora in cassaforte
        (8, "confirmed", 0, 1712),
        # il timbro su un affare gia' pagato e' inerte: li' i sats
        # sono usciti e non c'e' piu' niente da decidere
        (9, "released", 0, 1712)])
    con.commit()

    # la WHERE vera, estratta dal sorgente invece che riscritta a mano
    i = _SORGENTE.index('o = con.execute("SELECT * FROM ordini WHERE id=? AND (')
    where = _SORGENTE[i:_SORGENTE.index('(ordine_id,)', i)]
    where = where[where.index('"SELECT'):]
    sql = "".join(re.findall(r'"([^"]*)"', where))
    visti = [r["id"] for r in con.execute(
        sql.replace("id=?", "id=id") + " ORDER BY id", ())]
    prova("la coda vede le dispute aperte, le due incagliate e "
          "l'affare chiuso da un timer", [1, 2, 3, 4, 8], visti)
    # LA META' CHE TIENE FERMA LA DECISIONE: chi ha confermato di
    # persona resta chiuso, e il timbro su un 'released' non riapre
    # niente — la porta esiste solo finche' i sats sono nostri.
    prova("un 'confirmed' normale non e' una disputa", True, 5 not in visti)
    prova("e un affare pagato non torna in coda per il timbro", True,
          9 not in visti)
    prova("un affare gia' chiuso non torna in coda", True,
          6 not in visti and 7 not in visti)
    con.close()

    # --- SENTINELLE -------------------------------------------------
    rd = pezzo("risolvi_disputa")
    # riaprire e' cio' che permette di cambiare strada senza allentare
    # le guardie: _sblocca_sats non parte da 'refund', e deve restare
    # cosi' — se un domani qualcuno togliesse la riapertura, il
    # ripensamento tornerebbe a essere un no-op silenzioso
    prova("il caso incagliato si RIAPRE prima di ridecidere", True,
          "stato='dispute'" in rd and 'stato in ("confirmed", "refund")' in rd)
    prova("_sblocca_sats continua a non partire da 'refund'", True,
          '"refund"' in pezzo("_sblocca_sats").split("bolt11")[0])
    # l'esito si valida PRIMA di riaprire, o un esito storto lascerebbe
    # il caso riaperto per niente
    prova("l'esito si valida prima di toccare l'ordine", True,
          rd.index('esito not in ("venditore"') < rd.index("stato='dispute'"))
    # e chi perde una disputa lo viene a sapere, una volta sola
    prova("chi perde lo sblocco viene avvisato", True,
          'o["disputata"] and primo_giro' in pezzo("_sblocca_sats"))
    prova("chi perde il rimborso viene avvisato", True,
          'o["disputata"] and primo_giro' in pezzo("_rimborsa_compratore"))
    prova("l'avviso non si ripete a ogni ritentativo", 2,
          _SORGENTE.count("primo_giro = o[\"stato\"] !="))


def prove_idor_verifica():
    """L'ordine e' MIO (ago 2026, audit). verifica-pagamento era
    l'unica rotta /api/orders/{id}/… senza guardia di proprieta': gli
    id sono progressivi, quindi chiamandoli in fila si leggeva lo
    stato di ogni ordine del mercatino — e si poteva innescare in
    anticipo il flusso di un altro. Qui si prova che un estraneo non
    arriva nemmeno a chiedere a LNbits."""
    print("\n[l'ordine è mio]")
    import asyncio
    import sqlite3

    class _H(Exception):
        def __init__(self, code, detail=""):
            self.code, self.detail = code, detail

    vero = sqlite3.connect(":memory:")
    vero.row_factory = sqlite3.Row
    vero.execute("CREATE TABLE ordini(id INTEGER PRIMARY KEY, "
                 "compratore_id INT, stato TEXT, payment_hash TEXT, "
                 "cassaforte TEXT DEFAULT 'saas')")
    vero.executemany("INSERT INTO ordini(id, compratore_id, stato, "
                     "payment_hash) VALUES(?,?,?,?)", [
        (1, 111, "creato", "hash1"),      # del compratore 111
        (2, 333, "creato", "hash2"),      # di un altro
        (3, 333, "shipped", "hash3")])    # di un altro, gia' avanti
    vero.commit()

    class Con:
        def execute(self, *a):
            return vero.execute(*a)

        def close(self):
            pass

    chiesto = []      # ogni riga = una domanda a LNbits

    async def _pagata(h, _cf=""):
        chiesto.append(h)
        return False

    async def _incassa(oid):
        return {"stato": "locked"}

    def guarda(ordine_id, chi):
        # Header/Cookie servono perche' i default della firma si
        # valutano quando la funzione si definisce, non quando si chiama
        amb = {"db": Con, "HTTPException": _H, "invoice_pagata": _pagata,
               "_incassa_ordine": _incassa,
               "Header": lambda d="": d, "Cookie": lambda d="": d,
               "verifica_utente": lambda h, s: {"id": chi}}
        exec("async " + pezzo("verifica_pagamento"), amb)
        try:
            return asyncio.new_event_loop().run_until_complete(
                amb["verifica_pagamento"](ordine_id))
        except _H as e:
            return f"{e.code} {e.detail}"

    prova("il compratore vero passa", {"stato": "in_attesa"},
          guarda(1, 111))
    prova("un estraneo sull'ordine altrui: 400",
          "400 Operazione non permessa", guarda(2, 333 + 1))
    prova("...e non chiede NIENTE a LNbits per conto suo", 1, len(chiesto))
    # l'oracolo: prima si distingueva «non esiste» da «esiste, ed e'
    # in questo stato». Ora le due risposte sono la stessa.
    prova("ordine inesistente e ordine altrui rispondono uguale",
          True, guarda(999, 111) == guarda(3, 111))
    prova("il venditore non passa da qui: e' il compratore che paga",
          "400 Operazione non permessa", guarda(3, 111))
    vero.close()

    # SENTINELLA: l'utente si legge e si USA. Buttarlo via era
    # esattamente il difetto, ed e' una riga che si riperde in un
    # riordino senza rompere nessuna prova funzionale.
    vp = pezzo("verifica_pagamento")
    prova("sentinella: l'utente non si butta via", True,
          "user = verifica_utente(" in vp and "compratore_id=?" in vp)


def prove_contenuti_cifrati():
    """La cifratura a riposo dei codici (ago 2026, audit). La chiave
    si derivava con uno SHA-256 nudo: contro una passphrase debole
    costa un hash a tentativo. Ora c'e' scrypt sotto il prefisso
    'f2', e i due formati convivono per sempre — un database nato
    con la ricetta vecchia deve restare leggibile."""
    print("\n[i contenuti cifrati]")
    try:
        from cryptography.fernet import Fernet
        from cryptography.hazmat.primitives.kdf.scrypt import Scrypt
    except ImportError:
        salta("la cifratura dei contenuti digitali",
              "cryptography non e' installata")
        return
    import base64
    import hashlib

    def mondo(chiave):
        amb = {"CHIAVE_CONTENUTI_DIGITALI": chiave, "Fernet": Fernet,
               "Scrypt": Scrypt, "base64": base64, "hashlib": hashlib}
        i = _SORGENTE.index("_SALE_CONTENUTI = ")
        exec(_SORGENTE[i:_SORGENTE.index("\n\n\n", i)], amb)
        exec(pezzo("_chiave_fernet"), amb)
        exec(pezzo("_cifra_contenuto"), amb)
        exec(pezzo("_decifra_contenuto"), amb)
        return amb

    a = mondo("una-chiave-segreta")
    blob = a["_cifra_contenuto"]("BUONO-1234")
    prova("si cifra con la ricetta nuova", True, blob.startswith("f2:"))
    prova("il codice non si legge nel blob", False, "BUONO-1234" in blob)
    prova("e si rilegge", "BUONO-1234", a["_decifra_contenuto"](blob))

    # il formato VECCHIO deve restare leggibile per sempre: un database
    # scritto ieri non puo' diventare illeggibile con un aggiornamento
    vecchio = "f:" + Fernet(base64.urlsafe_b64encode(
        hashlib.sha256(b"una-chiave-segreta").digest())).encrypt(
            b"CODICE-VECCHIO").decode()
    prova("il formato di ieri si rilegge ancora", "CODICE-VECCHIO",
          a["_decifra_contenuto"](vecchio))
    prova("e il 'plain:' di prima ancora", "in chiaro",
          a["_decifra_contenuto"]("plain:in chiaro"))

    # una chiave diversa non deve dare un'eccezione al chiamante, ma
    # una riga onesta (il venditore il codice ce l'ha comunque)
    altra = mondo("un'altra-chiave")
    prova("chiave sbagliata: una riga onesta, mai un'eccezione", True,
          altra["_decifra_contenuto"](blob).startswith("(contenuto cifrato"))

    # senza chiave si scrive in chiaro, ed e' dichiarato — ma dev'essere
    # DETTO all'avvio, che era la parte che mancava
    spenta = mondo("")
    prova("senza chiave si scrive in chiaro col suo prefisso", True,
          spenta["_cifra_contenuto"]("X").startswith("plain:"))
    prova("il fail-open non e' piu' muto: l'avvio lo dice", True,
          "if not CHIAVE_CONTENUTI_DIGITALI:" in _SORGENTE
          and "IN CHIARO" in _SORGENTE)
    # e le due ricette non devono dare la stessa chiave, o scrypt
    # sarebbe li' per niente
    prova("scrypt e sha256 danno chiavi diverse", True,
          a["_chiave_fernet"]("f2") != a["_chiave_fernet"]("f"))


def _exif_con_gps(orientamento=1):
    """I byte EXIF di una foto scattata a casa: orientamento, marca,
    ora e il GPS — che e' quello che non deve uscire. Attrezzo delle
    prove del cantiere «niente GPS nelle foto» (set 2026)."""
    from PIL import Image
    from PIL.TiffImagePlugin import IFDRational
    ex = Image.Exif()
    ex[0x0112] = orientamento
    ex[0x010F] = "Apple"
    ex[0x9003] = "2026:09:13 10:00:00"
    ex[0x8825] = {1: "N", 2: tuple(IFDRational(v) for v in (45, 27, 0)),
                  3: "E", 4: tuple(IFDRational(v) for v in (9, 11, 0))}
    return ex.tobytes()


def _gps_dentro(raw):
    """I campi GPS che questi byte portano ANCORA: {} e' la risposta
    che si vuole leggere dappertutto."""
    import io
    from PIL import Image
    with Image.open(io.BytesIO(raw)) as im:
        return dict(im.getexif().get_ifd(0x8825))


def prove_busta_ritiro():
    """La busta di consegna (ago 2026): nome del destinatario e codice
    di ritiro DENTRO l'ordine, cifrati col trasporto dei contenuti
    digitali ma MAI con la sua semantica — aprire la busta non e' una
    ricevuta, e la macchina dell'escrow non sa che esiste. NIENTE gate
    su segna_spedito (decisione di Andrea): il codice arriva quando il
    pacco e' GIA' al punto."""
    print("\n[la busta di consegna]")
    import asyncio
    import shutil
    import sqlite3
    import tempfile
    import time as _t

    # Pillow e io servono a _amb, che gira molto prima del punto in
    # cui la foto del documento nasce: se Pillow manca, questa prova si
    # gira come si e' sempre girata (il perche' sta dentro _amb)
    import io as _io
    try:
        from PIL import Image as _Im, ImageOps as _IOps
    except ImportError:
        _Im = _IOps = None

    # la whitelist delle firme e' una costante, non una funzione:
    # si estrae per testo come tutto il resto, o la prova giudicherebbe
    # una tabella scritta a mano invece di quella vera
    _i = _SORGENTE.index("FIRME_DOC_BUSTA = (")
    _firme_doc = _SORGENTE[_i:_SORGENTE.index("\n)\n", _i) + 3]
    buste_dir = tempfile.mkdtemp(prefix="buste-prove-")

    # --- le sentinelle di forma: la SEPARAZIONE dall'escrow ---------
    dep = pezzo("deposita_busta_ritiro").split('"""')[-1]
    let = pezzo("leggi_busta_ritiro").split('"""')[-1]
    sped = pezzo("segna_spedito").split('"""')[-1]
    prova("deposito: solo venditore, su locked/shipped/dispute", True,
          "venditore_id=?" in dep
          and "'locked','shipped','dispute'" in dep)
    prova("deposito: esige la via punto", True, 'o["via_punto"]' in dep)
    prova("deposito: UN solo UPDATE, e tocca SOLO le colonne busta", 1,
          dep.count("UPDATE"))
    prova("deposito: non tocca stato, spedito_il, consegnato", [],
          [x for x in ("stato='", "spedito_il", "consegnato")
           if x in dep])
    prova("deposito: cifra col trasporto dei contenuti digitali", True,
          "_cifra_contenuto(" in dep)
    prova("deposito: il journal porta l'impronta, mai il testo", True,
          "hashlib.sha256(codice" in dep and "[:16]" in dep)
    prova("deposito: notifiche statiche, mai il contenuto", [],
          [x for x in ("{nome", "{codice") if x in dep])
    # il GET e' PURO: aprire la busta significa poter andare a
    # ritirare, NON aver ricevuto — qui vive la separazione
    prova("lettura: GET puro, nessuna scrittura", [],
          [x for x in ("UPDATE", "INSERT", "commit") if x in let])
    prova("lettura: non sa nemmeno cosa sia `consegnato`", False,
          "consegnato" in let)
    prova("lettura: l'admin non ha strada", False, "e_admin" in let)
    prova("lettura: autorizzazione PRIMA dell'esistenza (anti-oracolo)",
          True, "compratore_id=? OR venditore_id=?" in let
          and let.index("Operazione non permessa")
          < let.index("Nessuna istruzione"))
    # il gate NON esiste (decisione di Andrea che ha rovesciato il
    # brief): in segna_spedito la busta compare solo DOPO l'UPDATE,
    # cioe' nel ramo delle notifiche — mai in una guardia
    prova("segna_spedito: nessun gate sulla busta", True,
          sped.index("UPDATE ordini SET stato='shipped'")
          < sped.index("busta_il"))
    # il segnale d'arrivo e' UNO e parte da due strade: la costante
    # e' definita una volta e usata due
    prova("il «ti aspetta» e' UNA costante per due strade", 3,
          _SORGENTE.count("MSG_BUSTA_PRONTA"))
    # le finestre dell'escrow non sanno che la busta esiste
    prova("controlla_scadenze e' cieca alla busta", False,
          "busta" in pezzo("controlla_scadenze"))
    # lo strip: nome e codice non escono MAI da /api/orders
    mo = pezzo("miei_ordini")
    prova("lo strip di /api/orders copre nome e codice", True,
          'r.pop("busta_nome"' in mo and 'r.pop("busta_codice"' in mo)
    # la nota in disputa dice SE e QUANDO (e le correzioni), mai cosa
    ad = pezzo("apri_disputa")
    prova("la disputa racconta la busta senza aprirla", True,
          "nota_punto" in ad and "busta_correzioni" in ad
          and "_decifra_contenuto" not in ad)
    # il promemoria al posto del gate: popolazione e ancora giuste
    sb = pezzo("sollecita_buste_ferme").split('"""')[-1]
    prova("il promemoria pesca shipped+via_punto+busta assente", True,
          "o.stato='shipped' AND o.via_punto=1 AND o.busta_il=0" in sb)
    prova("...con l'ancora spedito_il e le colonne SUE", True,
          "MAX(o.spedito_il + ?" in sb and "sollecito_busta_il" in sb)
    prova("...ed e' agganciato all'orologio", 1,
          _SORGENTE.count("await sollecita_buste_ferme()"))
    prova("il libro mastro sorveglia la busta fuori contratto", True,
          "busta fuori contratto" in _SORGENTE)

    # --- LA BUSTA DIRETTA (ago 2026, cantiere 45): le forme ----------
    # Il venditore dichiara che il codice di ritiro arriva
    # direttamente al compratore. Le sentinelle guardano il CODICE
    # (codice(): via i commenti — la prosa che racconta la clausola
    # la renderebbe verde anche a clausola tolta), e la RIGA INTERA
