def pezzo_js(mini, firma, fine="\n\n"):
    """Il gemello di pezzo() per miniapp.html: estrae una funzione JS
    per testo, dalla firma alla prima riga vuota."""
    i = mini.index(firma)
    return mini[i:mini.index(fine, i)]


# LA BOLT11 VERA del 16 set 2026: 7468 sats, scadenza 3600 s, cltv 80,
# nata alle 14:28:38 UTC — quella che il foglio ha suggerito e il
# coordinatore ha rifiutato. E' pubblica (una fattura non porta segreti)
# e vale come fixture perche' e' il caso vissuto: importo sbagliato
# (ne voleva 7543) E scadenza da un'ora esatta, tutt'e due insieme.
BOLT11_VERA_7468 = (
    "")


def bolt11_finta(sats, scadenza, quando, firma=None, phash=0):
    """Una bolt11 SINTATTICAMENTE vera — bech32 col suo checksum, i
    campi taggati al posto giusto, la firma di zeri — per provare il
    lettore del client senza una chiave: `leggiBolt11` verifica il
    checksum e non la firma (quella la guarda LND). sats=0 e' la
    fattura senza importo. Il conio e' BOLT-11 a mano: hrp `lnbc` +
    importo in nBTC (1 n = 0,1 sat), timestamp su 35 bit, poi
    [tipo, lunghezza (10 bit), dati], poi 520 bit di firma."""
    ALF = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
    hrp = "lnbc" + (f"{sats * 10}n" if sats else "")

    def bits(n, larghezza):
        return [(n >> (5 * k)) & 31 for k in range(larghezza - 1, -1, -1)]

    def tag(tipo, dati):
        return [tipo] + bits(len(dati), 2) + dati

    def minimo(n):
        g = 1
        while n >> (5 * g):
            g += 1
        return bits(n, g)

    dati = bits(quando, 7)
    # p: il payment hash (256 bit su 52 gruppi, 4 bit di riempimento).
    # Di zeri se non lo si sceglie; chi deve distinguere DUE fatture —
    # «paga da un'altra cassaforte», 21 set 2026 — ne passa uno suo.
    dati += tag(1, bits(phash << 4, 52))
    dati += tag(13, [])                  # d: descrizione vuota
    if scadenza is not None:             # senza `x` vale un'ora (BOLT-11)
        dati += tag(6, minimo(scadenza))     # x: la scadenza
    dati += tag(24, minimo(80))          # c: cltv finale, come LND
    dati += tag(16, [0] * 52)            # s: payment secret di zeri
    # la firma: 65 byte di zeri — o 104 gruppi scelti da chi prova un
    # lettore che non deve scambiarli per campi (20 set 2026)
    dati += list(firma) if firma else [0] * 104

    def polymod(v):
        GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]
        chk = 1
        for x in v:
            b = chk >> 25
            chk = ((chk & 0x1ffffff) << 5) ^ x
            for i in range(5):
                if (b >> i) & 1:
                    chk ^= GEN[i]
        return chk

    esp = [ord(c) >> 5 for c in hrp] + [0] + [ord(c) & 31 for c in hrp]
    pm = polymod(esp + dati + [0] * 6) ^ 1
    chk = [(pm >> (5 * (5 - i))) & 31 for i in range(6)]
    return hrp + "1" + "".join(ALF[x] for x in dati + chk)


def prove_ssrf_redirect():
    """Il guardiano anti-SSRF si aggirava con un 302 (ago 2026,
    audit): urllib segue i redirect da solo e `url_foto_ammesso`
    giudicava solo il PRIMO indirizzo, quindi un host pubblico che
    rispondeva «vai a 127.0.0.1» portava il server dentro la sua
    stessa rete. E l'import da Nostr non aveva guardie affatto — e
    gira DENTRO il server ogni ora."""
    print("\n[il redirect ricontrollato]")
    import ipaddress
    import urllib.error
    import urllib.request
    from urllib.parse import urlparse

    class _Dns:
        """Un DNS di cartone: nessuna prova deve dipendere da una
        risoluzione vera — la rete altrui non e' una prova."""
        FINTI = {"pubblico.tld": "93.184.216.34",
                 "interno.tld": "10.0.0.5"}

        @staticmethod
        def getaddrinfo(host, _porta):
            ip = _Dns.FINTI.get(host, host)
            ipaddress.ip_address(ip)      # un nome sconosciuto esplode qui
            return [(2, 1, 6, "", (ip, 0))]

    amb = {"urllib": urllib, "socket": _Dns, "ipaddress": ipaddress,
           "urlparse": urlparse, "print": lambda *a, **k: None}
    exec(pezzo("url_foto_ammesso"), amb)
    i = _SORGENTE.index("class _RedirectControllato")
    exec(_SORGENTE[i:_SORGENTE.index("def scarica_foto_import(", i)], amb)

    ammesso = amb["url_foto_ammesso"]
    prova("un host pubblico va bene", True, ammesso("http://pubblico.tld/a.jpg"))
    prova("un indirizzo privato no", False, ammesso("http://10.0.0.5/a.jpg"))
    prova("e nemmeno il loopback", False, ammesso("http://127.0.0.1/a.jpg"))

    # IL SALTO: e' qui che stava il buco, e si prova sul salto
    class _Testa(dict):
        def get_all(self, n, d=None):
            return d

    guardia = amb["_RedirectControllato"]()
    partenza = urllib.request.Request("http://pubblico.tld/foto.jpg")

    def salto(dove):
        try:
            r = guardia.redirect_request(partenza, None, 302, "Found",
                                         _Testa(), dove)
            return "seguito" if r is not None else "non seguito"
        except urllib.error.HTTPError:
            return "fermato"

    prova("il salto verso il loopback si ferma", "fermato",
          salto("http://127.0.0.1/segreto"))
    prova("il salto verso la rete interna si ferma", "fermato",
          salto("http://interno.tld/admin"))
    prova("il salto verso i metadati del cloud si ferma", "fermato",
          salto("http://169.254.169.254/latest/meta-data/"))
    prova("il salto verso file:// si ferma", "fermato",
          salto("file:///etc/passwd"))
    prova("un salto onesto si segue come sempre", "seguito",
          salto("http://pubblico.tld/altra.jpg"))

    # --- SENTINELLE -------------------------------------------------
    # Uno scaricatore solo: se ne ricompare un altro con urlopen nudo,
    # le guardie tornano a valere per meta' del progetto
    prova("sentinella: in server.py non c'e' piu' un urlopen nudo", True,
          "urllib.request.urlopen(" not in _SORGENTE)
    prova("sentinella: l'apritore controllato e' quello usato", True,
          "_APRITORE_FOTO.open(" in pezzo("scarica_foto_url"))
    prova("sentinella: il guardiano si chiama anche sulla partenza",
          True, "url_foto_ammesso(url)" in pezzo("scarica_foto_url"))
    # e l'import da Nostr lo riceve: il patto del `vaglio` — insieme al
    # cambio, che dall'ago 2026 viaggia sulla stessa strada, e dal set
    # 2026 anche il ripulitore (vedi piu' sotto, «la QUARTA porta»). Dal
    # 23 set 2026 in coda c'e' anche la lista dei relay da cui leggere,
    # gia' passata dal giudice delle letture: prove_letture_relay_collaudo
    prova("sentinella: l'import orario riceve lo scaricatore del server",
          True, "vaglio, scarica_foto_url, cambio_import,\n"
          "                pulisci=spoglia_metadati, relays=relays)"
          in _SORGENTE)
    imp = open("importa_nostr.py", encoding="utf-8").read()
    prova("sentinella: e l'import lo usa quando ce l'ha", True,
          "def scarica_foto(url: str, annuncio_id: int, indice: int, "
          "scarica=None,\n                 pulisci=None)" in imp
          and "esito = scarica(url)" in imp)


def prove_niente_ai_nella_ricerca():
    """L'AI E' USCITA DALLA RICERCA (ago 2026, decisione di Andrea).
    Questa famiglia ha CAMBIATO LATO: prima certificava il freno della
    ricerca AI — la quota oraria, il catalogo da 300, il ripiego a
    quota finita — e adesso certifica che di quella strada non resti
    niente. Il precedente e' la sentinella del reaper sui 'creato' e
    quella degli avatar.

    Perche' serve una prova, e non basta aver cancellato: una chiamata
    ad Anthropic che rientrasse di soppiatto nella ricerca non
    romperebbe nulla di visibile — costerebbe credito a ogni tasto, e
    lo si scoprirebbe dalla fattura."""
    print("\n[niente AI nella ricerca]")
    c = pezzo("cerca")
    prova("la ricerca non chiama piu' il modello", True,
          "ai.messages.create" not in c)
    prova("...ne' costruisce un catalogo per lui", True,
          "catalogo" not in c)
    prova("il freno a gettoni non esiste piu'", 0,
          _SORGENTE.count("_ricerca_ai_concessa"))
    prova("...ne' la sua quota in memoria", 0,
          _SORGENTE.count("RICERCA_QUOTA"))
    prova("...ne' il tetto del catalogo", 0,
          _SORGENTE.count("TETTO_CATALOGO_AI"))
    # La rotta resta AUTENTICATA: non e' piu' credito da difendere, ma
    # una superficie pubblica senza un motivo e' solo superficie (la
    # lezione di /api/comuni).
    prova("il guscio resta autenticato", True, "verifica_utente(" in c)
    # E la forma della risposta non si tocca, per i client in cache.
    prova("senza busta resta l'array di sempre", True,
          '{"annunci": annunci, "ai": False} if busta else annunci' in c)
    mini = open("miniapp.html", encoding="utf-8").read()
    # Il client non chiama piu' `/api/search` affatto: la ricerca
    # passa dalla vetrina, e a reggere le due forme della risposta —
    # l'array di ieri e la busta paginata — resta `leggiPagina`, che
    # e' il posto dove quel patto e' sempre vissuto.
    prova("il client non chiama piu' /api/search", 0,
          mini.count("API_BASE}/search"))
    prova("...e le due forme della risposta le regge leggiPagina", True,
          "const leggiPagina = j => Array.isArray(j) ? "
          "{annunci: j, cursore: null} : j;" in mini)
    # IL MODELLO RESTA DOVE SERVE: la moderazione, la
    # ricategorizzazione e l'import a lotti continuano a chiamarlo.
    # Questa prova e' la meta' che impedisce di leggere la famiglia
    # come «via l'AI da Barattolo».
    prova("l'AI resta dov'e' il suo mestiere", True,
          _SORGENTE.count("ai.messages.create") >= 3)


def prove_initdata():
    """La freschezza dell'initData (ago 2026, audit). La firma dice
    CHI, non QUANDO: finche' nessuno guardava `auth_date`, un initData
    catturato apriva quell'account per sempre. Qui si firma per
    davvero, con un token di prova, e si guarda cosa passa e cosa no."""
    print("\n[freschezza dell'initData]")
    import hashlib
    import hmac
    import json
    import time
    from urllib.parse import parse_qsl, urlencode

    TOKEN = "123456:token-di-prova"

    def initdata(quando=None, token=TOKEN):
        """Un initData come lo firma Telegram. `quando=None` = senza
        auth_date: e' il caso che deve fallire da solo."""
        dati = {"query_id": "AAA", "user": '{"id":111,"first_name":"Ada"}'}
        if quando is not None:
            dati["auth_date"] = str(int(quando))
        controllo = "\n".join(f"{k}={v}" for k, v in sorted(dati.items()))
        chiave = hmac.new(b"WebAppData", token.encode(),
                          hashlib.sha256).digest()
        dati["hash"] = hmac.new(chiave, controllo.encode(),
                                hashlib.sha256).hexdigest()
        return urlencode(dati)

    class FintoErrore(Exception):
        def __init__(self, codice, testo=""):
            self.codice, self.testo = codice, testo

    class FintoDb:
        """Un database di cartone: qui non si prova la scrittura, si
        prova CHI ci arriva."""
        def __init__(self, visite):
            self.visite = visite

        def execute(self, *a):
            self.visite.append(a[0][:20])
            return self

        def fetchone(self):
            return None

        def commit(self):
            pass

        def close(self):
            pass

    def monta(ore, visite, in_sessione=None):
        amb = {"parse_qsl": parse_qsl, "hmac": hmac, "hashlib": hashlib,
               "json": json, "time": time, "BOT_TOKEN": TOKEN,
               "MODALITA_COLLAUDO": False, "ORE_INITDATA": ore,
               "MSG_INITDATA_SCADUTO": "scaduta",
               "HTTPException": FintoErrore,
               "db": lambda: FintoDb(visite),
               "nuovo_codice_negozio": lambda con: "abcd1234",
               "utente_da_sessione": lambda t: in_sessione}
        # verifica_utente non scrive piu' l'UPSERT a mano: lo chiede a
        # _upsert_da_telegram, la porta unica delle tre — reale() e non
        # uno stub, per non imitarne anche i bug (la lezione di sempre)
        exec(pezzo("_upsert_da_telegram"), amb)
        exec(pezzo("verifica_utente"), amb)
        return amb["verifica_utente"]

    def entra(init, ore=24, sessione="", in_sessione=None):
        """Torna l'id di chi entra, o il testo del rifiuto."""
        try:
            return monta(ore, [], in_sessione)(init, sessione)["id"]
        except FintoErrore as e:
            return e.testo

    ora = time.time()
    prova("initData appena firmato: si entra", 111, entra(initdata(ora)))
    prova("di un'ora: si entra", 111, entra(initdata(ora - 3600)))
    prova("di 23 ore e mezza: si entra ancora", 111,
          entra(initdata(ora - 23.5 * 3600)))
    prova("di 25 ore: rifiutato", "scaduta",
          entra(initdata(ora - 25 * 3600)))
    prova("di un anno: rifiutato", "scaduta",
          entra(initdata(ora - 365 * 86400)))
    # il rifiuto della scadenza DEVE essere distinguibile da quello
    # della firma storta, o il client non puo' dire «riaprimi»
    prova("firma storta: rifiutata, con l'ALTRO messaggio",
          "Autenticazione Telegram non valida",
          entra(initdata(ora, token="999:un-altro-token")))
    # fail-closed per costruzione, come importo_invoice: il campo che
    # manca vale 0, cioe' vecchio di un'era
    prova("auth_date assente: rifiutato senza un ramo apposta",
          "scaduta", entra(initdata(None)))
    prova("il rifiuto e' un 401", 401,
          _codice_rifiuto(monta(24, []), initdata(ora - 25 * 3600),
                          FintoErrore))
    # la leva spenta riapre esattamente il buco: e' dichiarato, e la
    # prova lo dice invece di lasciarlo credere
    prova("leva a 0: il vecchio ripassa (buco riaperto, dichiarato)",
          111, entra(initdata(ora - 365 * 86400), ore=0))
    # le altre due porte non sanno nulla di questa finestra
    prova("il cookie di sessione non passa di qui", 222,
          entra("", in_sessione={"id": 222}))

    # una credenziale scaduta non deve nemmeno TOCCARE il database
    visite = []
    try:
        monta(24, visite)(initdata(ora - 25 * 3600))
    except FintoErrore:
        pass
    prova("chi e' scaduto non scrive sul database", [], visite)

    # --- SENTINELLE: il controllo non deve sparire in un riordino ----
    vu = pezzo("verifica_utente")
    prova("sentinella: auth_date si legge davvero", True, "auth_date" in vu)
    # la scrittura del ramo vero e' l'ULTIMA del pezzo (la prima e'
    # quella del collaudo): rindex, o si confronterebbe col ramo sbagliato
    prova("sentinella: si controlla PRIMA di scrivere sul database",
          True, vu.index("ORE_INITDATA") < vu.rindex("_upsert_da_telegram("))
    # dentro il try l'except si mangerebbe l'HTTPException e la
    # riscriverebbe col messaggio generico: il client perderebbe il
    # solo segnale che gli dice di riaprirsi
    prova("sentinella: il rifiuto della scadenza non e' inghiottito",
          True, vu.index("except Exception") < vu.index("ORE_INITDATA"))
    mini = open("miniapp.html", encoding="utf-8").read()
    prova("il client distingue la scadenza dalla vetrina", True,
          "r.status === 401 && !!tg?.initData" in mini
          and "BANNER_SCADUTO" in mini)


def prove_foto():
    """La cartella foto/ non e' piu' montata (ago 2026, audit): era
    l'unica directory servita in blocco di tutto il progetto, contro
    la regola ferrea 3. Adesso c'e' una rotta con la whitelist delle
    FORME che i nostri scrittori producono — e le forme vanno tenute
    allineate a loro, o le foto vere spariscono dalla vetrina."""
    print("\n[le foto senza StaticFiles]")
    import re
    amb = {"re": re}
    i = _SORGENTE.index("NOME_FOTO = re.compile")
    exec(_SORGENTE[i:_SORGENTE.index("TIPI_FOTO =", i)], amb)
    ammesso = lambda n: bool(amb["NOME_FOTO"].match(n))

    # I nomi VERI, uno per scrittore
    for nome in ("a12_0.jpg", "a12_0_min.jpg",
                 "a12_0_1785852876.jpg", "a12_0_1785852876_min.jpg",
                 "a7_1.png", "a7_1.webp", "a7_1.gif", "a7_1_min.jpg",
                 "av_0236b74b_1784996031.jpg"):
        prova(f"si serve la foto vera {nome}", True, ammesso(nome))

    # e tutto cio' che in quella cartella non c'e' mai stato — piu'
    # (ago 2026) la gemella degli avatar, che c'era stata eccome: la
    # faceva genera_miniature_mancanti passando su ogni .jpg e non
    # solo sugli annunci, ed e' la forma che al primo giro era
    # sfuggita alla tabella degli scrittori. Adesso non se ne producono
    # piu' e i 75 di produzione sono stati tolti dal disco (613
    # rimasti), quindi il caso ha cambiato lato: da «si serve» a «non
    # si serve», che e' l'affermazione piu' forte delle due — se un
    # domani ne ricomparisse una, la rotta non la pubblicherebbe.
    for nome in ("../config.py", "..%2fconfig.py", "config.py",
                 "satmarket.db", "a1_0.jpg.exe", "", "a1_0.jpg\n",
                 "a1_0.jpg/../x", "av_../x_1.jpg", "a_0.jpg",
                 "av_f29bcbf7_1785852876_min.jpg"):
        prova(f"non si serve {nome!r}", False, ammesso(nome))

    # IL PODIO del riepilogo e' il quarto scrittore: il canale lo mostra
    # per URL, quindi senza la sua forma qui Telegram si vedrebbe
    # rispondere 404 dal nostro stesso server.
    prova("si serve il podio del lunedi'", True, ammesso("pod_2026-08-17.jpg"))
    prova("si serve la figura del negozio", True,
          ammesso("neg_10_1786960394.jpg"))
    for nome in ("pod_2026-8-17.jpg", "pod_.jpg", "pod_2026-08-17.png",
                 "pod_2026-08-17_min.jpg", "pod_../config.py"):
        prova(f"non si serve {nome!r}", False, ammesso(nome))

    # --- SENTINELLE ---------------------------------------------------
    # La regola ferrea 3 diventa verificabile invece che raccomandata:
    # non si guardano le parole (i commenti la nominano apposta), si
    # guarda il CODICE
    prova("sentinella: nessuna directory montata, in tutto il server",
          True, "app.mount(" not in _SORGENTE
          and "from fastapi.staticfiles import" not in _SORGENTE)
    # la formula dell'ETag e' UNA: due rotte che la calcolassero in
    # modo diverso manderebbero header divergenti, e il 304 delle
    # illustrazioni — che nacque da un caso vero — smetterebbe di
    # scattare senza che nessuno se ne accorga
    prova("sentinella: la formula dell'ETag vive in un posto solo", 1,
          _SORGENTE.count('f"{st.st_mtime}-{st.st_size}"'))
    prova("sentinella: le illustrazioni passano dallo stesso cuore",
          True, "_file_con_etag" in pezzo("asset_categoria"))
    # e la cache delle due resta quella di prima: revalidazione per le
    # illustrazioni (nomi non versionati), un giorno per le foto
    prova("le illustrazioni restano a revalidazione", True,
          '"public, no-cache"' in pezzo("asset_categoria"))
    prova("le foto restano a un giorno", True,
          '"public, max-age=86400"' in pezzo("foto_annuncio"))
    # la forma dell'avatar dice «esadecimale» perche' il codice negozio
    # lo fa token_hex: se un domani cambiasse alfabeto, TUTTE le facce
    # sparirebbero in silenzio (404) e nessuna prova funzionale se ne
    # accorgerebbe. Qui il legame e' scritto.
    prova("sentinella: il codice negozio e' ancora esadecimale", True,
          "secrets.token_hex(" in pezzo("nuovo_codice_negozio"))


def prove_foto_scarti():
    """NESSUNA FOTO SPARISCE IN SILENZIO (ago 2026, caso dal campo).
    Ogni scarto di salva_foto era un `continue` muto: l'annuncio
    nasceva con meno foto e nessuno lo diceva. Adesso salva_foto torna
    anche i MOTIVI, e la risposta della pubblicazione li porta fino
    all'utente. Qui si gira il pezzo VERO su una cartella usa-e-getta,
    piu' le sentinelle sulle righe che in un riordino sparirebbero
    riportandosi dentro il bug."""
    print("\n[le foto che sparivano in silenzio]")
    import base64
    import io
    import re
    import tempfile

    try:
        from PIL import Image, ImageOps, ImageStat
    except ImportError:
        salta("gli scarti di salva_foto, girati per davvero",
              "Pillow non e' installata")
    else:
        with tempfile.TemporaryDirectory() as tmp:
            amb = {"os": os, "io": io, "re": re, "base64": base64,
                   "ImmaginePillow": Image, "ImageOps": ImageOps,
                   "ImageStat": ImageStat,
                   "pillow_heif": None, "FOTO_DIR": tmp,
                   "print": lambda *a, **k: None}
            i = _SORGENTE.index("MINIATURA_LATO = ")
            exec(_SORGENTE[i:_SORGENTE.index("\n\n\n", i)], amb)
            # e le tre leve della foto vuota, che vivono in un blocco
            # loro: chi estrae una funzione ne eredita le dipendenze
            i = _SORGENTE.index("FOTO_COLORI_MIN = ")
            exec(_SORGENTE[i:_SORGENTE.index("\n\n\n", i)], amb)
            # e le whitelist della spoliazione (set 2026): salva_foto
            # adesso toglie i metadati, e senza i suoi pezzi qui il
            # pezzo VERO esploderebbe invece di dire la sua
            i = _SORGENTE.index("SEGMENTI_JPEG_TENUTI = ")
            exec(_SORGENTE[i:_SORGENTE.index("\n\n\n", i)], amb)
            for f in ("converti_in_jpeg", "miniatura_jpeg", "_foto_vuota",
                      "_salva_una_foto", "_e_immagine", "_spoglia_jpeg",
                      "_spoglia_png", "_spoglia_webp", "_porta_metadati",
                      "spoglia_metadati", "salva_foto"):
                exec(pezzo(f), amb)

            def uri(raw, tipo="jpeg"):
                return (f"data:image/{tipo};base64,"
                        + base64.b64encode(raw).decode())

            out = io.BytesIO()
            # una FOTO e non una tinta unita: quella oggi la rifiuta
            # _foto_vuota, che e' il suo mestiere (vedi foto_finta)
            foto_finta().save(out, "JPEG")
            buona = out.getvalue()
            pdf = b"%PDF-1.4\n1 0 obj<</Type/Catalog>>endobj\n%%EOF\n"

            # il giudice dei byte, sui casi nudi
            prova("un JPEG e' un'immagine", True, amb["_e_immagine"](buona))
            prova("un PDF no", False, amb["_e_immagine"](pdf))
            prova("il vuoto no", False, amb["_e_immagine"](b""))

            # IL CASO DAL CAMPO: un PDF rinominato .jpg. Il data-URI lo
            # scrive il browser dall'ESTENSIONE, quindi arriva qui
            # etichettato image/jpeg e prima finiva SCRITTO sul disco.
            nomi, scarti = amb["salva_foto"](7, [uri(buona), uri(pdf)])
            prova("il PDF vestito da foto non si salva", 1, len(nomi))
            prova("...e il motivo si dice", ["non è una foto"], scarti)
            prova("...e sul disco non ci finisce", ["a7_0.jpg", "a7_0_min.jpg"],
                  sorted(f for f in os.listdir(tmp) if f.startswith("a7_")))

            # gli altri motivi, uno per uno
            for foto, atteso in (
                    (["non sono un data-uri"], "formato non riconosciuto"),
                    # base64 che non torna: b64decode butta i caratteri
                    # fuori alfabeto, quindi per farlo INCIAMPARE serve
                    # una lunghezza storta, non solo spazzatura — la
                    # spazzatura pura decodifica a vuoto e la ferma
                    # _e_immagine, un passo piu' in la'
                    (["data:image/jpeg;base64,!!!non-base64!!!"],
                     "foto illeggibile"),
                    (["data:image/jpeg;base64,!!!"], "non è una foto"),
                    ([uri(b"\xff\xd8" + bytes(16_000_000))],
                     "troppo grande (oltre 15MB)"),
                    ([uri(b"nemmeno per sogno", "heic")],
                     "foto HEIC: questo server non sa convertirla")):
                nomi, scarti = amb["salva_foto"](8, foto)
                prova(f"scarto detto: {atteso}", ([], [atteso]), (nomi, scarti))

            # e il caso normale non inventa avvisi
            nomi, scarti = amb["salva_foto"](9, [uri(buona), uri(buona)])
            prova("due foto buone, zero scarti", (2, []), (len(nomi), scarti))
            prova("nessuna foto chiesta, nessuno scarto", ([], []),
                  amb["salva_foto"](10, []))

    # --- SENTINELLE ---------------------------------------------------
    mini = open("miniapp.html", encoding="utf-8").read()
    # 1) IL TRASCINAMENTO. Il riquadro e' tratteggiato e si chiama
    # photo-drop: sul desktop chiede di essere usato cosi', e per un
    # anno ha avuto il solo onclick — senza preventDefault sul dragover
    # il browser non emette nemmeno l'evento drop, quindi trascinare una
    # foto non faceva ASSOLUTAMENTE NIENTE (riprodotto). Se queste
    # righe spariscono, il caso dal campo torna identico.
    riquadro = mini[mini.index('<div class="photo-drop"'):]
    riquadro = riquadro[:riquadro.index(">")]
    for gancio in ("ondragenter", "ondragover", "ondragleave", "ondrop"):
        prova(f"sentinella: il riquadro ascolta {gancio}", True,
              gancio in riquadro)
    i = mini.index("function fotoSopra(")
    prova("sentinella: ed e' il preventDefault a renderlo un bersaglio",
          True, "ev.preventDefault()" in mini[i:mini.index("\n}", i)])
    # 2) l'errore dell'anteprima si LEGGE e si DICE: prima era un
    # `if (r.ok)` senza else, e in pagina restava il segnaposto «verra'
    # convertita alla pubblicazione» — una promessa mai verificata
    prova("sentinella: il motivo del server arriva all'utente", True,
          "res({motivo: d.detail || `Non riesco a preparare" in mini)
    prova("sentinella: il segnaposto bugiardo non c'e' piu'", False,
          "verrà convertita" in mini)
    # 3) il FileReader che fallisce non e' piu' muto
    prova("sentinella: il FileReader che fallisce lo dice", True,
          "Non riesco a leggere «" in mini)
    # 4) quante ne sono entrate: il server lo dice e il client lo mostra
    prova("sentinella: la pubblicazione conta le foto", 2,
          _SORGENTE.count('"foto_salvate": len(nomi)'))
    # due chiamate (pubblicazione e modifica) piu' la definizione
    prova("sentinella: e il client lo racconta in due posti", 2,
          mini.count("= avvisoFoto("))
    # 5) salva_foto ha DUE valori di ritorno, e chi la chiama li prende
    # entrambi: con un solo nome l'unpacking esplode subito, ma un
    # terzo chiamante distratto potrebbe scrivere `nomi = salva_foto(...)`
    # e ritrovarsi una tupla dove aspetta una lista
    prova("sentinella: i chiamanti di salva_foto scompattano in due", 2,
          len(re.findall(r"\w+, \w+ = await asyncio.to_thread\(\s*salva_foto|"
                         r"\w+, \w+ = await asyncio\.to_thread\(salva_foto",
                         _SORGENTE)))
    # 6) I DUE SILENZI DEL CASO XIAOMI (ago 2026, dal campo: «non
    # riesco a inserire le foto» su un Android vecchio dentro
    # Telegram). Il chooser che torna a MANI VUOTE — il for su una
    # lista vuota non fa niente, e il bottone «non fa niente» alla
    # lettera — e il decode che non finisce MAI, col chip «Carico la
    # foto…» eterno e Pubblica bloccato senza spiegazione. Le
    # sentinelle guardano DENTRO il loro ramo (la lezione del reaper):
    # cercate nel file intero non potrebbero fallire.
    i = mini.index("async function aggiungiFoto(")
    corpo = mini[i:mini.index("function fotoSopra(")]
    prova("sentinella: la lista vuota si racconta, nei due contesti", 2,
          corpo.count("Non ho ricevuto nessuna foto"))
    prova("sentinella: ...e a decidere il contesto e' Telegram", True,
          "tg?.initData" in corpo)
    # find() e non index(): a blocco tolto deve diventare ROSSA, non
    # esplodere portandosi dietro le prove dopo di lei
    _pos = corpo.find("Non ho ricevuto nessuna foto")
    prova("sentinella: ...PRIMA del for, che a mani vuote non fa niente",
          True, 0 <= _pos < corpo.index("for (const file of files)"))
    i = mini.index("function ridimensiona(")
    corpo = mini[i:mini.index("async function fotoScelte(")]
    j = corpo.index("img.onload")
    k = corpo.index("img.onerror")
    prova("sentinella: il watchdog del decode e' armato prima dei callback",
          True, "setTimeout" in corpo[:j])
    # E AL TIMEOUT NON SI MOLLA PIU' (set 2026): trenta secondi di
    # silenzio dicono che QUESTO telefono non decodifica quel file, non
    # che il file sia rotto — quindi si chiede al server, che i byte li
    # ha uguali. La via d'uscita non e' piu' una frase: e' una strada.
    prova("sentinella: ...e al timeout si chiede al server, non si molla",
          True, "res(await fotoDalServer(file))" in corpo[:j])
    prova("sentinella: onload disarma il watchdog nel SUO ramo", True,
          "clearTimeout(watchdog)" in corpo[j:k])
    prova("sentinella: onerror pure — o la strada del server, che puo' "
          "durare piu' di trenta secondi su rete lenta, correrebbe col "
          "timer addosso", True, "clearTimeout(watchdog)" in corpo[k:])
    prova("sentinella: e il callback postumo tace, in tutti e due i rami",
          2, corpo.count("if (decodeMuto) return"))

    # ---- NESSUNA FOTO SPARISCE IN SILENZIO, NEMMENO NEL BROWSER ----
    # (set 2026, caso dal campo: annuncio #354 nato SENZA foto, colonna
    # `foto` vuota, e chi ha pubblicato non ha visto nessun avviso.)
    # Le sentinelle dicono come sono scritti i rami; questo li FA
    # GIRARE, che e' l'unico modo di rispondere alla domanda vera:
    # «se la foto non entra, chi l'ha scelta lo viene a sapere?».
    import shutil as _sh5
    import subprocess as _sp5
    import json as _json5
    if not _sh5.which("node"):
        salta("le quattro strade di ridimensiona, girate per davvero",
              "node non installato")
    else:
        _pezzi = "".join(pezzo_js(mini, f, "\n}\n") + "\n}\n" for f in (
            "function fotoDalServer(file){", "function jpegDalCanvas(img){",
            "function ridimensiona(file){", "async function aggiungiFoto(files){"))
        _banco = """
          // il banco: un telefono finto, con la tela e il server che
          // si comportano come dice CASO
          let CASO = {};
          const _st = setTimeout;
          // il watchdog e' a 30 secondi: qui si sveglia subito, o la
          // prova aspetterebbe mezzo minuto per ogni caso
          globalThis.setTimeout = (fn, ms, ...a) => _st(fn, ms >= 1000 ? 1 : ms, ...a);
          let toasts = [], sellFoto = [], editandoNostr = false;
          const tg = {initData:'x'};
          let DEMO = false, VETRINA = false;
          const API_BASE = '/api';
          function authHdr(){ return ''; }
          function toast(t){ toasts.push(String(t)); }
          function renderFotoPreview(){}
          function haptic(){}
          globalThis.URL = {createObjectURL:()=>'blob:finto',
                            revokeObjectURL:()=>{}};
          globalThis.document = {createElement:()=>({
            getContext:()=>({drawImage(){}}),
            toDataURL:()=>CASO.tela})};
          function Image(){}
          Object.defineProperty(Image.prototype, 'src', {
            set(v){ this._s = v; const io = this;
              if (CASO.decode === 'muto') return;   // ne' onload ne' onerror
              setTimeout(()=>{ if (CASO.decode === 'errore') { io.onerror(); }
                else { io.naturalWidth = CASO.larg; io.naturalHeight = CASO.alt;
                       io.onload(); } }, 0); },
            get(){ return this._s; }});
          globalThis.Image = Image;
          function FileReader(){}
          FileReader.prototype.readAsDataURL = function(){
            const fr = this;
            setTimeout(()=>{ if (CASO.lettore === 'errore') fr.onerror();
              else { fr.result = 'data:image/jpeg;base64,QUJD'; fr.onload(); } }, 0);
          };
          globalThis.FileReader = FileReader;
          globalThis.fetch = async ()=>{
            if (CASO.server === 'rete') throw new Error('rete');
            return {ok: CASO.server === 'ok', json: async ()=>
              CASO.server === 'ok' ? {foto:'data:image/jpeg;base64,DALSERVER'}
                                   : {detail:'Non riesco a leggere questa foto'}};
          };
          const BUONA = 'data:image/jpeg;base64,' + 'Q'.repeat(200);
        """ + _pezzi + """
          async function giro(caso){
            CASO = Object.assign({decode:'ok', larg:4080, alt:3060,
                                  tela:BUONA, server:'ok'}, caso);
            DEMO = !!caso.demo; VETRINA = false;
            toasts = []; sellFoto = [];
            await aggiungiFoto([{name:'IMG_2032.jpg', type:'image/jpeg',
                                 size: caso.peso || 3498244}]);
            return [sellFoto.length, toasts.length,
                    (toasts[0] || '').slice(0, 60)];
          }
          (async ()=>{
            const out = {};
            out.buona = await giro({});
            out.tela0 = await giro({larg:0, alt:0});
            out.telaVuota = await giro({tela:'data:,'});
            out.decodeNo = await giro({decode:'errore'});
            out.muto = await giro({decode:'muto'});
            out.serverNo = await giro({decode:'errore', server:'no'});
            out.reteNo = await giro({decode:'errore', server:'rete'});
            out.demo = await giro({decode:'errore', demo:true});
            out.pesante = await giro({decode:'errore', peso: 20000000});
            console.log(JSON.stringify(out));
          })();
        """
        _r = _sp5.run(["node", "-e", _banco], capture_output=True,
                      text=True, encoding="utf-8", timeout=60)
        try:
            v = _json5.loads((_r.stdout or "").strip())
        except Exception:
            v = None
            prova("il banco del client gira", True,
                  f"node ha detto: {(_r.stderr or '')[:300]}")
        if v:
            # 1) la strada normale: entra, e nessuno dice niente
            prova("la foto buona entra, e nessuno parla", [1, 0, ""],
                  v["buona"])
            # 2) IL SILENZIO NUOVO, quello che ha aperto il cantiere:
            # onload parla ma i pixel non ci sono (naturalWidth 0), la
            # tela nasce 0x0 e toDataURL torna 'data:,' — una stringa
            # che SEMBRA una foto. Prima entrava in sellFoto cosi'
            # com'era: anteprima rotta, e alla pubblicazione lo scarto
            # «formato non riconosciuto». Adesso e' il server a salvarla.
            prova("la tela 0x0 non e' un rifiuto: la salva il server",
                  [1, 0, ""], v["tela0"])
            prova("...e cosi' la tela che torna 'data:,'", [1, 0, ""],
                  v["telaVuota"])
            # 3) il decode che fallisce su un JPEG: PRIMA si rifiutava
            # qui («non è una foto che riesco a leggere») perche' si
            # dava per scontato che il browser i JPEG li sappia leggere
            # tutti. Un JPEG da 12 Mpx dentro una WebView a corto di
            # memoria dice di no, e Pillow lo apre senza fiatare.
            prova("il JPEG che il telefono non decodifica lo prende il server",
                  [1, 0, ""], v["decodeNo"])
            # 4) il decode muto: il watchdog non molla piu', chiede
            prova("il decode che non risponde MAI finisce dal server",
                  [1, 0, ""], v["muto"])
            # 5) e quando non entra, si DICE — sempre, e col perche'
            prova("il server che rifiuta: niente foto, e il suo motivo",
                  [0, 1, "Non riesco a leggere questa foto"], v["serverNo"])
            prova("la rete che cade: niente foto, e lo dice", [0, 1],
                  v["reteNo"][:2])
            prova("in DEMO il ripiego non c'e', e non si finge", [0, 1],
                  v["demo"][:2])
            prova("...e il troppo pesante dice il tetto", True,
                  v["pesante"][0] == 0 and "15MB" in v["pesante"][2])
            # LA REGOLA, in una riga: in nessuno dei nove casi la foto
            # sparisce senza che qualcuno lo dica
            prova("REGOLA: o la foto entra, o qualcuno parla. Sempre.",
                  [], [k for k, r in v.items() if r[0] == 0 and r[1] == 0])
    # LA REGOLA E' DI STRUTTURA, non di memoria: `ridimensiona` e i suoi
    # due aiutanti non hanno piu' una bocca — rispondono {foto} o
    # {motivo} — e a parlare e' il chiamante, in un posto solo. Finche'
    # e' cosi', un ramo nuovo che dimentica di dire il no non esiste.
    for f in ("function ridimensiona(", "function fotoDalServer(",
              "function jpegDalCanvas("):
        prova(f"sentinella: {f.split()[1][:-1]} non parla, risponde",
              False, "toast(" in pezzo_js(mini, f, "\n}\n"))
    _agg = pezzo_js(mini, "async function aggiungiFoto(files){", "\n}\n")
    prova("sentinella: ...e chi la chiama dice SEMPRE il no", True,
          "if (!esito.foto)" in _agg and "esito.motivo ||" in _agg)
    # i tre chiamanti prendono .foto: con la risposta vecchia (una
    # stringa) un oggetto sarebbe stato truthy SEMPRE, e la foto rotta
    # sarebbe entrata dappertutto
    prova("sentinella: tutti e tre i chiamanti leggono l'esito",
          (3, 3), (mini.count("await ridimensiona("),
                   mini.count("esito = await ridimensiona(")))


def prove_foto_vuota():
    """LA FOTO CHE NON MOSTRA NIENTE (ago 2026, caso dal campo):
    l'annuncio 254 e' rimasto in vetrina SEI GIORNI con una foto che a
    schermo era un rettangolo viola — un JPEG sano con dentro otto
    colonne larghe un pixel ripetute 88 volte, che l'occhio fonde in
    una tinta piatta — e l'abbiamo saputo solo perche' il venditore ha
    scritto.

    Il giudice si gira per DAVVERO su immagini vere: una sentinella
    sulla forma direbbe che la guardia c'e', mai che risponda giusto, e
    qui il punto e' esattamente COSA rifiuta e cosa no. Meta' dei casi
    sono grafiche piatte LEGITTIME, perche' il rischio di questa difesa
    e' tutto di quel lato."""
    print("\n[la foto che non mostra niente]")
    import base64
    import io
    import os
    import re
    import tempfile

    try:
        from PIL import Image, ImageDraw, ImageOps, ImageStat
    except ImportError:
        salta("il giudice della foto vuota, girato per davvero",
              "Pillow non e' installata")
    else:
        amb = {"io": io, "ImmaginePillow": Image, "ImageStat": ImageStat}
        i = _SORGENTE.index("FOTO_COLORI_MIN = ")
        exec(_SORGENTE[i:_SORGENTE.index("\n\n\n", i)], amb)
        exec(pezzo("_foto_vuota"), amb)
        vuota = amb["_foto_vuota"]

        def jpeg(im):
            """Come il canvas del client: q90, senza sottocampionare."""
            b = io.BytesIO()
            im.convert("RGB").save(b, "JPEG", quality=90, subsampling=0)
            return b.getvalue()

        # --- QUEL CHE DEVE PASSARE ------------------------------------
        # La bandiera e' il caso che dice perche' il numero dei colori
        # DA SOLO non basterebbe: ne ha QUATTRO, meno del file rotto.
        im = Image.new("RGB", (1024, 1024))
        d = ImageDraw.Draw(im)
        for k in range(0, 1024, 128):
            d.rectangle((k, 0, k + 127, 1024),
                        fill=[(255, 0, 0), (0, 255, 0), (0, 0, 255),
                              (255, 255, 0)][(k // 128) % 4])
        prova("passa: bandiera a bande (4 colori, meno del rotto)",
              False, vuota(jpeg(im)))

        im = Image.new("RGB", (600, 600), (255, 255, 255))
        ImageDraw.Draw(im).rectangle((0, 0, 600, 300), fill=(20, 20, 20))
        prova("passa: due meta' bianco e nero", False, vuota(jpeg(im)))

        im = Image.new("RGB", (1000, 1000), (255, 255, 255))
        ImageDraw.Draw(im).ellipse((200, 200, 800, 800), fill=(247, 147, 26))
        prova("passa: un logo su fondo bianco", False, vuota(jpeg(im)))

        # e questo dice perche' non basta nemmeno l'altra meta': e' PIU'
        # piatto del rotto (0,9 di variazione contro 4), ma ha 161
        # colori — l'antialiasing del testo — e la prima domanda lo salva
        im = Image.new("RGB", (900, 900), (252, 252, 252))
        ImageDraw.Draw(im).text((380, 440), "COD: 7788-2211", fill=(0, 0, 0))
        prova("passa: un buono con una scritta piccola su bianco",
              False, vuota(jpeg(im)))

        # --- QUEL CHE DEVE PRENDERE -----------------------------------
        prova("prende: la tela nera (l'alpha appiattito, il canvas di iOS)",
              True, vuota(jpeg(Image.new("RGB", (704, 628), (0, 0, 0)))))
        prova("prende: la tela bianca",
              True, vuota(jpeg(Image.new("RGB", (704, 628), (255, 255, 255)))))

        # IL CASO VERO, ricostruito al pixel dai colori del file che era
        # in vetrina: otto colonne da 1px nell'ordine che aveva lui
        pal = [(243, 88, 102), (184, 182, 232), (182, 129, 183),
               (180, 147, 102), (95, 61, 52), (84, 28, 135),
               (43, 69, 4), (38, 60, 224)]
        im = Image.new("RGB", (704, 628))
        px = im.load()
        for x in range(704):
            for y in range(628):
                px[x, y] = pal[[6, 3, 5, 7, 0, 4, 2, 1][x % 8]]
        prova("prende: il pattern dell'annuncio 254", True, vuota(jpeg(im)))

        # --- FAIL-OPEN ------------------------------------------------
        prova("niente byte, nessun giudizio", False, vuota(b""))
        prova("byte che non sono un'immagine, nessun giudizio",
              False, vuota(b"%PDF-1.4 non sono una foto"))
        senza = {"io": io, "ImmaginePillow": None, "ImageStat": None,
                 "FOTO_COLORI_MIN": amb["FOTO_COLORI_MIN"],
                 "FOTO_PIATTA_SD": amb["FOTO_PIATTA_SD"]}
        exec(pezzo("_foto_vuota"), senza)
        prova("senza Pillow non si rifiuta niente (fail-open)",
              False, senza["_foto_vuota"](jpeg(
                  Image.new("RGB", (704, 628), (0, 0, 0)))))

        # --- E IL GIRO INTERO, dalla foto allo scarto -----------------
        with tempfile.TemporaryDirectory() as tmp:
            amb2 = {"os": os, "io": io, "re": re, "base64": base64,
                    "ImmaginePillow": Image, "ImageOps": ImageOps,
                    "ImageStat": ImageStat, "pillow_heif": None,
                    "FOTO_DIR": tmp, "print": lambda *a, **k: None}
            i = _SORGENTE.index("MINIATURA_LATO = ")
            exec(_SORGENTE[i:_SORGENTE.index("\n\n\n", i)], amb2)
            i = _SORGENTE.index("FOTO_COLORI_MIN = ")
            exec(_SORGENTE[i:_SORGENTE.index("\n\n\n", i)], amb2)
            # e le whitelist della spoliazione (set 2026), che salva_foto
            # adesso chiama: senza, il pezzo vero esplode qui
            i = _SORGENTE.index("SEGMENTI_JPEG_TENUTI = ")
            exec(_SORGENTE[i:_SORGENTE.index("\n\n\n", i)], amb2)
            for f in ("converti_in_jpeg", "miniatura_jpeg", "_foto_vuota",
                      "_salva_una_foto", "_e_immagine", "_spoglia_jpeg",
                      "_spoglia_png", "_spoglia_webp", "_porta_metadati",
                      "spoglia_metadati", "salva_foto"):
                exec(pezzo(f), amb2)

            def uri(raw):
                return "data:image/jpeg;base64," + base64.b64encode(
                    raw).decode()

            buona = jpeg(foto_finta())
            # una foto vera, anche piccola, non deve mai cadere qui
            prova("una foto vera non e' vuota", False,
                  amb2["_foto_vuota"](buona))
            nera = jpeg(Image.new("RGB", (704, 628), (0, 0, 0)))
            nomi, scarti = amb2["salva_foto"](77, [uri(buona), uri(nera)])
            prova("la foto vuota non si salva", 1, len(nomi))
            prova("...col motivo che dice cosa fare",
                  [amb2["MSG_FOTO_VUOTA"]], scarti)
            prova("...e sul disco non ci finisce",
                  ["a77_0.jpg", "a77_0_min.jpg"],
                  sorted(f for f in os.listdir(tmp) if f.startswith("a77_")))

    # --- SENTINELLE ---------------------------------------------------
    corpo = pezzo("salva_foto")
    prova("sentinella: la guardia vive in salva_foto", True,
          "_foto_vuota(raw)" in corpo)
    # PRIMA di scrivere sul disco, o il file rotto ci finirebbe lo
    # stesso e resterebbe li' a farsi servire
    prova("sentinella: e scatta prima che il file tocchi il disco", True,
          corpo.index("_foto_vuota(raw)") < corpo.index("_salva_una_foto("))
    prova("sentinella: il motivo e' la costante, non una frase a mano",
          True, "scarti.append(MSG_FOTO_VUOTA)" in corpo)
    giudice = pezzo("_foto_vuota")
    # il fail-open e' la meta' che protegge chi pubblica: senza Pillow
    # non si giudica nessuno
    prova("sentinella: senza Pillow il giudice si astiene", True,
          "if not raw or not ImmaginePillow:" in giudice)
    # BOX e' la media esatta — LANCZOS sui pattern periodici oscilla, e
    # misurerebbe il filtro invece della foto
    # `codice()` toglie i commenti: LANCZOS il giudice lo NOMINA, per
    # dire perche' non lo usa, e una sentinella che legge la prosa
    # diventa rossa per colpa di una spiegazione
    prova("sentinella: si riduce con BOX, mai con LANCZOS",
          (True, False), ("Resampling.BOX" in codice(giudice),
                          "LANCZOS" in codice(giudice)))
    # i due numeri non si ribattono a mano da nessuna parte
    prova("sentinella: le due soglie sono leve, non numeri sparsi",
          (True, True), ("maxcolors=FOTO_COLORI_MIN" in giudice,
                         "<= FOTO_PIATTA_SD" in giudice))


def prove_foto_metadati():
    """NESSUNA FOTO PORTA FUORI CASA (set 2026, cantiere suo). Il GPS
    di dove e' stata scattata viaggia negli EXIF, e in un mercatino
    quello e' l'indirizzo di chi vende. La porta grande era gia' pulita
    per fortuna e non per scelta — la Mini App ridisegna tutto in un
    canvas, che i metadati non li sa nemmeno scrivere — ma l'import
    passava i byte VERBATIM, e da li' uscivano interi.
    Qui si gira la spoliazione VERA su foto vere, e si guardano le due
    cose che contano: che dopo il giro il GPS non ci sia, e che i pixel
    siano ancora identici — spogliare non e' ricomprimere, o il patto
    della compressione unica cadrebbe da un'altra parte."""
    print("\n[le foto senza metadati]")
    import base64
    import io
    import os
    import re

    try:
        from PIL import Image, ImageOps, ImageStat
        from PIL.PngImagePlugin import PngInfo
    except ImportError:
        Image = None
        salta("la spoliazione dei metadati, girata per davvero",
              "Pillow non e' installata")
    if Image:
        amb = {"io": io, "os": os, "re": re, "base64": base64,
               "ImmaginePillow": Image, "ImageOps": ImageOps,
               "ImageStat": ImageStat}
        i = _SORGENTE.index("SEGMENTI_JPEG_TENUTI = ")
        exec(_SORGENTE[i:_SORGENTE.index("\n\n\n", i)], amb)
        for f in ("_spoglia_jpeg", "_spoglia_png", "_spoglia_webp",
                  "_porta_metadati", "spoglia_metadati",
                  "converti_in_jpeg", "_e_immagine",
                  "normalizza_foto_import"):
            exec(pezzo(f), amb)
        spoglia = amb["spoglia_metadati"]

        def pixel(raw):
            """I PIXEL, non i byte: e' la misura che dice se qualcuno
            ha ricompresso di nascosto."""
            with Image.open(io.BytesIO(raw)) as im:
                return im.convert("RGB").tobytes()

        def jpeg(exif=None, **extra):
            out = io.BytesIO()
            if exif:
                extra["exif"] = exif
            foto_finta(120, 80).save(out, "JPEG", quality=90, **extra)
            return out.getvalue()

        # --- JPEG: il caso del cantiere -------------------------------
        sporco = jpeg(_exif_con_gps(), comment=b"scattata a casa")
        prova("la foto di partenza porta il GPS", 4,
              len(_gps_dentro(sporco)))
        pulito = spoglia(sporco)
        prova("la spoliazione risponde", True, pulito is not None)
        prova("...e il GPS non c'e' piu'", {}, _gps_dentro(pulito))
        prova("...ne' un solo tag EXIF", 0,
              len(dict(Image.open(io.BytesIO(pulito)).getexif())))
        prova("...ne' il commento", None,
              Image.open(io.BytesIO(pulito)).info.get("comment"))
        prova("...E I PIXEL SONO GLI STESSI (niente ricompressione)",
              pixel(sporco), pixel(pulito))
        prova("...il file e' piu' leggero, non piu' pesante", True,
              len(pulito) < len(sporco))
        prova("...e resta un JPEG che si apre", True,
              amb["_e_immagine"](pulito))
        prova("il JFIF (APP0) resta: e' di quelli che disegnano",
              b"\xff\xd8\xff\xe0", pulito[:4])
        # quel che arriva dal canvas della Mini App e' gia' nudo: non
        # deve essere toccato nemmeno di un byte
        nudo = jpeg()
        prova("un JPEG gia' nudo torna IDENTICO", nudo, spoglia(nudo))

        # --- PNG -------------------------------------------------------
        testo = PngInfo()
        testo.add_text("Comment", "scattata a casa mia")
        out = io.BytesIO()
        foto_finta(120, 80).save(out, "PNG", pnginfo=testo,
                                 exif=_exif_con_gps())
        png = out.getvalue()
        prova("il PNG di partenza porta il GPS", 4, len(_gps_dentro(png)))
        png_pulito = spoglia(png)
        prova("il PNG spogliato: niente GPS", {}, _gps_dentro(png_pulito))
        prova("...niente testo libero", {},
              getattr(Image.open(io.BytesIO(png_pulito)), "text", {}))
        prova("...e i pixel intatti", pixel(png), pixel(png_pulito))

        # --- WebP: quello dove tagliare non basta ----------------------
        webp = b""
        try:
            out = io.BytesIO()
            foto_finta(120, 80).save(out, "WEBP", quality=90,
                                     exif=_exif_con_gps())
            webp = out.getvalue()
        except Exception:
            pass
        if webp and _gps_dentro(webp):
            webp_pulito = spoglia(webp)
            prova("il WebP spogliato: niente GPS", {},
                  _gps_dentro(webp_pulito))
            prova("...e i pixel intatti", pixel(webp), pixel(webp_pulito))
            # la lunghezza del RIFF va RIFATTA, e i due bit del VP8X che
            # ANNUNCIANO i metadati vanno spenti: un contenitore che
            # dichiara quel che non ha certi lettori lo rifiutano in
            # blocco — e' il modo silenzioso in cui questa cura poteva
            # rompere le foto invece di salvarle
            prova("...e la lunghezza del RIFF torna", len(webp_pulito) - 8,
                  int.from_bytes(webp_pulito[4:8], "little"))
        else:
            salta("il WebP coi metadati", "questa Pillow non lo scrive")

        # --- cio' che non si sa spogliare ------------------------------
        out = io.BytesIO()
        foto_finta(120, 80).convert("P").save(out, "GIF")
        gif = out.getvalue()
        prova("un GIF pulito passa com'e' (non si converte per paura)",
              gif, spoglia(gif))
        prova("i byte che non si capiscono: «non lo so», mai un taglio "
              "a caso", (None, None),
              (spoglia(b"\xff\xd8\xff finto"), spoglia(b"")))

        # --- LA PORTA DEL CANTIERE: l'import verbatim ------------------
        grande = io.BytesIO()
        foto_finta(1200, 900).save(grande, "JPEG", quality=90,
                                   exif=_exif_con_gps())
        dritta = amb["normalizza_foto_import"](grande.getvalue())
        prova("L'IMPORT VERBATIM NON PORTA PIU' IL GPS", {},
              _gps_dentro(dritta))
        prova("...e non ha ricompresso: i pixel sono quelli",
              pixel(grande.getvalue()), pixel(dritta))
        # la storta passava gia' dalla conversione, ed e' l'ironia del
        # difetto: era protetta LEI e non la dritta
        storta = io.BytesIO()
        foto_finta(1200, 900).save(storta, "JPEG", quality=90,
                                   exif=_exif_con_gps(orientamento=6))
        prova("e la storta resta senza GPS, com'era gia'", {},
              _gps_dentro(amb["normalizza_foto_import"](storta.getvalue())))

    # --- SENTINELLE ---------------------------------------------------
    # le tre porte: se un riordino toglie la chiamata, la promessa cade
    # in silenzio e nessuna prova funzionale se ne accorge
    for porta in ("salva_foto", "normalizza_foto_import",
                  "_documento_busta"):
        prova(f"sentinella: {porta} spoglia ancora", True,
              "spoglia_metadati" in codice(pezzo(porta)))
    # la QUARTA porta (set 2026): l'import da Nostr scriveva raw() com'era
    # arrivato, ed era l'unica delle quattro filiere a non passare mai da
    # qui — e gira ogni ora in produzione. Due controlli, non uno: che
    # scarica_foto (in importa_nostr.py, non server.py: pezzo() non ci
    # arriva) chiami davvero il suo `pulisci`, e che il server lo INIETTI
    # davvero nel giro orario — senza il secondo, il parametro resta None
    # in silenzio e la porta si richiude senza che nessuna prova se ne
    # accorga.
    _imp_nostr = open("importa_nostr.py", encoding="utf-8").read()
    _i = _imp_nostr.index("def scarica_foto(")
    _scarica_foto_src = _imp_nostr[_i:_imp_nostr.index("\ndef ", _i)]
    prova("sentinella: scarica_foto (import Nostr) chiama pulisci", True,
          "pulisci(raw)" in codice(_scarica_foto_src))
    prova("sentinella: il server inietta il ripulitore nell'import orario",
          True, "pulisci=spoglia_metadati" in codice(_SORGENTE))
    # ESEGUIBILE, non solo sentinella: scarica_foto VERA (estratta,
    # come pezzo()/reale() fanno per server.py — mai una copia a mano
    # che diverge), su un `pulisci` finto — la logica di spoglia_metadati
    # e' gia' provata a fondo qui sopra, qui si prova solo il FILO che
    # la collega a scarica_foto: il file salvato e' il RISULTATO di
    # pulisci (mai il raw), e se pulisci si arrende NESSUN file tocca
    # il disco — la stessa cintura della foto troppo grande.
    import tempfile
    _amb_sf = {"os": os, "FOTO_DIR": None, "MAX_FOTO_BYTES": 3_000_000}
    exec(_scarica_foto_src, _amb_sf)
    with tempfile.TemporaryDirectory() as _tmp:
        _amb_sf["FOTO_DIR"] = _tmp
        _nome = _amb_sf["scarica_foto"](
            "https://esempio.tld/foto.jpg", 999, 0,
            scarica=lambda url: (b"sporcoEXIF", "image/jpeg"),
            pulisci=lambda raw: raw.replace(b"sporcoEXIF", b"pulito"))
        prova("il file salvato e' il risultato di pulisci, non il raw",
              b"pulito", open(os.path.join(_tmp, _nome), "rb").read())
        _prima = set(os.listdir(_tmp))
        _esito = _amb_sf["scarica_foto"](
            "https://esempio.tld/sporca.jpg", 998, 0,
            scarica=lambda url: (b"irriconoscibile", "image/jpeg"),
            pulisci=lambda raw: None)
        prova("pulisci che si arrende: nessun file scritto, resta l'URL",
              (None, True), (_esito, set(os.listdir(_tmp)) == _prima))
    # il ripiego di tutte e tre e' la conversione, che spoglia perche'
    # RIDISEGNA: e lo fa solo finche' nessuno le passa gli exif
    prova("sentinella: converti_in_jpeg non si riporta dietro gli EXIF",
          True, "exif=" not in codice(pezzo("converti_in_jpeg")))
    # il giudice dell'esito e' l'unico fail-CHIUSO della filiera: sul
    # dubbio dice «sporca», e chi chiama ricomprime
    prova("sentinella: sul dubbio _porta_metadati dice di si'", True,
          codice(pezzo("_porta_metadati")).rstrip().endswith("return True"))
    # e la ragione per cui la porta grande era gia' pulita: il canvas
    prova("sentinella: la Mini App ridisegna ancora nel canvas", True,
          "toDataURL('image/jpeg'" in open("miniapp.html",
                                           encoding="utf-8").read())


def prove_foto_spenta():
    """«NESSUNA» VUOL DIRE OVUNQUE, ANCHE A LUI (ago 2026, dal campo:
    «scelgo Nessuna e il bottone sembra non fare niente»).

    La diagnosi diceva che il gesto RIUSCIVA: la scelta si salvava, e in
    vetrina e nel negozio la foto spariva davvero. Restava dov'era nella
    vista PRIVATA — tappo e testata del Profilo — perche' /api/me
    mandava l'avatar GREZZO, ed era una regola scritta: «e' il tuo
    profilo, devi vedere cosa hai». Solo che il toast diceva «ovunque» e
    a due dita dal selettore la faccia era ancora li'.

    DECISIONE DI ANDREA: la regola si ROVESCIA — chi la spegne non la
    vuole. Il dato non si perde (colonna e file restano: il giudice
    nasconde in USCITA, il patto di `condizione_da_mostrare`), quindi
    riaccendendo la foto torna.

    E LA META' CHE NON ERA NEL PIANO: rovesciando, riaccendere
    diventava lo stesso difetto al contrario — il client non ha piu'
    nessun nome in mano, e quello di prima non servirebbe comunque
    perche' il rinfresco cancella il file vecchio. Da qui il si' che
    ASPETTA il social e torna col nome nuovo. Il prezzo (un bottone che
    ci mette quanto ci mette Telegram o Nostr) e' dichiarato e vale per
    un gesto raro."""
    import sqlite3, asyncio
    src = _SORGENTE
    mini = open("miniapp.html", encoding="utf-8").read()
    giu = pezzo("avatar_da_mostrare")
    end = pezzo("scegli_avatar")
    print("\n[«Nessuna» vale ovunque, anche per lui]")

    # --- IL GIUDICE, girato e non guardato -------------------------
    amb = {}
    exec(giu, amb)
    g = amb["avatar_da_mostrare"]
    prova("con 'nessuna' la foto non esce", "", g("av_ab12cd34_9.jpg",
                                                  "nessuna"))
    prova("...con l'automatico esce", "av_ab12cd34_9.jpg",
          g("av_ab12cd34_9.jpg", ""))
    prova("...con Telegram pure", "av_ab12cd34_9.jpg",
          g("av_ab12cd34_9.jpg", "telegram"))
    prova("...e con Nostr", "av_ab12cd34_9.jpg",
          g("av_ab12cd34_9.jpg", "nostr"))
    prova("chi non ha foto non ne guadagna una", "", g("", "telegram"))
    prova("il None non diventa mai 'None'", "", g(None, ""))

    # --- /api/me: era l'unica rotta che la mandava grezza ----------
    _me = pezzo("mio_profilo")
    prova("/api/me passa dal giudice", True,
          "avatar_da_mostrare(" in codice(_me))
    # ⚠️ la riga vale solo se sta DOPO il dict(u), o riscriverebbe una
    # chiave che il dict rimette grezza subito dopo
    prova("...e DOPO il dict(u), o il grezzo la ricoprirebbe", True,
          _me.index("profilo = dict(u)") < _me.index("avatar_da_mostrare("))
    # il CASE del pubblico non si tocca: sei SELECT che dicono gia' la
    # stessa cosa in SQL
    prova("il CASE del pubblico resta dov'era", True,
          src.count("avatar_scelta='nessuna' THEN ''") >= 5)

    # --- IL SI' CHE ASPETTA ----------------------------------------
    _end = codice(end)
    prova("il rinfresco si ASPETTA", True,
          "await aggiorna_profilo_social(" in _end)
    prova("...e non e' piu' un create_task che nessuno attende", False,
          "create_task(aggiorna_profilo_social" in _end)
    prova("con 'nessuna' non si aspetta niente (spegnere e' istantaneo)",
          True, 'if scelta != "nessuna":' in _end)
    prova("la risposta porta il nome del francobollo", True,
          '"avatar": avatar_da_mostrare(' in _end)
    # LA RIGA CHE VALE IL CANTIERE: rileggere PRIMA direbbe il nome di
    # ieri, cioe' un file che il rinfresco ha appena cancellato
    prova("...riletto DOPO il rinfresco", True,
          _end.index("await aggiorna_profilo_social(")
          < _end.index("SELECT avatar, nome FROM utenti"))
    # IL NOME VERO, non solo quello del francobollo (set 2026): senza
    # questa chiave nella risposta, chi passa a 'nostr' vedeva la foto
    # cambiare subito e il nome restare quello di ieri finche' non
    # ricaricava tutta la Mini App — lo stesso difetto di sopra,
    # applicato al nome invece che alla foto.
    prova("la risposta porta anche il nome vero", True,
          '"nome": r["nome"]' in _end)

    # --- IL CLIENT --------------------------------------------------
    _set = pezzo_js(mini, "async function setFotoScelta(scelta){")
    prova("il client rimette la faccia col nome che torna", True,
          "if ('avatar' in d) myAvatar = d.avatar || '';" in _set)
    # chiave assente = server di ieri: si tiene quel che c'e'
    prova("...e un server vecchio non gli svuota la faccia", True,
          "'avatar' in d" in _set)
    prova("...e rimette anche il NOME che torna", True,
          "if (d.nome) myNome = d.nome;" in _set)
    prova("ridisegna anche la testata e il tappo, non solo il cassetto",
          (True, True),
          ("renderProfilo()" in _set, "renderAvatar()" in _set))
    prova("...e la riga del cassetto su OGNI strada (anche il rifiuto)",
          True, "finally { fine(); renderIdentita();" in _set)
    prova("la bandierina para il doppio tocco", True,
          "if (fotoInCorso) return;" in _set)

    # IL VELO E' SUO, e le due esclusioni sono la regola: la ritardata
    # e' delle sole LETTURE (c'e' il censimento), e bottoneInAttesa
    # alzerebbe il velo su tutta l'app per un gesto che non muove sats
    prova("il velo e' quello suo", True, "attesaFoto(scelta)" in _set)
    prova("...e non uno dei due di casa", (False, False),
          ("attesaRitardata" in _set, "bottoneInAttesa" in _set))
    _velo = pezzo_js(mini, "function attesaFoto(scelta){")
    prova("il velo arma un timer e non tocca subito il DOM", True,
          "setTimeout(" in _velo
          and _velo.index("setTimeout(") < _velo.index("fotoStato"))
    prova("...con la soglia dello stepper, non una sua", True,
          "}, RITARDO_ATTESA);" in _velo)
    prova("...e il ripristino ANNULLA il timer (mai un velo dopo il si')",
          True, "clearTimeout(t)" in _velo)
    prova("le pillole si spengono mentre si aspetta", True,
          "pointerEvents = 'none'" in _velo)
    # i due ganci: senza, il velo non avrebbe dove posarsi
    prova("la riga della foto ha i suoi due ganci", (True, True),
          ('id="fotoStato"' in mini, 'id="fotoPillole"' in mini))

    # ================================================================
    # IL FUNZIONALE: l'endpoint VERO su un database vero
    # ================================================================
    class _H(Exception):
        def __init__(self, code, detail=""):
            self.code, self.detail = code, detail

    vero = sqlite3.connect(":memory:")
    vero.row_factory = sqlite3.Row
    vero.executescript("""
      CREATE TABLE utenti(
        tg_id INT PRIMARY KEY, negozio TEXT DEFAULT '', nome TEXT DEFAULT '',
        avatar TEXT DEFAULT '', avatar_scelta TEXT DEFAULT '',
        npub TEXT DEFAULT '', npub_verificata INT DEFAULT 0,
        npub_accesso TEXT DEFAULT '');
      INSERT INTO utenti(tg_id,negozio,nome,avatar,npub,npub_verificata)
        VALUES(111,'ab12cd34','Ada','av_ab12cd34_100.jpg','npub1zz',1);
      -- chi una npub non l'ha: la gamba Nostr non gli si offre
      INSERT INTO utenti(tg_id,negozio,nome) VALUES(222,'cd34ab12','Bruno');
      -- il nativo Nostr: una chat Telegram non ce l'ha
      INSERT INTO utenti(tg_id,negozio,nome,npub_accesso)
        VALUES(-5,'ef56ab78','Nativo','npub1qq');
    """)
    vero.commit()

    class Con:
        def execute(self, q, p=()):
            return vero.execute(q, p)

        def commit(self):
            vero.commit()

        def close(self):
            pass

    class _Req:
        def __init__(self, d):
            self._d = d

    async def _leggi(req):
        return req._d

    social = []

    async def _rinfresca(tg_id):
        """Il download vero: scrive un nome NUOVO, come _scrivi_avatar
        (i nomi sono versionati). Se la risposta lo leggesse PRIMA,
        direbbe ancora quello di ieri — ed e' cio' che questa finta
        rende visibile."""
        social.append(tg_id)
        vero.execute("UPDATE utenti SET avatar=? WHERE tg_id=?",
                     ("av_ab12cd34_200.jpg", tg_id))
        vero.commit()

    def scegli(scelta, chi=111):
        amb = {"db": Con, "HTTPException": _H, "Request": object,
               "Header": lambda d="": d, "Cookie": lambda d="": d,
               "verifica_utente": lambda h, s: {"id": chi},
               "leggi_json": _leggi,
               "aggiorna_profilo_social": _rinfresca}
        exec(giu, amb)
        exec("async " + end, amb)
        try:
            return asyncio.new_event_loop().run_until_complete(
                amb["scegli_avatar"](_Req({"scelta": scelta})))
        except _H as e:
            return f"{e.code} {e.detail}"

    def riga():
        return vero.execute("SELECT avatar, avatar_scelta FROM utenti "
                            "WHERE tg_id=111").fetchone()

    social.clear()
    r = scegli("nessuna")
    prova("spegnere: la risposta non porta nessuna foto",
          {"ok": True, "scelta": "nessuna", "avatar": "", "nome": "Ada"}, r)
    prova("...e non si e' chiesto niente al social", [], social)
    prova("...ma il file resta in dispensa: riaccendendo torna",
          "av_ab12cd34_100.jpg", riga()["avatar"])

    social.clear()
    r = scegli("telegram")
    prova("riaccendere: si va a chiedere al social", [111], social)
    # LA PROVA REGINA: e' il nome NUOVO, non quello di ieri
    prova("...e la risposta porta la foto NUOVA",
          {"ok": True, "scelta": "telegram",
           "avatar": "av_ab12cd34_200.jpg", "nome": "Ada"}, r)
    prova("...che e' anche quella in colonna", "av_ab12cd34_200.jpg",
          riga()["avatar"])

    # LE GUARDIE DI SEMPRE NON SI SONO ALLENTATE — e i due casi
    # vogliono utenti VERI: col tg_id di uno che nel cartone non
    # c'e', l'endpoint risponde 404 «Profilo non trovato» e la
    # prova passerebbe per la ragione sbagliata.
    prova("chi non ha una npub non puo' sceglierla", True,
          str(scegli("nostr", chi=222)).startswith("400 Prima"))
    prova("...e il nativo Nostr non ha una chat Telegram", True,
          str(scegli("telegram", chi=-5)).startswith("400 Questo"))
    prova("...e la scelta sconosciuta si rifiuta ancora", True,
          str(scegli("faccina")).startswith("400 Scelta"))
    # e nessuno dei tre rifiuti ha toccato il social
    prova("un rifiuto non va a chiedere niente a nessuno", [],
          social[1:])


def prove_foto_telegram_fallita():
    """IL BOTTONE «TELEGRAM» NON DEVE CANCELLARE UNA FOTO BUONA (set
    2026, dal campo di Andrea): l'account aveva la foto vera di
    Telegram fin dall'inizio, e' passato a Nostr (funzionava), poi e'
    tornato su Telegram — e li' e' rimasto senza foto per niente, ne'
    Telegram ne' Nostr.

    LA CAUSA: `_foto_profilo_telegram` restituiva un solo None sia per
    «Telegram ha risposto: la foto non c'e'» sia per «l'API o la rete
    non hanno risposto», e la scelta ESPLICITA (senza ripiego su Nostr,
    voce di `aggiorna_profilo_social`) scriveva '' in colonna in
    entrambi i casi: un intoppo di un istante bastava a cancellare una
    foto che c'era davvero.

    LA CURA distingue i due casi: b'' = Telegram ha risposto per bene e
    conferma zero foto (si scrive '', e' la scelta senza ripiego che
    l'utente ha chiesto); None = non si sa (rete o API a vuoto), e
    l'avatar che gia' c'era non si tocca."""
    import asyncio
    print("\n[il bottone Telegram non cancella una foto buona per un intoppo]")

    # --- _foto_profilo_telegram distingue i tre casi -----------------
    ft = pezzo("_foto_profilo_telegram")

    def chiama(risposta):
        async def _bot_api(metodo, dati):
            return risposta
        amb = {"bot_api": _bot_api, "AVATAR_LATO": 128, "BOT_TOKEN": "x",
               "httpx": None}
        exec("async " + ft, amb)
        return asyncio.new_event_loop().run_until_complete(
            amb["_foto_profilo_telegram"](111))

    prova("rete/API a vuoto: non si sa (None), non e' un 'non ce l'ha'",
          None, chiama(None))
    prova("Telegram risponde ok=False (es. 429): idem, None", None,
          chiama({"ok": False, "error_code": 429}))
    prova("Telegram conferma zero foto: b'' e non None",
          b"", chiama({"ok": True,
                      "result": {"total_count": 0, "photos": []}}))

    # --- aggiorna_profilo_social: il None esplicito non scrive nulla -
    agg = pezzo("aggiorna_profilo_social")

    def mondo(esito_telegram):
        riga = {"negozio": "ab12cd34", "avatar": "av_ab12cd34_100.jpg",
                "npub": "", "npub_verificata": 0, "npub_accesso": "",
                "avatar_scelta": "telegram"}

        class _Con:
            def execute(self, q, p=()):
                return self

            def fetchone(self):
                return dict(riga)

            def close(self):
                pass

        scritture = []

        async def _foto_tg(tg_id):
            return esito_telegram

        async def _foto_ns(profilo):
            return None

        async def _prof_ns(npub):
            return {}

        amb = {"db": lambda: _Con(), "_AVATAR_IN_CORSO": set(),
               "_profilo_nostr": _prof_ns,
               "_scrivi_nome_nostr": lambda tg_id, nome: None,
               "nome_da_profilo": lambda profilo: "",
               "_foto_profilo_telegram": _foto_tg,
               "_foto_profilo_nostr": _foto_ns,
               "_scrivi_avatar": lambda tg_id, nome: scritture.append(nome),
               "_salva_avatar": lambda negozio, raw:
                   ("av_ab12cd34_NUOVA.jpg" if raw else ""),
               "print": lambda *a, **k: None}
        exec("async " + agg, amb)
        asyncio.new_event_loop().run_until_complete(
            amb["aggiorna_profilo_social"](111))
        return scritture

    prova("rete giu': non si scrive NIENTE, la foto buona resta",
          [], mondo(None))
    prova("Telegram conferma zero foto: si scrive '' (senza ripiego)",
          [""], mondo(b""))
    prova("Telegram risponde con la foto: si scrive quella nuova",
          ["av_ab12cd34_NUOVA.jpg"], mondo(b"jpegfinto"))


def prove_nome_da_nostr():
    """IL NOME SEGUE LA FOTO (set 2026, chiesto da Andrea: «quando un
    utente aggiorna il profilo da Nostr o da Telegram, deve prendere
    la foto e anche il nome»). Prima `_scrivi_nome_nostr` si arrendeva
    su OGNI tg_id positivo — «comanda Telegram», diceva il commento,
    ma quello riscrive il nome SOLO a chi la Mini App la riapre
    davvero: chi vive di sessione web restava fermo al nome della
    prima registrazione per sempre, qualunque profilo aggiornasse.
    Ora scrive anche li', ma SOLO con la scelta 'nostr' esplicita:
    mai in automatico, perche' Telegram un nome ce l'ha SEMPRE (a
    differenza della foto) — l'automatico non sarebbe un ripiego ma
    uno sfarfallio a ogni giro."""
    print("\n[il nome segue la scelta della foto]")
    import sqlite3
    import time as _time

    def con_utenti():
        c = sqlite3.connect(":memory:")
        c.row_factory = sqlite3.Row
        c.executescript("""
        CREATE TABLE utenti(tg_id INTEGER PRIMARY KEY, nome TEXT,
          username TEXT DEFAULT '', avatar_scelta TEXT DEFAULT '',
          registrato INTEGER DEFAULT 0, negozio TEXT DEFAULT '');
        INSERT INTO utenti VALUES(-1,'npub1abc…','','',0,'nat1');
        INSERT INTO utenti VALUES(111,'Mario (Telegram)','mario','',0,'mar1');
        INSERT INTO utenti VALUES(222,'Luigi (Telegram)','luigi','nostr',0,'lui1');
        """)
        return c

    class _SenzaClose2:
        def __init__(self, c): self._c = c
        def __getattr__(self, n): return getattr(self._c, n)
        def close(self): pass

    # --- _scrivi_nome_nostr: ORA scrive anche sui tg_id positivi ----
    def scrivi_nome(con, tg_id, nome):
        amb = {"db": lambda: _SenzaClose2(con), "time": _time}
        exec(pezzo("_scrivi_nome_nostr"), amb)
        amb["_scrivi_nome_nostr"](tg_id, nome)

    c = con_utenti()
    scrivi_nome(c, -1, "Nome Nativo")
    prova("nativo Nostr: scrive come sempre", "Nome Nativo",
          c.execute("SELECT nome FROM utenti WHERE tg_id=-1").fetchone()[0])
    scrivi_nome(c, 111, "Nome Da Nostr")
    prova("tg_id positivo: ORA scrive (prima si arrendeva sempre)",
          "Nome Da Nostr",
          c.execute("SELECT nome FROM utenti WHERE tg_id=111").fetchone()[0])
    scrivi_nome(c, -1, "")
    prova("nome vuoto (kind-0 muto): non tocca niente", "Nome Nativo",
          c.execute("SELECT nome FROM utenti WHERE tg_id=-1").fetchone()[0])

    # --- _upsert_da_telegram: protegge SOLO chi ha scelto 'nostr' ---
    def upsert(con, tg_id, nome, username):
        amb = {"time": _time, "nuovo_codice_negozio": lambda con: "zz00zz00"}
        exec(pezzo("_upsert_da_telegram"), amb)
        amb["_upsert_da_telegram"](con, tg_id, nome, username)

    c = con_utenti()
    upsert(c, 111, "Mario (da Telegram ORA)", "mario_tg")
    prova("automatico (''): Telegram vince sempre, come sempre",
          "Mario (da Telegram ORA)",
          c.execute("SELECT nome FROM utenti WHERE tg_id=111").fetchone()[0])
    upsert(c, 222, "Luigi (da Telegram ORA)", "luigi_tg")
    prova("scelta 'nostr': Telegram NON sovrascrive piu' il nome",
          "Luigi (Telegram)",
          c.execute("SELECT nome FROM utenti WHERE tg_id=222").fetchone()[0])
    prova("...ma lo username si aggiorna comunque (Nostr non ne ha uno)",
          "luigi_tg",
          c.execute("SELECT username FROM utenti WHERE tg_id=222").fetchone()[0])

    # --- SENTINELLA: le tre porte passano tutte dalla stessa scrittura
    for porta in ("upsert_utente", "verifica_utente"):
        prova(f"sentinella: {porta} passa da _upsert_da_telegram", True,
              "_upsert_da_telegram(" in pezzo(porta))

    # --- il chiamante di aggiorna_profilo_social: il nome si chiede
    #     solo se tg_id<0 o scelta=='nostr', mai in automatico -------
    import asyncio

    def mondo(tg_id, scelta):
        riga = {"negozio": "ab12cd34", "avatar": "", "npub": "npub1x",
                "npub_verificata": 1, "npub_accesso": "",
                "avatar_scelta": scelta}

        class _Con:
            def execute(self, q, p=()):
                return self

            def fetchone(self):
                return dict(riga)

            def close(self):
                pass

        chiamate = []

        async def _prof_ns(npub):
            return {"name": "NomeDaiRelay"}

        async def _foto_tg(tg_id):
            return None

        async def _foto_ns(profilo):
            return None

        amb = {"db": lambda: _Con(), "_AVATAR_IN_CORSO": set(),
               "_profilo_nostr": _prof_ns,
               "_scrivi_nome_nostr": lambda tg_id, nome: chiamate.append(nome),
               "nome_da_profilo": lambda profilo: profilo.get("name", ""),
               "_foto_profilo_telegram": _foto_tg,
               "_foto_profilo_nostr": _foto_ns,
               "_scrivi_avatar": lambda tg_id, nome: None,
               "_salva_avatar": lambda negozio, raw: "",
               "print": lambda *a, **k: None}
        exec("async " + pezzo("aggiorna_profilo_social"), amb)
        asyncio.new_event_loop().run_until_complete(
            amb["aggiorna_profilo_social"](tg_id))
        return chiamate

    prova("nativo Nostr (tg_id<0): il nome si chiede sempre",
          ["NomeDaiRelay"], mondo(-1, ""))
    prova("tg_id>0, automatico: il nome NON si chiede (Telegram vince "
          "gia')", [], mondo(111, ""))
    prova("tg_id>0, 'telegram' esplicito: idem, nessuna chiamata",
          [], mondo(111, "telegram"))
    prova("tg_id>0, 'nostr' esplicito: ORA il nome si chiede",
          ["NomeDaiRelay"], mondo(111, "nostr"))

    # --- il client dice che il nome segue, solo quando e' vero ------
    mini = open("miniapp.html", encoding="utf-8").read()
    prova("il client avvisa SOLO quando Nostr governa anche il nome",
          True, "Anche il tuo nome viene da lì." in mini
          and "attivaFoto === 'nostr' && tgFotoOk" in mini)


def prove_duplica_annuncio():
    """IL DUPLICATO (ago 2026, chiesto da Andrea): si ricalca un
    proprio annuncio invece di ricompilare tutto, e i tre campi che
    quasi sempre cambiano — titolo, prezzo, foto — arrivano gia'
    pieni. Le foto le copia il SERVER dai file: qui si gira il pezzo
    vero su una cartella usa-e-getta, perche' la cosa che conta —
    che i byte del pieno siano IDENTICI, cioe' nessuna seconda
    compressione — una sentinella sulla forma non la puo' dire."""
    print("\n[il duplicato]")
    import io
    import json
    import re
    import sqlite3
    import tempfile

    try:
        from PIL import Image, ImageOps, ImageStat
    except ImportError:
        salta("la copia delle foto, girata per davvero",
              "Pillow non e' installata")
    else:
        with tempfile.TemporaryDirectory() as tmp:
            amb = {"os": os, "io": io, "re": re, "json": json,
                   "ImmaginePillow": Image, "ImageOps": ImageOps,
                   "ImageStat": ImageStat, "FOTO_DIR": tmp}
            i = _SORGENTE.index("MINIATURA_LATO = ")
            exec(_SORGENTE[i:_SORGENTE.index("\n\n\n", i)], amb)
