    # ---- 25-31: le offerte ----------------------------------------
    TRE = "('proposta','controproposta','accettata')"
    prova("le offerte vive si leggono sui tre stati", True,
          f"AND stato IN {TRE}" in ric)
    # HA CAMBIATO LATO (ago 2026, l'offerta sul carrello): le
