    for morto in ("cat-share", "catShare", "renderCondividiCategoria"):
        prova(f"del bottone non resta niente: «{morto}»", 0,
              testo_mini.count(morto))

    # IL GESTO E' DELEGATO SULLA STRISCIA, e non poteva essere
