    pd = pezzo_js(testo_mini, "fila.addEventListener('pointerdown'", "});")
    prova("ogni gesto nuovo riparte pulito", True,
          "premutaFatta = false;" in pd)

    # IL MENU DEL SISTEMA. La card e' un `<a>` VERO (i crawler devono
