    prova("la WHERE dice spedito + via punto + busta vuota", True,
          "OR o.stato='shipped' AND o.via_punto=1 " in c
          and "AND o.busta_il=0)" in c)
    # ...e si guarda il CORPO e non la funzione intera: la docstring
