    prova("...e il tetto non e' scritto a mano", True,
          "SOLLECITO.max" in g and not re.search(r">=\s*3\b", g))

    # --- 12) IL BOTTONE SPENTO DICE PERCHE' ----------------------
    # Sparire non e' gratis: dal campo, un bottone che c'era e un
