    prova("del logo non resta niente", (0, 0, 0),
          (mini.count("rac-logo"), mini.count("rac-nome"),
           _rn.count("rac-logo")))

    # ---- 3d. I TRE PUNTI E LE QUATTRO TAPPE ---------------------
    # I PUNTI SI CONTORNANO (ago 2026, decisione di Andrea): il
