    prova("i tre punti sono contornati", True,
          "border:1.5px solid var(--field-line)" in _rp
          and "border-radius:" in _rp and "padding:" in _rp)
    # ...E LA SUPERFICIE E' NEUTRA, che e' la meta' da non ammorbidire:
