    prova("...e non prendono nessun colore parlante", (0, 0, 0, 0),
          (_rp.count("--trust"), _rp.count("--sats"),
           _rp.count("--lampo"), _rp.count("--sconto")))
    # LE TAPPE PRENDONO IL PALLINO (ago 2026, decisione di Andrea): la
