    _blo = re.findall(r"\{t: '(\w+)'(?:, n: (\d))?", _cat)
    prova("i blocchi del racconto stanno nell'ordine deciso",
          [("testo", ""), ("foto", "2"), ("testo", ""),
           ("punti", ""), ("foto", "4"), ("tappe", ""),
           ("foto", "1"), ("elenco", ""), ("foto", "3")],
          _blo)

    # ---- 3f. LA TRUST-LINE E' USCITA DAL NEGOZIO ----------------
    # ⚠️ (ago 2026, decisione di Andrea): «Ogni acquisto e' protetto
