    prova("...ma quella di Esplora c'e' ancora", 1,
          mini.count('class="trust-line"'))
    prova("...ed e' quella che il tour cerca", True,
          "#view-esplora .trust-line" in mini)

    # ---- 3g. LE DUE PROMESSE, SOTTO LA VETRINA ------------------
