    def blocco_media(testa):
        """il corpo di un @media, dalla sua testa alla graffa che lo
        chiude: si conta dalla PRIMA graffa, quella del @media — la testa
        puo' portarsene dietro altre, e contarle da dopo la sbilancerebbe"""
        i = css.find(testa)
        if i < 0:
            return ""
        j, fondo = css.index("{", i) + 1, 1
        while fondo and j < len(css):
            fondo += {"{": 1, "}": -1}.get(css[j], 0)
            j += 1
        return css[i:j]

    def _regola(testo, firma, fine="}"):
        """una regola CSS per firma, o niente: una firma che non c'e' piu'
        da' le rosse col loro nome, e non l'esplosione della sezione"""
        return pezzo_js(testo, firma, fine) if firma in testo else ""

    # --- 1) IL FILE: la SOLA freccia, su trasparente, 138x35 (3x di 46) --
