    raw = open(FILE, "rb").read()
    prova("la freccia e' un WebP", (b"RIFF", b"WEBP"), (raw[:4], raw[8:12]))
    pezzi, i = [], 12
    while i + 8 <= len(raw):
        n = _st.unpack("<I", raw[i + 4:i + 8])[0]
        pezzi.append(raw[i:i + 4].decode("ascii", "replace"))
        i += 8 + n + (n & 1)
