    def _px(testo, proprieta):
        m = re.search(re.escape(proprieta) + r":\s*(-?[\d.]+)px", testo)
        return float(m.group(1)) if m else None
    _casa = _regola(mini, "  nav button.sell .ic{\n", "}")
