    def _lum(h):
        c = [int(h[k:k + 2], 16) / 255 for k in (1, 3, 5)]
        c = [x / 12.92 if x <= 0.03928 else ((x + 0.055) / 1.055) ** 2.4
             for x in c]
        return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]

    def _contrasto(a, b):
        la, lb = sorted((_lum(a), _lum(b)), reverse=True)
        return (la + 0.05) / (lb + 0.05)
