    def riga(oid):
        r = con.execute("SELECT tg_id, preso_da, maker, stato FROM p2p_ordini "
                        "WHERE ordine=?", (oid,)).fetchone()
        return (r["tg_id"], r["preso_da"], r["maker"], r["stato"])

