              " ? {remove(){ fatti.push('via'); }} : null};\n"
              + pezzo_js(mini, "function togliGuscio(){", "\n}\n") + "\n}\n"
              + "const passo = () => { const c = coda; coda = [];"
              " c.forEach(f => f()); return [...fatti]; };\n"
